-- ── Recalculate pip_cost for reSpec force abilities ─────────────────────
UPDATE ref_force_abilities
SET pip_cost = GREATEST(
  1,
  (
    CHAR_LENGTH(COALESCE(description, ''))
    - CHAR_LENGTH(REPLACE(COALESCE(description, ''), '[FP]', ''))
  ) / 4
)
WHERE dataset_source = 'respec';

-- ── Mark OggDude-only talents as retired ────────────────────────────────
UPDATE ref_talents
SET is_retired = true
WHERE dataset_source = 'oggdude'
  AND key IN ('ALTDEAL', 'BYBOOK', 'COMARMS', 'DISCLORE', 'DISCSOUL', 'DISSTRIKE', 'EXTREACH', 'FEARREP', 'IMPCOMARMS', 'IMPPRIDEJOY', 'IMPSECRETJEDI', 'INSPLEAD', 'KNOWENEMY', 'KNOWROPES', 'MOSTIMP', 'PERSTARGINT', 'PREPBOARD', 'PRIDEJOY', 'SECRETJEDI', 'SEENTHINGS', 'SUPPRIDEJOY', 'TARGFIRE', 'TEMPTRAIN', 'TRUSTCAP', 'TRUSTNO');
