INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ADV', 'Adversary', 'Upgrade the difficulty of any combat check targeting this character once per rank of Adversary.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ANAT', 'Anatomy Lessons', 'After making a successful attack with a personal weapon, may spend 1 Destiny Point to add damage equal to Intellect to one hit.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ARM', 'Armor Master', 'When wearing armor, increase total soak value by 1.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ARMIMP', 'Armor Master (Improved)', 'When wearing armor with a soak value of 2 or higher, increase defense by 1.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BADM', 'Bad Motivator', 'Once per session, may take a Bad Motivator action; make a [B]Hard ([DI][DI][DI]) Mechanics check[b]. If successful, one device (subject to GM''s approval) spontaneously fails due to the character''s involvement, or because it was about to fail anyway and the character noticed it (this is the character''s decision)', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BACT', 'Bacta Specialist', 'Patients under the character''s supervision heal one additional wound per rank of Bacta Specialist each time they heal a wound while recovering in a bacta tank or under supervised medical conditions or long-term care.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BAL', 'Balance', 'When the character recovers strain at the end of the encounter, he may add [FO] per Force rating. He recovers additional strain equal to [LI] generated.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BAR', 'Barrage', 'Add 1 damage per rank of Barrage to one hit of successful Ranged (Heavy) or Gunnery attacks with non-starship/vehicle weapons at long or extreme range.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BLA', 'Black Market Contacts', 'When looking to purchase illegal, exotic, or black market goods, the character may decrease an item''s rarity by one level per rank in Black Market Contacts. For each level an item''s rarity is decreased, its cost increases by 50% of its base cost.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BLO', 'Blooded', 'Add [BO] per rank of Blooded to all checks to resist or recover from the effects of poisons, venoms, and other toxins. Reduce duration of ongoing poisons by 1 round per rank of Blooded to a minimum of 1.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BRA', 'Brace', 'Perform the Brace maneuver to remove [SE] per rank of Brace from next skill check based on changing conditions, inclement weather, unstable surfaces, zero gravity, heavy gravity, or other disruptive physical obstacles that would make a skill check more difficult.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BRI', 'Brilliant Evasion', 'Once per encounter may take Brilliant Evasion action. Select 1 opponent and make Opposed Piloting (Planetary or Space) check to stop opponent from attacking character for rounds equal to Agility.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BYP', 'Bypass Security', 'Remove [SE] per rank of Bypass Security from Skulduggery and Computers checks made to disable a security device or open a locked door.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COD', 'Codebreaker', 'Remove [SE] per rank in Codebreaker from checks to break codes or decrypt communications. Decrease difficulty of Computers and Intellect checks to break codes or decrypt communications by 1 (this does NOT increase with additional ranks of codebreaker).', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COM', 'Command', 'Add [BO] per rank of Command when making Leadership checks (or other checks to inspire, lead, or rally an audience). Affected targets add [BO] to Discipline checks for next 24 hours (this does not increase with additional ranks of Command)', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CONF', 'Confidence', 'May decrease difficulty of Discipline checks to avoid fear by 1 per rank of Confidence. If difficulty goes to 0, he does not have to make a check.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CONT', 'Contraption', 'Once per session, take Contraption action; make a [B] Hard ([DI][DI][DI]) Mechanics check[b] to fashion a device to solve a current problem using just the tools and parts on hand. This device must be approved by the GM and functions for the duration of the current encounter only. Those tools are destroyed in the process. [TR] may be spent to allow the tools to be recovered to be reused later.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CONV', 'Convincing Demeanor', 'Remove [SE] per rank of Convincing Demeanor from any Deception or Skulduggery checks.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CRIPV', 'Crippling Blow', 'Increase the difficulty of next combat check by 1. If check succeeds and deals damage, target suffers 1 strain whenever he moves for the remainder of the encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DEAD', 'Dead to Rights', 'Spend 1 Destiny Point to add additional damage equal to half Agility (rounded up) to one hit of successful attack made with ship or vehicle-mounted weaponry.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DEADIMP', 'Dead to Rights (Improved)', 'Spend 1 Destiny Point to add additional damage equal to Agility (rounded up) to one hit of successful attack made with ship or vehicle-mounted weaponry.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DEADACC', 'Deadly Accuracy', 'When acquired, choose 1 combat skill. Add damage equal to ranks in that skill to one hit of successful attack made using that skill while using a non-starship/vehicle weapon. He cannot choose the same combat skill twice.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DEDI', 'Dedication', 'Gain +1 to a single characteristic. This cannot bring a characteristic above 6.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DEFDRI', 'Defensive Driving', 'Increase defense of vehicle or starship being piloted by 1 per rank of Defensive Driving.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DEFSLI', 'Defensive Slicing', 'When defending computer systems (or when an opponent attempts to slice a computer owned or programmed by the character), add [SE] per rank of Defensive Slicing to opponent''s checks.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DEFSLIIMP', 'Defensive Slicing (Improved)', 'Defensive Slicing now upgrades opponents'' difficulty once per rank of Defensive Slicing, this replaces the usual benefits.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DEFSTA', 'Defensive Stance', 'Once per round, may perform Defensive Stance maneuver and suffer a number of strain to upgrade difficulty of all incoming melee attacks by an equal number until the start of the character''s next turn. Strain suffered this way cannot exceed ranks in Defensive Stance.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DISOR', 'Disorient', 'After hitting with combat check, may spend [AD][AD] to disorient target for number of rounds equal to ranks in Disorient. Disoriented targets add [SE] to all skill checks.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DODGE', 'Dodge', 'When targeted by combat check, may perform a Dodge incidental to suffer a number of strain no greater than ranks of Dodge, then upgrade the difficulty of the check by that number.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DURA', 'Durable', 'May reduce any Critical Injury suffered by 10 per rank of Durable to a minimum of 1.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ENDUR', 'Enduring', 'Gain +1 soak value.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EXTRACK', 'Expert Tracker', 'Remove [SE] per rank of Expert Tracker from checks to find tracks or track targets. Survival checks made to track targets take 50% less time than normal (this does not decrease with additional ranks of Expert Tracker).', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FAMSUNS', 'Familiar Suns', 'Once per session, may perform a Familiar Suns maneuver; make a [B] Hard ([DI][DI][DI]) Knowledge (Outer Rim)[b] or [B](Core Worlds) check[b] to reveal the current type of planetary environment, whether the planet is likely to be inhabited and, if so, where habitation could be found. He also knows about environmental effects, hostile predators, or potential base locations.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FERSTR', 'Feral Strength', 'Add 1 damage per rank of Feral Strength to one hit of successful attacks made using Brawl or Melee skills.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FLDCOMM', 'Field Commander', 'Take the Field Commander action; make an [B]Average ([DI][DI]) Leadership check[b]. A number of allies equal to Presence may immediately suffer 1 strain to perform 1 free maneuver. This does not count towards their two maneuvers this round. If there are any questions as to the order in which allies act, the character using Field Commander is the final arbiter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FLDCOMMIMP', 'Field Commander (Improved)', 'Field Commander action affects allies equal to double Presence, and may spend [TR] to allow one ally to suffer 1 strain to perform 1 free action instead of a maneuver.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FINETUN', 'Fine Tuning', 'When repairing system strain on a starship or vehicle, repair 1 additional system strain per rank of Fine Tuning.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FORAG', 'Forager', 'Remove up to [SE][SE] from skill checks to find food, water, or shelter, Survival checks to forage take half the time.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FORCERAT', 'Force Rating', 'Gain +1 Force Rating.', 'taPassive', true, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FRENZ', 'Frenzied Attack', 'When making a Melee or Brawl check, suffer a number of strain to upgrade the attack an equal number of times. The strain suffered may not exceed ranks in Frenzied Attack.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FULLTH', 'Full Throttle', 'Take a Full Throttle action; make a [B]Hard ([DI][DI][DI]) Piloting check[b] to increase a vehicle''s top speed by 1 for a number of rounds equal to Cunning. The ship still cannot perform actions or maneuvers it could not perform normally (e.g., actions that have a minimum speed requiremen).', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FULLTHIMP', 'Full Throttle (Improved)', 'Suffer 1 strain to attempt Full Throttle as a maneuver and decrease its difficulty to [B]Average ([DI][DI])[b].', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FULLTHSUP', 'Full Throttle (Supreme)', 'When performing Full Throttle, top speed increases by 2 instead of 1.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GALMAP', 'Galaxy Mapper', 'Remove [SE] per rank of Galaxy Mapper from Astrogation checks. Astrogation checks take 50% less time (this does not decrease with additional ranks of Galaxy Mapper).', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GEARHD', 'Gearhead', 'Remove [SE] per rank of Gearhead from Mechanics checks. Credits cost to add mods to attachments decreases by 50% (this does not stack with additional ranks of Gearhead).', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GRIT', 'Grit', 'Gain +1 strain threshold.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HARDHD', 'Hard Headed', 'When staggered or disoriented, perform the Hard Headed action; make a  [B]Daunting ([DI][DI][DI][DI]) Discipline check[b] to remove status. Difficulty reduced per additional rank of Hard Headed, to a minimum of [B]Easy ([DI])[b].', 'taAction', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HARDHDIMP', 'Hard Headed (Improved)', 'The character may use the Hard Headed action to recover from being incapacitated due to exceeding their strain threshold. On their next turn after being incapacitated, the character may make a [B]Formidable ([DI][DI][DI][DI][DI]) Discipline check[b]. If the check is successful, they decrease their strain to one below their strain threshold. The difficulty of this check decreases by one per rank of Hard Headed after the first, to a minimum of [B]Easy ([DI])[b].', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HEIGHT', 'Heightened Awareness', 'Allies within short range add [BO] to Perception or Vigilance checks. Engaged allies add [BO] [BO].', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HERO', 'Heroic Fortitude', 'May spend 1 Destiny Point to ignore effects of Critical Injuries on Brawn or Agility checks until the end of the encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HIDD', 'Hidden Storage', 'Gain hidden storage in vehicle or equipment that holds items with a total encumbrance equal to ranks in Hidden Storage. Checks to detect these compartments have a [B]Formidible ([DI][DI][DI][DI][DI]) difficulty.[b]', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HOLDTOG', 'Hold Together', 'Spend 1 Destiny Point to perform a Hold Together incidental immediately after vehicle or starship he has repaired this encounter takes damage resulting in hull trauma. The character explains why the apparently serious damage was in fact superficial, and the damage from the attack becomes system strain instead.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HUNT', 'Hunter', 'Add [BO] per rank of Hunter to all checks when interacting with beast or animals (including combat checks). Add +10 to Critical Injury results against beasts or animals per rank of Hunter.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INDIS', 'Indistinguishable', 'The character''s appearance is so common that people have a hard time identifying distinguishing traits. Opposing characters upgrade the difficulty of any checks made to identify them once per rank of Indistinguishable', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INSIGHT', 'Insight', 'Perception and Discipline become career skills.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INSPRHET', 'Inspiring Rhetoric', 'Take the Inspiring Rhetoric action; make an [B]Average ([DI][DI]) Leadership check[b]. For each [SU], 1 ally within close range recovers 1 strain. Spend [AD] to cause 1 affected ally to recover 1 additional strain.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INSPRHETIMP', 'Inspiring Rhetoric (Improved)', 'Each ally affected by Inspiring Rhetoric gains [BO] on all skill checks for a number of rounds equal to ranks in Leadership; this does not stack with itself.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INSPRHETSUP', 'Inspiring Rhetoric (Supreme)', 'The character may volentarily suffer 1 strain to perform Inspiring Rhetoric as a maneuver instead of an action.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INTENSFOC', 'Intense Focus', 'Perform an Intense Focus maneuver; suffer 1 strain and upgrade the ability of the next skill check once.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INTENSPRE', 'Intense Presence', 'Spend 1 Destiny Point to recover strain equal to Presence rating.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INTIM', 'Intimidating', 'May suffer a number of strain to downgrade difficulty of Coercion checks, or upgrade difficulty when targeted by Coercion checks, by an equal number. Strain suffered this way cannot exceed ranks in Intimidating.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INVENT', 'Inventor', 'When constructing new items or modifying existing attachments, add [BO] or remove [SE] per rank of Inventor.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('JUMP', 'Jump Up', 'Once per round, may stand from seated or prone as an incidental.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('JURY', 'Jury Rigged', 'Choose 1 weapon, armor, or other item and give it a permanent improvement while it remains in use.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KILL', 'Kill With Kindness', 'Remove [SE] per rank of Kill with Kindness from all Charm and Leadership checks.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOCK', 'Knockdown', 'After hitting with a melee attack, may spend [TR] to knock the target prone. If the target is larger than the acting character, it requires one additional [TR] for each silhouette larger.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWSOM', 'Know Somebody', 'Once per session, when attempting to purchase a legally available item, reduce its rarity by 1 per rank of Know Somebody.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWSPEC', 'Knowledge Specialization', 'When acquired, choose 1 Knowledge skill. When making that skill check, may spend [TR] result to gain additional [SU] equal to ranks in Knowledge Specialization.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWSCH', 'Known Schematic', 'Once per session, may perform the Known Schematic maneuver; make a [B]Hard ([DI][DI][DI]) Knowledge (Education) check[b]. Success grants familiarity with a building or capital ship''s design. He now knows the location of critical components or facilities within the ship or vehicle, as well as his own location. He can also plan unconventional routes around obstacles. Additional [SU], [AD], or [TR] results can reveal other useful information at the GM''s discretion.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LETSRIDE', 'Let''s Ride', 'Once per round on the character''s turn, may mount or dismount a vehicle or beast, or enter a cockpit or weapon station on a vehicle, as an incidental instead of a maneuver.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LETHALBL', 'Lethal Blows', 'Add +10 per rank of Lethal Blows to any Critical Injury results inflicted on opponents.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASDOC', 'Master Doctor', 'Once per round, suffer 2 strain to decrease the difficulty of a Medicine check by 1 to a minimum of [B]Easy ([DI]).[b]', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASMERC', 'Master Merchant', 'When buying or selling goods, or paying off or taking Obligation, may suffer 2 strain to sell for 25% more, buy for 25% less, pay off 1 more Obligation, or take 1 less.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASSHAD', 'Master of Shadows', 'Once per round, suffer 2 strain to decrease difficulty of the next Stealth or Skulduggery check by one to a minimum of [B]Easy ([DI])[b].', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASPIL', 'Master Pilot', 'Once per round when piloting a starship, may suffer 2 strain to perform any action as a maneuver instead.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASSLIC', 'Master Slicer', 'Once per round, may take a Master Slicer incidental to suffer 2 strain and decrease difficulty of the next Computers or other slicing-related check by 1 to a minimum of [B]Easy ([DI])[b].', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
