INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NOBFOOL', 'Nobody''s Fool', 'May upgrade difficulty of incoming Charm, Coercion, or Deception checks once per rank of Nobody''s Fool.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('OUTDOOR', 'Outdoorsman', 'Remove [SE] per rank of Outdoorsman from checks to move through terrain or manage environmental effects. Decrease overland travel times by half (this does not decrease with additional ranks of Outdoorsman).', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('OVEREM', 'Overwhelm Emotions', 'May add [FO] per Force Rating to Charm, Coercion, or Deception checks. Each [LI] adds [SU] to charm checks. Each [DA] adds [SU] to Coercion or Deception checks. However, every [LI][LI] add [FA] to Coercion and Deception checks and every [DA][DA] add [FA] to Charm Checks. This does not apply to targets immune to Force powers.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PLAUSDEN', 'Plausible Deniability', 'Remove [SE] per rank of Plausible Deniability from all Coercion and Deception checks.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('POINTBL', 'Point Blank', 'Add 1 damage per rank of Point Blank to damage of one hit of a successful attack while using Ranged (Heavy) or Ranged (Light) skills at short range or engaged.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PRECAIM', 'Precise Aim', 'Once per round, suffer strain up to ranks in Precise Aim, then reduce target''s melee and ranged defense by that number.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PRESPNT', 'Pressure Point', 'When making a Brawl check against an opponent, instead of dealing damage, may deal equivalent strain plus additional strain equal to ranks of Medicine. These checks cannot be made with any weapons, but this strain damage is not reduced by soak.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('QUICKDR', 'Quick Draw', 'Once per round, draw or holster an easily accessible weapon or item as an incidental instead of a maneuver. Reduce the amount of time to draw or stow a weapon that usually requires more than one maneuver to properly prepare or stow, by one maneuver.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('QUICKST', 'Quick Strike', 'Add [BO] per rank of Quick Strike to combat checks against targets that have not acted yet this encounter.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RAPREA', 'Rapid Reaction', 'Suffer a number of strain to add an equal number of [SU] to initiative checks. Strain suffered cannot exceed ranks in Rapid Reaction.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
