INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SURG', 'Surgeon', 'When making a Medicine check to help a character heal wounds, the target heals 1 additional wound per rank of Surgeon.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
