INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STIMAP', 'Stim Application', 'Take the Stim Application Action; Must have access to drugs, a medpack, or stimpacks, make an [B]Average ([DI][DI]) Medicine check[b]. If successful 1 engaged ally (including themself) increases 1 characteristic by 1 for the remained of the encounter and suffers 4 strain. A single character''s individual characteristics may each only be increased once by Stim Application during an encounter.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STIMAPIMP', 'Stim Application (Improved)', 'When performing Stim Application Action, may increase difficulty of check to [B]Hard ([DI][DI][DI])[b], and target only suffers 1 strain.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TOUGH', 'Toughened', 'Gain +2 wound threshold.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STIMAPSUP', 'Stim Application (Supreme)', 'When performing the Stim Application Action, spend [TR] to increase an additional Characteristic by 1.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
