INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TARGBL', 'Targeted Blow', 'After making a successful attack with a non-starship/vehicle weapon, may spend 1 Destiny Point to add damage equal to Agility to one hit.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SNIPSHOT', 'Sniper Shot', 'Before making a non-thrown ranged attack, may  perform a Sniper Shot maneuver to increase the weapon''s range by 1 range band per rank of Sniper Shot. Upgrade the difficulty of the attack by 1 per range band increase (this is in addition to the increased difficulty of the shot due to longer range).', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
