INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SPKBIN', 'Speaks Binary', 'When directing NPC droids, may grant them [BO] per rank of Speaks Binary on checks.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
