INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SHORTCUT', 'Short Cut', 'During a chase; add [BO] per rank of Shortcut to any checks made to catch or escape an opponent.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UTIL', 'Utility Belt', 'Spend 1 Destiny Point to perform a Utility Belt incidental; produce a previously undocumented-but essential-small tool from his utility belt, satchel, or pockets, with a rarity no greater than 4. This cannot be a weapon unless it has the Limited Ammo 1 quality.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
