INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TRUEAIM', 'True Aim', 'Once per round, may perform a True Aim maneuver to gain benefits of aiming and upgrade combat check once per rank of True Aim.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TRICK', 'Tricky Target', 'Count vehicle or starship piloted as having a silhouette 1 lower when being attacked to a minimum of 0.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SOLREP', 'Solid Repairs', 'The character repairs +1 hull trauma per rank of Solid Repairs whenever he repairs a starship or vehicle.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UTINNI', 'Utinni!', 'Remove [SE] per rank of Utinni! from checks to find or scavenge items or gear. These checks could include Negotiation, Perception or other checks depending on circumstances and GM''s discretion.  Such checks take half the time (this does not decrease with multiple ranks of Utinni!).', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TECHAPT', 'Technical Aptitude', 'Reduces time needed to complete Computer-related tasks by 25% per rank.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SKILLSLIC', 'Skilled Slicer', 'When making a Computers check may spend [TR] to make further Computers checks within this system as maneuvers.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNCANSENS', 'Uncanny Senses', 'Add [BO] per rank of Uncanny Senses to all Perception checks.', 'taPassive', true, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNCANREAC', 'Uncanny Reactions', 'Add [BO] per rank of Uncanny Reactions to all Vigilance checks.', 'taPassive', true, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SENSDANG', 'Sense Danger', 'Once per session, remove [SE][SE] from any 1 check.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SENSDEMO', 'Sense Emotions', 'Add [BO] to all Charm, Coercion, and Deception checks unless the target is immune to Force powers.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TOUCH', 'Touch of Fate', 'Once per session, add [BO][BO] to any 1 check.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SIXSENSE', 'Sixth Sense', 'Gain +1 ranged defense.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SUPREF', 'Superior Reflexes', 'Gain +1 melee defense.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PIN', 'Pin', 'Take Pin action; make an [B]Opposed Athletics check[b] to immobilize an engaged opponent until the end of the character''s next turn. Spend [TR] to extend duration one round.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MUSEUMWORTHY', 'Museum Worthy', 'Once per session, take Museum Worthy action, make a [B]Hard ([DI][DI][DI]) Knowledge (Education) check[b] regarding a relic, ruin, or piece of history (subject to GM''s approval). If successful, the character knows an amount of information about the item based on the number of [SU] rolled.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HUNTERQUARRY', 'Hunter''s Quarry', 'Take Hunter''s Quarry action, make a [B]Hard ([DI][DI][DI]) Survival check[b] against an opponent within long range. If the check succceeds, upgrade the ability of all attacks made against the target by one until the end of the character''s next turn.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HUNTQIMP', 'Hunter''s Quarry (Improved)', 'Suffer 2 strain to perform Hunter''s Quarry action as a maneuver.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BRNGITDWN', 'Bring It Down', 'Once per attack, spend 1 Destiny Point to add damage to a single hit equal to target''s Brawn value.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ALLTERDRIV', 'All-Terrain Driver', 'When piloting a vehicle using the Piloting (Planetary) skill, the character does not suffer the penalties for driving through difficult terrain.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NATDRIV', 'Natural Driver', 'Once per session, may reroll any 1 Piloting (Planetary) or Gunnery check.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FULLSTOP', 'Full Stop', 'When piloting a ship or vehicle, take a full-stop maneuver to reduce speed to zero and suffer system strain equal to the speed reduced.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASDRIV', 'Master Driver', 'Once per round when piloting a vehicle using the Piloting (Planetary) skill, may suffer 2 strain to perform any action as a maneuver instead.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SOUNDINV', 'Sound Investments', 'At the start of each session, gain 100 credits for each rank of Sound Investments. How this mony is earned is up to the player and GM. The GM can also decide that the current events of the adventure may make these funds temporarily unavailable.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GREASE', 'Greased Palms', 'Before making a social check, may spend up to 50 credits per rank of Greased Palms to upgrade the ability of the check once for every 50 spent. How the money accomplishes this can be up to the player and GM, but could take the form or bribes, buying gifts, or even purchashing information that gives the character an advantage in the ensuing interaction.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('THROWCRED', 'Throwing Credits', 'At beginning of session, spend 100 credits to ignore strain threshold penalty due to triggered Obligation. This may represent the character temporarily dealing with the obligation via a few credits, or simply indulging in some sort of diversion that takes his mind off his problems.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BOUGHT', 'Bought Info', 'Instead of making a Knowledge check, may take a Bought Info action; spend credits equal to 50 times the difficulty of the check to pass with one [SU]. At GM''s discretion, character may not be able to use this ability if the information sought is particular esoteric or hard to find, or if the character is in a situation where they could not purchase information (such as marooned on a planet with no access to the HoloNet.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NATMERCH', 'Natural Merchant', 'Once per session, may reroll any 1 Streetwise or Negotiation check.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GOODCOP', 'Good Cop', 'May spend [AD][AD] from a Charm or Negotiation check to upgrade ability of a single ally''s subsequent Social Interaction check against the target a number of times equal to ranks in Good Cop. A single check may only benefit from one use of Good Cop.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BADCOP', 'Bad Cop', 'May spend [AD][AD] from a Deception or Coercion check to upgrade ability of a single ally''s subsequent Social Interaction check against the target a number of times equal to ranks in Bad Cop.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNRELSKEP', 'Unrelenting Skeptic', 'When targeted by a Deception check, the character automatically adds [FA] to the check equal to ranks in Vigilance.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNRELSKEPIMP', 'Unrelenting Skeptic (Improved)', 'When targeted by a Deception check that fails, may spend 1 Destiny Point to add [DE] to the pool results.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DISBEH', 'Distracting Behavior', 'Make a Distracting Behavior maneuver and suffer strain no greater than ranks in Cunning. Until the beginning of next turn, equal number of NPC''s suffer [TH] on checks. Range increases with additional ranks.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CONGENIAL', 'Congenial', 'May suffer a number of strain to downgrade difficulty of Charm or Negotiation checks or upgrade difficulty when targeted by Charm or Negotiation checks, by an equal number. Strain suffered this way cannot exceed ranks in Congenial.', 'taIncidental', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DISBEHIMP', 'Distracting Behavior (Improved)', 'The Distracting Behavior maneuver inflicts [TH][TH] on NPC''s checks when NPC''s target character''s allies.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BIGGESTFAN', 'Biggest Fan', 'Once per session, may take a Biggest Fan action; make a [B]Hard ([DI][DI][DI]) Charm check[b] to turn one NPC into the character''s biggest fan.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DECEPTAUNT', 'Deceptive Taunt', 'Once per session, may make Deceptive Taunt action. Make opposed Deception check tarteging one NPC within medium range. If successful, the NPC must attack the character during its next turn. If used outside of combat, at the GM''s discretion, the NPC can choose to perform a non-legal attack if the situation warrents it.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COORDODGE', 'Coordination Dodge', 'When targeted by a combat check, may spend 1 Destiny Point to add [FA] equal to ranks in Coordination to check.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PWRBLST', 'Powerful Blast', 'Increase Blast damage dealt by explosives, explosive weapons, and granades by +1 per rank of Powerful Blast.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SELDETON', 'Selective Detonation', 'When using a weapon with the Blast quality spend [AD] to exclude 1 target that would be affected by the explosion, up to ranks in Selective Detonation. The character may also spend [TR] to exclude multiple targets, so long as the total number of targets does not exceed ranks in Selective Detonation.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STEADYNERVES', 'Steady Nerves', 'Remove [SE] per rank of Steady Nerves from Cool or Skulduggery checks.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TIME2GO', 'Time to Go', 'The character may spend 1 Destiny Point to perform a Move maneuver as an incidental to attempt to move into cover or out of the blast range of a weapon or explosion. This may be performed out of turn. This incidental occurs after the character determines he would be hit by the blast, but before damage is applied.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TIME2GOIMP', 'Time to Go (Improved)', 'When activating Time to Go, allow 1 engaged ally to also perform an out of turn Move maneuver as an incidental to attempt to move into cover or out of the blast range of a weapon or explosion.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IMPDET', 'Improvised Detonation', 'Once per session, the character may make a [B]Hard ([DI][DI][DI]) Mechanics check[b] to perform the Improvised Detonation action and build an explosive device out of available materials.  
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IMPDETIMP', 'Improvised Detonation (Improved)', 'Reduce the difficulty of Improvised Detonation''s check to [B]Average ([DI][DI])[b] and increase damage to twice ranks in Mechanics.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASGREN', 'Master Grenadier', 'Decrease the [AD] cost to activate the Blast quality on any weapon used by 1 to a minimum of 1. This includes the cost to activate the Blast quality if the weapon misses.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FEARSOME', 'Fearsome*', 'When an adversary becomes engaged with the character, the character may force the adversary to make a fear check, with the difficulty equal to the character''s ranks in Fearsome. [I]See Long Text[i]', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TALKTALK', 'Talk the Talk', 'When making a Knowledge skill check, the character may spend 1 Destiny Point to substitute Knowledge (Underworld) or Streetwise for the required skill.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LOOM', 'Loom', 'When an ally engaged with the character makes a successful Charm, Deception, or Negotiation check, the character adds [AD] per rank in Coercion to the ally''s check.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WALKWALK', 'Walk the Walk', 'The character may spend 1 Destiny Point to add damage equal to his ranks in Streetwise to one hit of a successful Brawl check.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BURLY', 'Burly', 'Reduce any wielded weapon''s Cumbersome quality and Encumbrance rating by a number equal to ranks in Burly to a minimum of 1.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RAINDEATH', 'Rain of Death', 'Perform the Rain of Death maneuver to ignore the increased difficulty due to the Auto-fire quality of attacks made this turn.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HEROICRES', 'Heroic Resilience', 'Immediately after being hit by an attack but before suffering damage, spend 1 Destiny Point to increase soak by ranks in Resiliance.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HEAVYHITTER', 'Heavy Hitter', 'Once per session, spend [TR] on a successful Ranged (Heavy) or Gunnery check to add the Breach 1 quality to the attack, or increase an existing Breach rating by 1.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DISARMSMILE', 'Disarming Smile', 'Take the Disarming Smile action; succeed at an opposed Charm check against one target within short range to lower all defenses the target has by ranks in Disarming Smile until the end of the encounter.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WORKLIKECHARM', 'Works Like a Charm', 'Once per session, make one skill check using Presence rather than the characteristic linked to that skill. When he does this, he must explain how, in this particular instance, his social ability is helping him overcome this challenge.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('JUSTKID', 'Just Kidding!', 'Once per round as an incidental, when the charater or any of his allies in short range generates [DE] on a social skill check, the character may spend one Destiny Point to convert a single [DE] generated on the check to [FA]. When he does this, he must explain what he says or does to smooth things over after the verbal mistep.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DONTSHOOT', 'Don''t Shoot!', 'Once per session, the character can take the Don''t Shoot! action to make a [B]Hard ([DI][DI][DI]) Charm Check[b]. If he succeeds, he cannot be the target of a combat check until the end of the encounter or until he makes a combat check. 
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UPANTE', 'Up the Ante', 'When gambling win 10% more credits per rank of Up the Ante.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SECCHANCE', 'Second Chances', 'Once per encounter choose a number of positive dice equal to ranks in Second Changes and reroll them. This talent cannot be used to re-roll any [FO].', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FORTFAVORBOLD', 'Fortune Favors the Bold', 'Once per session as an out of turn incidental, suffer 2 strain to flip one dark side Destiny Point to light side (this cannot be used to interrupt the spending of a Destiny Point).', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CLEVERSOLN', 'Clever Solution', 'Once per session, make one skill check using Cunning rather than the characteristic linked to that skill. When they do this, they must explain how their cunning is helping them overcome this challenge.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DOUBLEORNOTHING', 'Double or Nothing', 'Once per check, suffer 2 strain to perform the Double or Nothing incidental to increase the difficulty of the next check by one. Then, after canceling opposing symbols, double the amount of remaining [AD]', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DOUBLEORNOTHINGIMP', 'Double or Nothing (Improved)', 'When performing the Double or Nothing incidental, after canceling opposing symbols, also double the amount of remaining [SU].', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('QUICKDRIMP', 'Quickdraw (Improved)', 'The character may activate the Quick Draw talent twice per round (instead of just once per round).', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CALLEM', 'Call ''Em', 'Do not add [SE] to combat checks due to the use of the Aim maneuver.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SORRYMESS', 'Sorry About the Mess', 'Decrease the Critical Rating of a weapon by 1 (to a minimum of 1) against targets that have not yet acted this encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GUNSBLAZING', 'Guns Blazing', 'As an incidental, suffer 2 Strain to avoid increasing the difficulty of a Ranged (Light) check to attack with two weapons.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SPITFIRE', 'Spitfire', 'After a successful combined check with two Ranged (Light) weapons, additional hits can be allocated to other targets within range of the weapon.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DOUBLEORNOTHINGSUP', 'Double or Nothing (Supreme)', 'When performing the Double or Nothing incidental, also double the number of [TR] and [DE].', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COMMPRES', 'Commanding Presence', 'Remove [SE] per rank of Commanding Presence from Leadership and Cool checks.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COORDASS', 'Coordinated Assault', 'Take the Coordinated Assault maneuver; a number of engaged allies equal to Leadership ranks add [AD] to combat checks until beginning of the character''s next turn. Range increases per rank of Coordinated Assault.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DEPSHOT', 'Debilitating Shot', 'Upon making a successful attack with a starship or vehicle weapon, may spend [AD][AD] to reduce the maximum speed of the target by 1 (to a minimum of 1) until the end of the next round.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EXHPORT', 'Exhaust Port', 'Before attacking a starship or vehicle, the character may spend 1 Destiny Point to ignore the effects of the Massive rule for the attack.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FIRECON', 'Fire Control', 'Take the Fire Control action; all combat checks made from current starship or vehicle count their target''s silhouette as one higher than normal until the beginning of the character''s next turn. Does not stack.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FORMONME', 'Form On Me', 'Allies equal to ranks in Leadership in close range gain the benefits of the Gain the Advantage action. These allied vehicles maintain the benefits until they leave close range with the character or character loses the benefits of Gain the Advantage.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASLEAD', 'Master Leader', 'Once per round, suffer 2 strain to decrease difficulty of the next Leadership check by one, to a minimum of [B]Easy ([DI]).[b]', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NATLEAD', 'Natural Leader', 'Once per session, may reroll any 1 Cool or Leadership check.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('OVERDEF', 'Overwhelm Defenses', 'Upon making an unsuccessful attack with a starship or vehicle weapon, may spend [AD][AD] per rank of Overwhelm Defenses. Reduce the defense in the targeted zone by 1 for every [AD][AD] spent.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INCITE', 'Incite Rebellion', 'Once per session, may take an Incite Rebellion action; make a [B]Hard ([DI][DI][DI]) Coercion check[b] to cause a number of beings up to ranks in Coercion to become unhappy and try and take action against an organization or authority with power over them until the end of the encounter. This could be due to something the character did or said, or just because the beings were already unhappy with their position.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CAREPLAN', 'Careful Planning', 'Once per session, the character can choose to introduce a "fact" or additional context directly into the narrative as if he had spent a Destiny Point.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PHYSTRAIN', 'Physical Training', 'Add [BO] per rank of Physical Training to Athletics and Resilience checks.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNSTOP', 'Unstoppable', 'If a Critical Injury roll is 1 or reduced to 1, do not receive the critical injury.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STIMSPEC', 'Stimpack Specialization', 'Stimpacks heal 1 additional wound per rank of Stimpack Specialization. The sixth stimpack any beyond each day still have no effect.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ITSNOTTHATBAD', 'It''s Not that Bad', 'Once per session when an ally would suffer a Critical Injury, may take an It''s Not That Bad action; make a [B]Hard ([DI][DI][DI]) Medicine check[b] to stop the ally from gaining the Critical Injury.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('QUICKFIX', 'Quick Fix', 'Once per session, make one skill check using Agility rather than the characteristic linked to that skill. When he does this, he must explain how, in this particular instance, his agility is helping him overcome this challenge.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BASICTRAIN', 'Basic Combat Training', 'Brawl and Ranged (Light) become career skills.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TACTTRAIN', 'Tactical Combat Training', 'Melee and Ranged (Heavy) become career skills.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('VEHTRAIN', 'Vehicle Combat Training', 'Gunnery and Piloting (Planetary) become career skills.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WELLTRAV', 'Well Travelled', 'Knowledge (Core Worlds) and Knowledge (Outer Rim) become career skills.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CREATKILL', 'Creative Killer', 'Reduce the critical rating of improvised weapons by 2 (to a minimum of 1).', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DYNFIRE', 'Dynamic Fire', 'When making a ranged attack while engaged with an opponent, may suffer 2 strain to reduce the ranged modifier by 1. So, when firing a Ranged (Heavy) weapon, the character only increases the difficulty by 1 when engaged, and when firing a Ranged (Light) weapon,  doesn''t increase the difficulty at all.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BEASTWRANG', 'Beast Wrangler', 'Add [BO] per rank of Beast Wrangler to checks to tame or wrangle creatures.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EXHANDLER', 'Expert Handler', 'Remove [SE] per rank of Expert Handler from Survival checks made to ride beasts.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SPUR', 'Spur', 'Take a Spur action; make a [B]Hard ([DI][DI][DI]) Survival check[b] to increase a beast''s top speed by 1. The beast suffers 2 strain every round it stays spurred, the character can choose to end the effects at the start of any of his turns.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SPURIMP', 'Spur (Improved)', 'Suffer 1 strain to attempt Spur as a maneuver and decrease its difficulty to [B]Average ([DI][DI]).[b]', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SPURSUP', 'Spur (Supreme)', 'When activating and maintaining Spur, the beast only suffers 1 strain instead of 2.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SOOTHTONE', 'Soothing Tone', 'Once per encounter when riding a beast, the character may perform a Soothing Tone action, attempting an [B]Average ([DI][DI]) Knowledge (Xenology) check[b]. If successful, the beast the character is currently riding recovers strain equal to [SU] on the check (or heals that number of wounds if it does not have a strain threshold).', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HIGHGTRAIN', 'High-G Training', 'When a starship or vehicle being piloted would suffer system strain, may suffer strain up to ranks in High-G Training to prevent an equal amount of system strain.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CORSEND', 'Corellian Sendoff', 'Take a Corellian Sendoff action; target two ships or vehicles at Close range that are both of equal or smaller silhouette to the character''s, make a [B]Hard ([DI][DI][DI]) Cool check[b] to cause the targets to suffer a minor collision (page 256 of the Age of Rebellion Core Rulebook).', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CORSENDIMP', 'Corellian Sendoff (Improved)', 'When performing a Corellian Sendoff, the targets suffer a major collision instead.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KOITURN', 'Koiogran Turn', 'When an opponent has gained the advantage on a starship or vehicle being piloted, may suffer 2 strain to perform a Koiogran Turn maneuver to immediately remove the effects of Gain the Advantage any opponents have on the character''s starship or vehicle. Vehicle with speed +4 or higher only.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SHOWBOAT', 'Showboat', 'Once per round, before making a check in a starship or vehicle, may suffer 2 strain to ''showboat''. If check is successful, add [TR] to the result, but if it fails, add [DE] instead. The [TR] and [DE] do not include the extra [SU] or [FA], respectively.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LARGEPROJ', 'Larger Project', 'Signature Vehicle can have a silhouette 1 larger per rank of Larger Project.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FANCPAINT', 'Fancy Paint Job', 'Upgrade all Charm, Deception, and Negotiation checks made in the presence of Signature Vehicle once.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SIGVEH', 'Signature Vehicle', 'The character chooses one starship or vehicle with a silhouette of 3 or lower that they own. This starship or vehicle is the character''s "Signature Vehicle." They upgrade all Mechanics checks made to work on the vehicle once. The process of modifying and acclimating to the new vehicle may take some time at the GM''s discretion. No two characters can have the same vehicle as their signature vehicle.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('OVERAMMO', 'Overstocked Ammo', 'Increase the value of the Limited Ammo quality of any weapons mounted on Signature Vehicle by 1 per rank of Overstocked Ammo.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TUNEDTHRUST', 'Tuned Maneuvering Thrusters', 'Increase the handling of Signature Vehicle by 1 per rank of Tuned Maneuvering Thrusters.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BOLSTARMOR', 'Bolstered Armor', 'Increase the armor value of Signature Vehicle by 1 per rank of Bolstered Armor.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CUSTCOOL', 'Customized Cooling Unit', 'Increase the system strain threshold of Signature Vehicle by 2 per rank of Customized Cooling Unit.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FORTVAC', 'Fortified Vacuum Seal', 'Increase the hull trauma threshold of Signature Vehicle by 1 per rank of Fortified Vacuum Seal.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NOTTODAY', 'Not Today', 'Once per session, spend a Destiny Point to save a Signature Vehicle from destruction. If it would be destroyed by a Critical Hit, the Critical Hit is still suffered but the effect is ignored. If it would be destroyed by some other event, the details of how the starship or vehicle survives the near-destruction are up to the player and the GM.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('REINFRAME', 'Reinforced Frame', 'Signature Vehicle gains Massive 1: when making an attack targeting the ship or vehicle, the Critical rating of any weapon used counts as 1 higher.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SUPPEVI', 'Supporting Evidence', 'When assisting an ally with a Charm, Deception, Leadership, or Negotiation check, add automatic [AD] per rank of Supporting Evidence.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DISCREDIT', 'Discredit', 'Once per encounter, take the Discredit action, make a [B]Hard ([DI][DI][DI]) Deception check[b] to upgrade the difficulty of one character''s social checks once, plus once for every [AD][AD], until of the encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TWISTWORD', 'Twisted Words', 'When an incoming social check generates [TH][TH] or [DE], may suffer 1 strain as an incidental to inflict strain equal to ranks in Coercion on speaker.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PLAUSDENIMP', 'Plausible Deniability (Improved)', 'Take an Improved Plausible Deniability action makes a [B]Hard ([DI][DI][DI]) Coercion check[b] to convince one bystander per rank of Plausible Deniability to depart quietly. If interrogated about the matter later, these NPCs deny having seen anything or have forgotten anything of importance.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ENCWORD', 'Encouraging Words', 'When an ally within short range fails a check, the character may suffer 1 strain to assist that ally''s next check this encounter as an out of turn incidental (rather than as a maneuver).  The GM has final say as to which actions can benefit from such assistance if the character is farther than engaged range.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BLACKMAIL', 'Blackmail', 'When an NPC exceeds his strain threshold by any means other than a combat check, the character may spend 1 Destiny Point to compel the NPC to immediately perform one simple task before becoming incapacitated. The character must be able to communicate with the NPC to activate this talent, and the player must explain how he is blackmailing the NPC.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INTERJECT', 'Interjection', 'After another character makes a social check, suffer 3 strain to take an interjection incidental make an [B]Average ([DI][DI]) Vigilance check[b] to add [SU] or [FA] equal to [SU], and [AD] or [TH] equal to [AD] to the check.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CONTPLAN', 'Contingency Plan', 'Spend 1 Destiny Point to recover strain equal to Cunning rating.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SLEIGHTMIND', 'Sleight of Mind', 'Add [BO] per rank of Sleight of Mind to all Stealth checks unless the being attempting to detect the character is immune to Force powers.', 'taPassive', true, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INVIG', 'Invigorate', 'Once per encounter, may add [FO] to a check using Brawn or Agility made by an ally in short range, [LI] add [SU] and [DA] add [TH].', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FORCEWILL', 'Force of Will', 'Once per session, make one skill check using Willpower rather than the characteristic linked to that skill. When he does this, he must explain how, in this particular instance, his willpower is helping him overcome the challenge.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('VALFACT', 'Valuable Facts', 'Once per encounter, perform Valuable Facts action; make an [B]Average ([DI][DI]) Knowledge check[b] (the GM and player should determine which is most applicable). If successful, add [TR] to one ally''s skill check during the encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RESEARCHIMP', 'Researcher (Improved)', 'On a successful Knowledge check, character and allies gain automatic [AD] per rank of Researcher on checks to act on those facts until the end of his next turn.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ENCCOMM', 'Encoded Communique', 'Upgrade the difficulty of checks to decrypt this character''s coded messages without the proper cipher a number of times equal to Computers skill.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWALL', 'Know-It-All', 'Once per session, perfectly recall an important fact previously learned as if a Destiny Point had been spent.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('THORASS', 'Thorough Assessment', 'Once per session, take a Thorough Assessment action: make a [B]Hard ([DI][DI][DI]) Knowledge check[b] (GM and player should determine which is most applicable) to gain Boost dice equal to [SU] that can be distributed during the encounter. Target has to be able to benefit from the information. One [BO] per check.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('POSSPIN', 'Positive Spin', 'Whenever any character''s Duty would increase, it increases by an additional 1 per rank of Positive Spin.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('POSSPINIMP', 'Positive Spin (Improved)', 'Once per session, if no PC''s Duty triggered, make a [B]Daunting ([DI][DI][DI][DI]) Charm check[b] with the difficulty decreased once rank of Positive Spin to have one PC''s Duty trigger. When the Propagandist does this, the player must explain what event he engineered to highlight his comrade''s contributions to the cause.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BADPRESS', 'Bad Press', 'Once per session, choose an organization and make a [B]Hard ([DI][DI][DI]) Deception check[b]. If successful, organization members have their wound thresholds reduced by 1, plus 1 per [SU][SU][SU], until the end of the session. When he does this, the player must explain how the PC disseminated the propaganda such that it has affected his targets. Target must have time and means to spread misinformation, and cannot use this action during a combat encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INFORM', 'Informant', 'Once per session, may reveal a contact who can shed light on a chosen subject. When the character does this, he must explain how he knows this contact and how the contact can shed light on the matter in question. The contact should be available to the PCs, but the GM decides what the contact''s expertise might cost.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INKNOW', 'In The Know', 'Remove [SE] up to ranks in In the Know from checks to get information from people or disseminate news. Minions NPCs do not realize this character''s allegiance in interviews.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INKNOWIMP', 'In The Know (Improved)', 'Once per session, make an [B]opposed Decepetion vs Vigilance[b] check with the difficulty downgraded once per rank of In the Know to have a target NPC (who need not be present) believe specific false intelligence.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CUTQUEST', 'Cutting Question', 'Once per encounter, when making a Coercion skill check, the character may use Deception skill instead. The Deception skill is combined with his Willpower characteristic to form the dice pool. The player must explain how, in this particular instance, his Deception skill is helping erode his foe''s resolve.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SITAWARE', 'Situational Awareness', 'When in a starship or vehicle with functional coms, allies within short range add [BO] to their Perception and Vigilance checks. Allies within close range add [BO][BO] instead. This talent operates on planetary scale, not personal scale.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IDEALIST', 'Idealist', 'Spend 1 strain to add an [AD] on a skill check.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HEALTRANCE', 'Healing Trance', 'Commit [FO]. For every full encounter [FO] remains committed, heal 1 wound per rank of Healing Trance.', 'taPassive', true, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PHYSICIAN', 'Physician', 'When making a Medicine check to help a character heal wounds, the target heals 1 additional strain per rank of Physician.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWHEAL', 'Knowledgeable Healing', 'When healing an ally, spend 1 Destiny Point to heal additional wounds equal to ranks in Knowledge (Xenology).', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HEALTRANCEIMP', 'Healing Trance (Improved)', 'When healing wounds due to Healing Trance, make a Resilience check to heal a Critical Injury. Difficulty of the check equals severity of the Critical Injury.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CALMAURA', 'Calming Aura', 'When an opponent targets character with a Force power, reduce [FP] generated by 1.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CALMAURAIMP', 'Calming Aura (Improved)', 'Spend a maneuver and suffer 2 strain to extend Calming Aura''s effects to allies equal to Willpower at short range until start of next turn.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PARRY', 'Parry', 'When hit by a Brawl, Melee, or Lightsaber attack, suffer 3 strain to reduce damage by 2 plus ranks in Parry. Once per hit only and when the character is wielding a Lightsaber or Melee weapon.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PARRYIMP', 'Parry (Improved)', 'When parrying a hit that generated [DESPAIR] or [THREAT][THREAT][THREAT]. May hit the attacker once with Brawl, Melee, or Lightsaber weapon. Deals the weapon’s base damage AFTER the original attack resolves.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('REFLECT', 'Reflect', 'When hit by a ranged attack, suffer 3 strain to reduce damage by 2 plus ranks in Reflect. Once per hit and when the character is wielding a Lightsaber weapon only.', 'taPassive', true, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DEFTRAIN', 'Defensive Training', 'When wielding a Lightsaber, Melee, or Brawl weapon, the weapon gains the Defensive quality with a rating equal to ranks in Defensive Training (this replaces any ranks in Defensive the weapon already has).', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NIMTECH', 'Niman Technique', 'When making a Lightsaber skill check, the character may use Willpower instead of Brawn.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SUMDJEM', 'Sum Djem', 'May spend [TR] or [AD][AD] with successful Lightsaber check to disarm opponent (with GM''s approval). The disarmed weapon lands anywhere within short range of the engagement (character''s choice).', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DRAWCLOSER', 'Draw Closer', 'Perform Draw Closer action; make a Lightsaber (Willpower) combat check against one silhouette 1 target within medium range, adding [FO] no greater than Force rating to check. Spend [FP] to move target one range band closer or to add [SU] to check.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CENTBEING', 'Center of Being', 'When wielding a lightsaber. Take a Center of Being maneuver. Until the beginning of next turn, attacks against the character increase their critical rating by 1 per rank of Center of Being.', 'taPassive', true, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FORCEASSAULT', 'Force Assault', 'Spend [TR] or [AD][AD][AD] on a missed Lightsaber (Willpower) combat check to immediately perform Move Force power action as maneuver.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CENTBEINGIMP', 'Center of Being (Improved)', 'Suffer 1 strain to perform Center of Being maneuver as an incidental.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ONEUNI', 'One With The Universe', 'Once per session, meditate, then perform One with the Universe action; make [B]Average ([DI][DI]) Astrogation check[b]. If successful, add [LI] to all Force power checks in the next encounter. If successful with [TH], add [DA]  instead.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PREEMAVOID', 'Preemptive Avoidance', 'Immediately after an opponent engages the character, may spend 1 Destiny Point to disengage from engaged enemy as an out-of-turn incidental.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FORCEALLY', 'The Force Is My Ally', 'Once per session, may suffer 2 strain to perform Force power action as maneuver.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ENHLEAD', 'Enhanced Leader', 'When making a Leadership check, add [FO] no greater than Force rating. Spend [FP] to add [SU] or [AD] to the result.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNITYASSAULT', 'Unity Assault', 'If a missed combat check generates [TR] or [AD][AD][AD], may spend to perform Force power targeting allies as a maneuver.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FORCEPROT', 'Force Protection', 'Perform the Force Protection maneuver; suffer 1 strain and commit [FO] up to ranks of Force Protection. Increase soak by number of [FO] committed until beginning of next turn. Suffer 1 strain every turn [FO] remains committed.', 'taPassive', true, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CIRCLESHELTER', 'Circle of Shelter', 'When an engaged ally suffers a hit, may use Parry or Reflect incidental against the hit.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BODIMP', 'Body Guard (Improved)', 'Once per session, when an ally protected by the Body Guard maneuver suffers a hit, suffer the hit instead.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PARRYSUP', 'Parry (Supreme)', 'If the user did not make a combat check during his previous turn, may suffer 1 strain to use Parry.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STRATFORM', 'Strategic Form', 'May take the Strategic Form action, making a [B]Hard ([DI][DI][DI]) Lightsaber check[b] rolling [FO] no greater than Force rating. If successful, 1 target within short range may only attack character for 1 round. Spend [FP] to extend effects for 1 target for 1 round.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWPOW', 'Knowledge is Power', 'Once per session, when making a check count Force rating as being equal to ranks in Knowledge (Lore).', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SENSEADV', 'Sense Advantage', 'Once per session, may add [SE][SE] to 1 NPC''s skill check.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RESDISARM', 'Resist Disarm', 'Suffer 2 strain to avoid being disarmed or have weapon damaged or destroyed.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MAKTECH', 'Makashi Technique', 'When making a check using the Lightsaber skill, the character may use Presence instead of Brawn.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DUELTRAIN', 'Duelist''s Training', 'Add [BO] to Melee and Lightsaber checks when engaged with only one opponent. A single minion group counts as multiple opponents.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FEINT', 'Feint', 'Spend [TR] or [AD][AD][AD] generated on a missed  melee attack to upgrade difficulty of opponent''s next attack targeting character by ranks in Feint.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MAKFIN', 'Makashi Finish', 'Take the Makashi Finish action; Perform a Lightsaber (Presence) combat check against engaged target, adding [FO] no greater than Force rating. Spend [FP] to add +10 to any resulting Critical Injury rolls.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MAKFLOUR', 'Makashi Flourish', 'Once per encounter, perform Makashi Flourish action. Make an [B]Average ([DI][DI]) Lightsaber (Presence) check[b]. 1 engaged opponent suffers strain equal to [SU], and heal an equal amount of strain. May spend [AD][AD] or [TR] to stagger the opponent until the end of the target’s next turn.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KEENEYED', 'Keen Eyed', 'Remove [SE] per rank of Keen Eyed from Perception and Vigilance checks. Decrease time to search a specific area by half.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FOREWARN', 'Forewarning', 'Perform the Forewarning action. All allies within medium range increase defense by character''s Force rating until they act in the encounter.', 'taPassive', true, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NATMYSTIC', 'Natural Mystic', 'Once per session, may reroll any 1 Force power check.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CONDITIONED', 'Conditioned', 'Remove [SE] per rank of Conditioned from Athletics and Coordination check. Reduce the damage and strain suffered from falling by 1 per rank of Conditioned.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ATARU', 'Ataru Technique', 'When making a check using the Lightsaber skill, the character may use Agility instead of Brawn.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HAWKSWOOP', 'Hawk Bat Swoop', 'Take the Hawk Bat Swoop action. Perform a Lightsaber (Agility) combat check against target within short range, adding [FO] no greater than Force rating. Spend [FP] to engage target and spend [FP] to add [AD] to check.', 'taPassive', true, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SABERSW', 'Saber Swarm', 'Perform the Saber Swarm maneuver; suffer 1 strain to make next Lightsaber (Agility) combat check this turn gain the Linked item quality equal to Force rating during check.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SABERTHROW', 'Saber Throw', 'Perform Saber Throw action; make Lightsaber combat check as ranged attack at target within medium range, adding [FO] no greater than Force rating. Must spend [FP] and succeed to hit target; spend [FP] to have weapon return to hand.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INTUITSHOT', 'Intuitive Shot', 'When maing a Ranged (Heavy) or Range (Light) combat check, add [FO] no greater than Force rating to the check. May spend [FP] to add [SU] or [AD].', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ANIMALEMP', 'Animal Empathy', 'When making checks to handle or tame animals, add [FO] no greater than Force rating to the check. Spend [FP] to add [SU] or [AD] to the check.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ANIMALBOND', 'Animal Bond', 'Develop long-term bond with single animal of silhouette no greater than half Force rating rounded down. This cannot be done in structured encounters. Bond persists as long as PC wishes it, but at GM discretion and circumstances depending.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MENTBOND', 'Mental Bond', 'May perform the Mental Bond action. Commit [FO]. While committed, may communicate with bonded animal at long range and see and hear through its senses. He can see and hear what it does, and in structure encounters, he may direct his animal at up to extreme range.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('QUICKMOVE', 'Quick Movement', 'Suffer 2 strain to perform the Quick Movement incidental; add [FO] no greater than Force rating to next check. May spend [FP][FP] to perform one additional Move maneuver after action. This Move maneuver may be in addition to any other maneuvers performed this turn and can allow the character to perform three maneuvers in a turn.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SHAREPAIN', 'Share Pain', 'May perform the Share Pain incidental when bonded animal suffers wounds. Reduce wounds suffered to half, then character suffers wounds equal to number reduced.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MENTTOOLS', 'Mental Tools', 'Always count as having the right tools for the job when performing Mechanics checks.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IMBUEITEM', 'Imbue Item', 'Take the Imbue Item maneuver; suffer 1 strain and commit [FO] to grant one weapon, piece of armor, or item an improvement while [FO] remains committed. Suffer 1 strain every round [FO] remains committed.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASTART', 'Master Artisan', 'Once per round, may take the Master Artisan Incidental; suffer 2 strain to decrease the difficulty of next Mechanics check by 1, to a minimum of [B]Easy ([DI])[b].', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INTUITIMP', 'Intuitive Improvements', 'When making check to craft or repair item, may add [FO] no greater than Force rating to check. Spend [FP][FP] to increase hard points by 1, to max of +2.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COMPTECH', 'Comprehend Technology', 'Take Comprehend Technology action; make an [B]Average ([DI][DI]) Knowledge (Education) check[b] to use Force rating as ranks in skills to use a single item.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SHROUD', 'Shroud', 'The character may spend 1 Destiny Point to make himself undetectable via Force powers and make his own powers go unnoticed for the remainder of the encounter.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SLIPMIND', 'Slippery Minded', 'If under the effects of a Force power, perform the Slippery Minded action; make a [B]Hard ([DI][DI][DI]) Deception check[b] to immediately end effects of power.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NOWYOUSEE', 'Now You See Me', 'Once per session, may take the Now You See Me action. Make a [B]Hard ([DI][DI][DI]) Deception check[b] to make a number of NPCs equal to Cunning within medium range forget any interactions they had with the character during the last thirty minutes.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SHIENTECH', 'Shien Technique', 'When making a check using the Lightsaber skill, the character may use Cunning instead of Brawn.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COUNTERST', 'Counterstrike', 'When an attack misses the character and generates [DE] or [TH][TH], may upgrade next Lightsaber (Cunning) check against attacker during encounter once.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('REFLECTIMP', 'Reflect (Improved)', 'When reflecting a hit that generated [DE] or [TH][TH][TH] may hit one target in medium range with the same damage as the initial hit, after original attack resolves.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DJEMSODEFL', 'Djem So Deflection', 'After using Reflect, may spend 1 Destiny Point to perform Move maneuver as out-of-turn incidental to close distance with or engage opponent. This may be performed once per round.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FALLAVAL', 'Falling Avalanche', 'Suffer 2 strain to add damage equal to Brawn to next Lightsaber combat check made that turn.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DISRUPSTRIKE', 'Disruptive Strike', 'Perform Disruptive Strike action; make a Lightsaber (Cunning) combat check, adding [FO] no greater than Force rating. Spend [FP] to add [FA] to the next combat check the target makes.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('REFLECTSUP', 'Reflect (Supreme)', 'If the user did not make a combat check during previous turn, may suffer 1 strain to use Reflect.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DRIVEBACK', 'Drive Back', 'The Inquisitor may spend [TR] or [AD][AD][AD] on a missed Brawl, Melee, or Lightsaber combat check to force target to make a move maneuver in a direction of the Inquisitor''s choice.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PREYWEAK', 'Prey on the Weak', 'Add +1 damage to one hit of successful combat checks against disoriented targets per rank of Prey on the Weak.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TERRIFY', 'Terrify', 'Take the Terrify action; make a [B]Hard ([DI][DI][DI]) Coercion check[b], adding [FO] no greater than Force rating. Disorient one target within medium range per [SU]. Spend [AD][AD] to extend duration and spend [FP] to immobilize affected target.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TERRIFYIMP', 'Terrify (Improved)', 'Reduce the difficulty of Terrify’s
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('AAO', 'Against All Odds', 'When incapacitated, perform Against All Odds action; making [B]Hard ([DI][DI][DI]) Resilience check[b] with [FO] equal to Force rating. Heal wounds equal to [SU], spend [FP] to add [SU].', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MULTOPP', 'Multiple Opponents', 'Add [BO] to Lightsaber, Brawl, and Melee checks when engaged with multiple opponents. This includes single groups of multiple minions.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NATBLADE', 'Natural Blademaster', 'Once per session, may reroll any 1 Lightsaber or Melee check.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SARSWEEP', 'Sarlacc Sweep', 'Increase difficulty of Lightsaber check by 1 to perform Sarlacc Sweep action. May spend [AD][AD] to hit additional engaged targets.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INTUITEVA', 'Intuitive Evasion', 'When piloting a silhouette 5 vehicle or smaller, may perform the Intuitive Evasion maneuver; suffer 1 strain and commit a [FO] up to ranks of Intuitive Evasion. Upgrade difficulty of combat checks targeting vehicle by equal amount until beginning of next turn. Suffer 1 strain at the beginning of each of his turns in which these dice remain committed.', 'taPassive', true, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INTUITSTRIKE', 'Intuitive Strike', 'When making a combat check with a planetary scale weapon, add [FO] no greater than Force rating to the check. Spend [FP][FP] to add [SU] or [AD].', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DEFCIRCLE', 'Defensive Circle', 'May take the Defensive Circle action, making a [B]Hard ([DI][DI][DI]) Lightsaber (Intellect) check[b]. The character, plus one ally within short range per [SU], gains X defense until the beginning of next turn. X equals 1, plus 1 per [AD][AD].', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SUPPRFIRE', 'Suppressing Fire', 'The character and each ally within short range may spend [AD] on their failed combat checks to inflict one strain on the target per rank of Supressing Fire. Each character can only activate this effect once per round.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PROPAIM', 'Prophetic Aim', 'While benefiting from an Aim maneuver, [DE] from the character''s Ranged (Heavy) and Ranged (Light) checks cannot cause attacks to hit allies engaged with the target.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('REINITEM', 'Reinforce Item', 'Take the Reinforce Item maneuver: commit [FO][FO] to grant one weapon or piece of armor the Cortosis quality while [FO][FO] remains committed. Suffer 3 strain at the start of each turn in which he keeps these dice committed.', 'taManeuver', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PRIMEPOS', 'Prime Positions', 'When this character or an ally in short range takes cover, he increases soak against ranged attacks by 1 per rank of Prim Positions until he leaves that cover.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PRESSHOT', 'Prescient Shot', 'Add [BO] to all Ranged (Light) checks unless the target is immune to Force powers.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PRECSTR', 'Precision Strike', 'When this character inflicts a Critical Injury with a Brawl, Melee, or Lightsaber weapon, may suffer 1 strain to change the result to any [B]Easy ([DI])[b] Critical Injury result. 
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GRAPPLE', 'Grapple', 'Once per round, the character may perform the Grapple maneuver. Until the beginning of the character''s next turn, enemies must spend two maneuvers instead of one maneuver to move from engaged range to short range of him.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('OVERBAL', 'Overbalance', 'Whenever an enemy engaged with the character makes a combat check, after the attack is resolved, the character may spend [DE] or [TH][TH][TH] to stagger the attacker until the end of the attacker''s next turn.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NOESC', 'No Escape', 'May spend [AD][AD] from a Coercion check or [TH][TH] from a foe''s fear based Discipline check; that target cannot perform a free maneuver during his next turn. The target must be within short range.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BALEGAZE', 'Baleful Gaze', 'When targeted by combat check from within medium range, may spend a Destiny Point to upgrade the difficulty of the check a number of times equal to ranks in Coercion.', 'taIncidentalOOT', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BLINDSPOT', 'Blind Spot', 'The character and allies within short range add automatic [AD] to combat checks they make while benefitting from cover.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ARMSUP', 'Armor Master (Supreme)', 'Once per round, when the character suffers a Critical Injury, he may suffer 3 strain to take the Armor Master incidental. If he does he reduces the Critical Injury result that he suffers by 10 per point of his soak, to a minimum of 1.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CUNNINGSTUNT', 'Cunning Stunt', 'Use Cunning instead of Presence for Cool checks.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SORESUTECH', 'Soresu Technique', 'When making a Lightsaber skill check, the character may use Intellect instead of Brawn.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FINESSE', 'Finesse', 'Use Agility instead of Brawn for Brawl or Melee checks.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SPKBINSUP', 'Supreme Speaks Binary', 'Once per encounter, may perform the Speaks Binary maneuver. Choose one skill, until the beginning of his next turn, a number of NPC, non-minion droids up to his ranks in Speaks Binary may use the character''s ranks in the chosen skill (rather than their own ranks in that skill).', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SPKBINIMP', 'Improved Speaks Binary', 'When the character directs a NPC droid to assist any character with a check, that droid provides an additional [BO] to the check for which it is assisting (beyond the usual benefits of assistance).', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RESOURCEREFIT', 'Resourceful Refit', 'May perform the Resourceful Refit action, make an [B]Average ([DI][DI]) Mechanics check[b] to scavenge an old attachment to construct a new one, reducing its price by that of the dismantled attachment.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('REROUTEPROC', 'Reroute Processors', 'Once per encounter, the character may perform the Reroute Processors action on a droid they are engaged with by making an [B]Average ([DI][DI]) Computers check[b] to reduce one of a droid''s characteristics by 1 (to a minimum of 0) and increase another of its characteristics by 1 (to a maximum of 7).  If the character is a droid, it may perform this action on itself.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('OVERCHARGESUP', 'Supreme Overcharge', 'When performing the Overcharge action, the character may choose any number of cybernetic implats to attempt to overcharge instead of just one. Upgrade difficulty of the Mechanics check once for each additional cybernetic beyond the first. On [DE], one overcharged cybernetic shorts out.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('OVERCHARGEIMP', 'Improved Overcharge', 'May spend [AD][AD] or [TR] from Overcharge action to immediately take another action.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('OVERCHARGE', 'Overcharge', 'Once per encounter, may use the Overcharge action. Make a [B]Hard ([DI][DI][DI]) Mechanics check[b] and choose one of their cybernetic implants that grants them one or more of the following: +1 to a characteristic rating, +1 rank to a skill, or +1 rank of a ranked talent. If they succeed, until the end of the encounter, the chosen cybernetic provides additional +1 to any characteristic rating (max of 7), an additional +1 ranks to any skills (max of 5), an additional +1 ranks of any ranked talents that it provides.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MOREMACH', 'More Machine Than Man', 'Increase cybernetic implant cap by 1 per rank of More Machine than Man.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MACHMEND', 'Machine Mender', 'When making a Mechanics check to help a character heal wounds, the target heals 1 additional wound per rank of Machine Mender.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ENERGTRANS', 'Energy Transfer', 'May suffer 1 strain to use the Energy Transfer maneuver to power up an unpowered device until the end of the encounter or replenish exhausted ammunition for an energy weapon. The character must have at least one cybernetic installed to perform this maneuver.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ENGREDUN', 'Engineered Redundancies', 'Gain the ability to use emergency repair patches to heal, but can only benefit from a total of 5 stim packs and/or emergency repair patches per day. Additionally, can be healed with Mechanics checks.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DEFTMAKER', 'Deft Maker', 'Remove [SE] per rank of Deft Maker from checks to repair, modify, construct, or program droids. In addition, materials to craft droids cost the character 50% less (this does not decrease with addition ranks).', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CYBERNETICIST', 'Cyberneticist', 'Remove [SE] per rank of Cyberneticist from checks to build, repair, and install cybernetic implants . In addition, cybernetics and any materials used to craft them cost the character 50% less (this does not decrease with addition ranks).', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CUSTLOAD', 'Custom Loadout', 'May add 2 additional hard points to Signature Vehicles.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WELLREAD', 'Well Read', 'Choose any 3 Knowledge skills. They permanently become career skills.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('THATHOWDONE', 'That''s How It''s Done', 'Upon a successful skill check, the character may suffer 1 strain.  If so, a number of characters within short range equal to the character''s Willpower add automatic [AD] when making the same skill check until the start of the character''s next turn.  The range at which That''s How It''s Done can affect allies increases by one band per rank of That''s How It''s Done beyond the first.', 'taIncidental', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('READANY', 'Ready for Anything', 'Remove [SE] per rank of Ready for Anything on Mass Combat checks and Cool or Vigiliance checks to determine Initiative order.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('READANYIMP', 'Ready for Anything (Improved)', 'When making Cool or Vigilance checks to determine Initiative order, may spend [TR] to add [SU] equal to ranks in Ready for Anything.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NATINST', 'Natural Instructor', 'Once per session, may reroll one Discipline or Leadership check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASSTRAT', 'Master Strategist', 'Once per phase during a mass combat, may suffer 2 strain to decrease difficulty of a Mass Combat check once.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASINST', 'Master Instructor', 'Once per round as an out of turn incidental, may suffer 2 strain to allow an ally within short range to use character''s ranks in Discipline for next Discipline check the ally makes.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CONFIMP', 'Confidence (Improved)', 'May spend [TR] on fear check tp steady the nerves of other allies making the same fear check. Each ally within short range add [SU] eual to the character''s ranks in Confidence to the result of their check.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COMMPRESIMP', 'Commanding Presence (Improved)', 'Once per session, may take Commanding Presence action; target a minion, minion group, or rival, make an opposed [B]Cool vs. Discipline[b]. If successful, the target removes itself from the encounter for the duration of it. The target will not attack or engage the PCs, or perform hostile or overt action, but will defend itself if attack. This can be used in narrative encounters with GM caveat applying.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CLEVCOMM', 'Clever Commander', 'May use ranks in Knowledge (Warfare) to upgrade Mass Combat checks instead of ranks in Leadership if the character is the commander of the acting force.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CALMCOMM', 'Calm Commander', 'May use ranks in Cool to upgrade Mass Combat checks instead of ranks in Leadership if the character is the commander of the acting force.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SEIZEINIT', 'Seize the Initiative', 'Once per session, character may leap foward to create a daring distraction on the battlefield; perform the Sieze the Initiative maneuver. Make a [B]Hard ([DI][DI][DI]) Athletics check[b]. If he succeeds, any nubmer of other PCs who have yet not acted this round may immediately take their turns as if there were that many PC slots at this point in the initiative order. Each PC who acts this way counts as having acted for this round (and thus cannot act again this round). Initiative order returns to its previous order at the beginning of the next round.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MOVTARGET', 'Moving Target', 'If the character has already acted this round, increase ranged defense by 1 per rank of moving target.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CUNNSNARE', 'Cunning Snare', 'Once per encounter as an action, may create a trap within short range. Any other character who moves to engaged range of the trap must make an [B]Opposed Vigilance vs. Survival check[b] to avoid the trap. If the trap is triggered, he suffers wounds (ignoring soak) equal to the trapper''s Cunning characteristic, plus 1 additional wound per [FA]. The trapper may spend [TH] generated by the check to disorient the character for 1 round per [TH] spent, [TH][TH][TH] or [DE] to immobilize the character for 1 round, and [DE] to stagger the character for 1 round. Once a character springs the trap, it is expended; at the GM''s discretion, the trapper may spend [DE] to have it remain functional for one extra use. It takes sevearl minutes and a [B]Hard ([DI][DI][DI]) Survival check[b] to disarm the trap, if fails the trap is triggered.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('AMBUSH', 'Ambush', 'Once per round while benefiting from cover, may make the Ambush maneuver. Add damage equal to Stealth skill to one hit of the next successful combat check with a non-starship/vehicle weapon against a target within short range before the end of his turn.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BODSUP', 'Body Guard (Supreme)', 'Body Guard maneuver may protect a number of engaged characters up to ranks in Reilience.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SUPHUMAN', 'Superhuman Reflexes', 'Once per session, after generating [DE] on a Piloting check, cancel the [DE] and add [SU] equal to ranks in Cool.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STRSMARTIMP', 'Street Smarts (Improved)', 'Once per session make a [B]Formidable ([DI][DI][DI][DI][DI]) Streetwise[b] or [B]Knowledge (Underworld)[b] check to learn one vital clue from the GM. Reduce the difficulty once per rank of Street Smarts. [I]See Long Text[i]', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SENSESCENE', 'Sense the Scene', 'Once per session, perform the Sense the Scene action; make a [B]Hard ([DI][DI][DI]) Perception check[b] while present at a single crime scene (or similar location), adding [FO] no greater than his Force rating to the check. If he succeeds and generates [FP], he may identify the emotional state of one person involved in the crime (such as the perpetrator or victim). He may spend additional [FP] to identify the emotional state of one additional person involved in the crime, and may do so multiple times.', 'taAction', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SABERTHROWIMP', 'Saber Throw (Improved)', 'When performing the Saber Throw action, may increase the range to long range. When attacking a target at long range, spend [FP][FP] to have the weapon return to hand.', 'taAction', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RECSCENE', 'Reconstruct the Scene', 'Once per session, perform the Reconstruct the Scene action; make a [B]Hard ([DI][DI][DI]) Perception check[b] while present at a crime scene (or similar location) if he succeeds, he identifies all prominent physical characteristics of one person who was at the crime scene when the crime was committed (if the crime occured within the last 24 hours). This could include the person''s weight, height, and species for example. He may idenfity all the phystical characteristics of one additional person similarly tied to the crime scene per additional [SU].', 'taAction', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IMPOSFALL', 'Impossible Fall', 'Once per session, perform Impossible Fall incidental when falling: make Force power check and spend [FP] to land somewere safe such as a pile of empty boxes in a street or a muddy spot in a larva field. The character may then spend [FP] to reduce the effects of the fall by one range band (page 221 of the Force and Destiny Core Rulebook), and may do so multiple times.', 'taIncidentalOOT', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FREERUN', 'Freerunning', 'Once per round, before perfoming a Move maneuver, the character may suffer 1 strain. If he does so, he may use his Move maneuver to move to any location within short range (even straight up) as long as there is some sort of object to move across or a path to move along.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FREERUNIMP', 'Freerunning (Improved)', 'Once per round, before perfoming a Move maneuver, the character may suffer 4 strain. If he does so, he may use his Move maneuver to move to any location within medium range (even straight up) as long as there is some sort of object to move across or a path to move along.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FEARSHAD', 'Fear the Shadows', 'Perform the Fear the Shadows action; make a [B]Hard ([DI][DI][DI]) Deception check[b] to force a single minion group or rival within long range to flee the encounter. At the GM''s discretion, these NPCs may not flee due to extenuating circumstances (such as if there is no realistic path or means to leave the encounter, or the only way to leave the encounter may result in their deaths from a dangerous fall or lethal atmosphere).', 'taAction', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CONSTVIGIL', 'Constant Vigilance', 'The character may always choose to use the Vigilance skill when making checks to determine Initiative.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BETTERLUCK', 'Better Luck Next Time', 'Once per session during a race or chase, the character may perform the Better Luck Next Time action. Make a [B]Hard ([DI][DI][DI]) Cool check[b]. If he succeeds, something terrible happens to one of his competitors. This could be a high-speed collision, having to dodge into a dead end to avoid an obstacle, or even an attack by enraged fans or spectators, as long as the GM approves it. At minimum, the competitor should suffer a major collision with an obstacle.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TERRKILL', 'Terrifying Kill', 'Spend a Destiny Point and take a Terrifying kill maneuver after incapacitating an enemy or inflicting a critical injury. Roll [FO] no greater than Force Rating, and spend [FP] to inflict 1 strain on any other character within short range of that target. A character who has purchased this talent gains 1 conflict at the beginning of a game session.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SURVFIT', 'Survival of the Fittest', 'Once per session, when making a single check the character may treat his Force rating as being equal to ranks in Survival.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STUDPLOT', 'Studious Plotting', 'When making a Streetwise or Survival skill check to navigate on a world, the character may use Intellect instead of Cunning.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SHORTCUTIMP', 'Shortcut (Improved)', 'When engaging in a chase or race, may suffer 2 strain to add [SU] equal to ranks in Shortcut to the check.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PLANMAP', 'Planet Mapper', 'Remove [SE] per rank of Planet Mapper from Streetwise or Survival checks used for navigation on a world. In addition, such checks take 50% less time (this does not decrase with additional ranks).', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ONENAT', 'One with Nature', 'When in the wilderness, the character may make a [B]Simple (-) Survival check[b] instead of Discipline or Cool to recover starin at the end of an encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MINDMAT', 'Mind Over Matter', 'The character may spend one Destiny Point to recover strain equal to to his Willpower rating.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MENACE', 'Menace', 'Once per round, on the character''s turn, the character may spend a maneuver to allow any suitably threatening creature linked through the Animal Bond talent and of Silhouette 2 or greater to perform the Menace manevuver when the creature is at short range with an enemy. The enemy gains [SE] on his next combat check against the character in this encounter. Enemy characters who are immune to the effects of fear are also immune to this ability. GM has final determination as to if a creature can threatn an enemy based on relative sizes and natures.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MARKDEATH', 'Marked for Death', 'Take the Marked for Death maneuver; commiting [FO]. Add [AD][AD] to combat checks against a chosen target while [FO] remains committed but cannot use this talent again until the original target is incapacitated or the session ends. [AD] gained this way cannot be used to recover strain.', 'taManeuver', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ESSENKILL', 'Essential Kill', 'When making a non-Gunnery combat check or operating a non-starship weapon, the character may add [FO] no greater than his Force rating to the check. The character may spend [FP] to add [AD] or [FP][FP][FP] to add [TR] (character''s choice) to the result. [AD] gained this way cannot be used to recover strain.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DEATHBLOW', 'Deathblow', 'After making a successful attack with a non-starship/vehicle weapon, the character may spend one Destiny Point to add damage equal to his Willpower to one hit of the successful attack.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IRONBODY', 'Iron Body', 'Remove [SE] per rank of Iron Body from Coordination and Resilience checks. Reduce the critical rating of unarmed attacks by 1 per rank of Iron Body (to a minimum of 1).', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNARMPARRY', 'Unarmed Parry', 'May Parry while unarmed. Reduce strain cost to Parry while unarmed by 1 (to a minimum of 1).', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PRECSTRSUP', 'Precision Strike (Supreme)', 'Once per session, when inflicting a Critical Injury with an unarmed attack, may suffer 3 strain to change the result to any [B]Hard ([DI][DI][DI])[b] Critical Injury. Combat checks to activate this talent cannot be made with any weapons.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PRECSTRIMP', 'Precision Strike (Improved)', 'Once per round, when inflicting a Critical Injury with a Brawl or Melee weapon, may suffer 2 strain to change the result to any [B]Average ([DI][DI])[b] Critical injury.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MARTIALGRACE', 'Martial Grace', 'Once per round, suffers 2 strain to add damage equal to ranks in Coordination to next Brawl check made this turn.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('OFFDRIVE', 'Offensive Driving', 'As a maneuver, suffer system strain up to vehicle''s highest defense to upgrade the difficulty of target''s next Piloting check that many times.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HINDERSHOT', 'Hindering Shot', 'Increase the difficulty of next Gunnery check by 1. If successful and the check deals damage, target starship or vehicle suffers system strain equal to speed when it moves until the end of the encounter.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HARDBOILED', 'Hard-Boiled', 'When recovering strain after an encounter, may spend [AD] up to ranks in Hard-Boiled to recover 1 wound per [AD] spent.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ANIMALBONDIMP', 'Animal Bond (Improved)', 'When spending a maneuver to direct a bonded animal, the character may suffer 1 strain to add [BO] to the animals next check.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FORCECONN', 'Force Connection', 'When the character performs a Survival or Knowledgen(Xenology) skill check, he may roll [FO] no greater than his Force rating. The character may spend [FP] to add [SU] or [AD] (character''s choice) to the result.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HARASS', 'Harass', 'Whenever the character''s bonded animal makes a successful combat check against a target, it may forgo inflicting damage to upgrade the difficulty of the target''s next check once instead. This can stack should multiple creatures perform this action on the same target.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HOLNAV', 'Holistic Navigation', 'When making an Astrogation skill check, the character may spend one Destiny Point to remove [DE], or to remove [TH] equal to his ranks in Perception.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INTUITNAV', 'Intuitive Navigation', 'When performing an Astrogation or Knowledge (Outer Rim) skill check, the character may roll [FO] no greater than his Force rating. The character may spend [FP] to add [SU] or [AD] (character''s choice) to the result.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MOUNTSTUBBORN', 'Stubborn', 'Upgrade the difficulty of checks to train this mount by 1 per rank.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MOUNTDOMESTED', 'Domesticated', 'Difficulty for training this beast is not upgraded.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MOUNTFLY', 'Flyer', 'This mount can fly.  When on the ground, it''s Speed is reduced to 1.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MOUNTBURDEN', 'Beast of Burden', 'Add 1 per rank to the mount''s encumbrance threshold.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MOUNTTRAINED', 'Trained Mount', 'Add [BO] per rank to a rider''s Survival checks while mounted on this mount.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MOUNTDOMEST', 'Domesticable', 'Downgrade the difficulty of checks to train this mount by 1 per rank.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ALTEREDDEAL', 'Altered Deal', 'Once per Session the character may take the Altered Deal action and make a [B]Hard ([DI][DI][DI]) Coercion check[b] to radically change a previously agreed upon deal or bargain to a version much more advantageous to the character.  The player player must narratively explain what happened, including the details of how the character arranged for the deal to be changed as well as the specifics of the new deal.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ASFORCEWILLS', 'As the Force wills it', 'The character may make an [B]Easy ([DI]) Knowledge (Lore) check[b] (instead of Discipline or Cool) to heal strain at the end of an encounter. [TRIUMPH] can be spent to heal all strain.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BYTHEBOOK', 'By the Book', 'Once per encounter, before making a combat check, the character may suffer two strain to add automatic [AD] to the results equal to his ranks in By the Book', 'taIncidental', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COMRADESINARMS', 'Comrades in Arms', 'Once per encounter, the character may take a Comrades in Arms action to make a [B]Hard ([DI][DI][DI]) Discipline check[b].  If successful, the character plus one ally per [SU] within medium range gains +1 defense for the remainder of the encounter.  Should an ally move outside of medium range, that ally loses this benefit.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COMRADESINARMSIMP', 'Comrades in Arms (Improved)', 'Whenever the character takes the Comrades in Arms action, he may spend [AD][AD][AD] or [TR] to also gain +1 soak or to give one affected ally +1 soak.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DISCIPLEOFLORE', 'Disciple of Lore', 'Once per round, the character may suffer one strain to decrease the difficulty of his next Knowledge (Lore) check a number of times equal to ranks in Disciple of Lore, to a minimum of [B]Simple (-)[b]', 'taIncidental', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DISCIPLINEDSOUL', 'Disciplined Soul', 'The character may spend one Destiny Point after making a Discipline check to spend a number of [TH] not exceeding the character''s ranks in Knowledge (Lore) as [AD]', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DISORIENTSTRIKE', 'Disorienting Strike', 'After missing an opponent with a Lightsaber combat check, the character may choose to spend [AD][AD] or [TR] to disorient his foe for three rounds.  Disoriented opponents add [SE] to all skill checks.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DOUBLETALK', 'Double-Talk', 'The character may spend [AD][AD] or [TR] from a successful Charm or Deception check to disorient a number of opponents within short range equal to his rating in Presence for the remainder of the current round and the next two rounds.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EXTENDREACH', 'Extended Reach', 'While armed with a two-handed melee weapon, the character may suffer one strain to make a Melee combat check with that weapon targeting an enemy at up to short range (rather than engaged range).  The difficulty of the check remains [B]Average ([DI][DI])[b].', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FEARSOMEREP', 'Fearsome Rep', 'The character adds automatic [AD] to the results of his Coercion checks equal to his ranks in Fearsome Rep', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FORMATIONTACTICS', 'Formation Tactics', 'The character may take the Formation Tactics action by making a [B]Hard ([DI][DI][DI]) Leadership check[b].  If successful, he may choose a number of allies within short range equal to [SU] generated.  The difficulty of attacks against these allies is upgraded once until the end of his next round.  the effects of this action do not stack.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FORMATIONTACTICSIMP', 'Formation Tactics (Improved)', 'The difficulty of taking the Formation Tactics action is reduced to [B]Average ([DI][DI])[b] instead of [B]Hard([DI][DI][DI])[b].  The character may also spend [TR] or [AD][AD][AD][AD][AD][AD] to have the effect last until the end of the encounter.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INSPIRINGLEADERSHIP', 'Inspiring Leadership', 'The character may take the Inspiring Leadership action by making an [B]Average ([DI][DI]) Leadership check[b].  If successful, a number of allies not exceeding his rating in presence within a short range add automatic [SU] to their next skill check.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWTHEENEMY', 'Know the Enemy', 'The character may choose to use the Knowledge (Warfare) skill when making checks to determine initiative.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWSTHEROPES', 'Knows the Ropes', 'Whenever the character is in binders or other personal restraints, he adds [BO] to checks made to free himself equal to his ranks in Knowledge (Underworld), [TR] on the check can be spent to free all other bound characters within short range.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MOSTIMPRESSIVE', 'Most Impressive', 'The character may spend [TR] from any skill check to allow a number of allies not excluding his rating in Presence within short range to add automatic [AD] to their next skill check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PERSISTARGET', 'Persistent Targeting', 'After making one or more successful combat checks against a target, the character adds [BO] to combat checks against that same target for the remainder of the encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PREPTOBOARD', 'Prepare to be Boarded!', 'Once per encounter the character may take the Prepare to be Boarded! action by making an [B]opposed Coercion vs. Discipline check[b] targetting an enemy ship captain (note this can be done via electronic means; the two characters do not need to be face to face).  If successful, the enemy suffers one strain per uncanceled [SU].  The character may also spend [TR] or [AD][AD][AD][AD] to inflict additional strain equal to his ranks in Coercion.  Should the enemy exceed his strain threshold as a result of resolving the check, the enemy surrenders his ship to the character.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PRIDEANDJOY', 'Pride and Joy', 'The character schooses one starship or vehicle with a silhouette of 4 or higher that they owns.  This vessel is the character''s "Pride and Joy" vessel.  They upgrade the ability of all social skill checks they makes while within short range of the vessel once.  If the vessel is ever lost or destroyed, the character may apply Pride and Joy to a new starship or vehicle that meets the requirements.  The process of modifying and acclimating to the new vessel may take some time at the GM''s discression.  No two characters can have the same vessel as their Pride and Joy.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PRIDEANDJOYIMP', 'Pride and Joy (Improved)', 'While inside their Pride and Joy vessel, the character recovers one additional strain whenever they recover strain and may spend [AD] on checks made to recover strain to allow and ally also within the vessel to recover one strain.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PRIDEANDJOYSUP', 'Pride and Joy (Supreme)', 'While inside their Pride and Joy vessel, once per session the character may reduce this vessel''s silhouette by two (to a minimum of 0) for the remainder of the round and the following round.  This lowered silhouette is used only for purposes of combat and movement, it does not physically reduce the size of the vessel.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PUSHASIDE', 'Push Aside', 'After making a successful Melee, Brawl, or Lightsaber combat check against an engaged foe, the character may force the opponent to move to short range as an out-of-turn incidental in a direction of the opponent''s choosing.  The character may spend [TR] to cause the opponent to fall prone after moving.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SECRETSOFTHEJEDIIMP', 'Secrets of the Jedi (Improved)', 'Discipline becomes a career skill.  Secrets of the Jedi can also be used when installing mods to lightsabers.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SEENALOTOFTHINGS', 'Seen a Lot of Things', 'Whenever the character failes a Knowledge check, he may spend [AD][AD][AD] to roll the check again during his next turn.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STEADYAIM', 'Steady Aim', 'The character does not lose the benefits of the Aim maneuver if her performs othe maneuvers (including moving) or actions.  He does lose the benefits of the aim maneuver if the encounter ends.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TARGETEDFIREPOWER', 'Targeted Firepower', 'Once per session the character may take the Targeted firepower action by identifying one detected enemy character, vehicle, starship, or structure  and making a [B]Hard ([DI][DI][DI]) Knowledge (Warfare) check[b].  If successful, for the remainder of the encounter all allies within short range add automatic [AD] to their combat attacks against that target equal to [SU] that the character gained in the check.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TEMPLETRAINING', 'Temple Training', 'Before making a Lightsaber skill check, the character may spend one Destiny Point to add damage to the attack equal to his ranks in Knowledge (Lore).', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TRUSTNOONE', 'Trust No One', 'When targeted by a social check, the character may choose to suffer one strain to add automatic [FA] to the check, if the check fails with [DE], the character may immediately perform a maneuver as an out-of-turn incidental.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TRUSTHTECAPTAIN', 'Trust the Captain', 'The character may take the Trust the Captain action by making a [B]Hard ([DI][DI][DI]) Leadership check[b]. If successful, for the remainder of the encounter all allies within short range increase their ranks in Discipline by an ammountt equal to the character''s ranks in Trust the Captain.', 'taAction', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COMBATVETERAN', 'Combat Veteran', 'The character adds [BO] to his Brawl and Discipline checks equal to his ranks in Combat Veteran.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EYEDET', 'Eye for Detail', 'After making a Mechanics or Computers check, may suffer strain up to ranks in Eye for Detail to convert that many [SU] to [AD].', 'taIncidental', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SECRETSOFTHEJEDI', 'Secrets of the Jedi', 'Lightsaber becomes a career skill.  The character may also decrease the difficulty of checks made to construct or repair lightsaber hilts a number of times equal to half his ranks in knowledge (lore) (rounded up), to a minimum of [B]Easy ([DI])[b].  This does not include checks made to install mods.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('AGGRNEG', 'Aggressive Negotiations', 'Once per session, perform a [B]Hard ([DI][DI][DI]) Lightsaber check[b] to decrease the difficulty of all Negotiation checks for the rest of the encounter by 2 to a minimum of 0.', 'taAction', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ALCHEMICALARTS', 'Alchemical Arts', 'After making a crafting check to create a potion or talisman, the character may choose to suffer strain no greater than twice their ranks in Alchemical Arts. For every two strain, they may add [LI] or [DA] to the results. If they choose to add [DA], they also suffer 1 Conflict per [DA].', 'taIncidental', true, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BLOIMP', 'Bloodied (Improved)', 'The character may take the Improved Blooded action, making a [B]Hard ([DI][DI][DI]) Resilience check[b]. If they succeed, they immediately recover from the effects of all poisons and the side effects or after effects of all drugs.  Reduce the difficulty of the check once per rank of Blooded, to a minimum of [B]Simple (-)[b].', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CHANNELAGONY', 'Channel Agony', 'After rolling [FO], the character may choose to suffer wounds no greater than twice their ranks in Channel Agony. For every two wounds, they add [DA] to the results.', 'taIncidental', true, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FONTOFPOWER', 'Font of Power', 'Once per game session, the character may perform the Font of Power action. For the remainder of the encounter, if the character is a light side Force user, whenever another Force user within medium range rolls [FO], add automatic [LI] to the results. If the character is a dark Side Force user, whenever another Force user within medium range rolls [FO], add automatic [DA] to the results.', 'taAction', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IDENTIFYINGREDIENTS', 'Identify Ingredients', 'After being exposed to any unknown substance, as an out of  turn incidental, the character may roll [FO] no greater than their Force rating. They may spend [FP][FP] to immediately identify the composition and any effects of the substance.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('OVERWHELMINGAURAIMP', 'Overwhelming Aura (Improved)', 'While Overwhelming Aura is active, characters affected by this character''s Overwhelming Aura talent add automatic [FA] to fear checks the character causes and automatic [SU] to fear checks not caused by the character.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('OVERWHELMINGAURA', 'Overwhelming Aura', 'The character may take the Overwhelming Aura maneuver, suffering 1 strain and committing a number of [FO] no greater than their Force rating or ranks of Overwhelming Aura. The character adds automatic [AD] equal to [FO] committed to their social checks. Opponents within short range add automatic [TH] equal to [FO] committed to their social checks', 'taManeuver', true, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('POWEROFDARK', 'Power of Darkness', 'Once per session, the character may perform the Power of Darkness maneuver. If they do so. they increase their wound threshold and strain threshold by 1 per Dark Side Destiny point currently in the Destiny pool until the end of the encounter.', 'taManeuver', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SECRETLORE', 'Secret Lore', 'The character removes [SE] per rank of Secret Lore from their Kowledge (Lore) checks.  The character reduces the difficulty of Knowledge (Lore) checks they make by 1 (this benefit does not increase with additional ranks of Secret Lore).', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TRANSMOGRIFY', 'Transmogrify', 'When making a crafting check, the character may add [FO] no greater than Force rating to the check. The character may spend [FP] to add [SU] to the result, and may spend [FP][FP] to add [AD] to the result.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IMPROVISEDCONCOCTION', 'Improvised Concoction', 'Once per encounter, as an action, the character may make a [B]Hard ([DI][DI][DI]) Knowledge (Xenology)[b] check, adding [FO] no greater than their Force rating. If the character succeeds, they create 1 dose of any potion, poison, or drug (such as the ones found on page 81 or page 181 of the Force and Destiny Core Rulebook) out of available materials.  The rarity of this item must be lower than or equal to the character''s Intellect + [SU] + [FP] spent.', 'taAction', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CRUCPOINT', 'Crucial Point', 'Once per session, the character may introduce to negotiations one potential concession that an opponent will do nearly anything to obtain. This can only be used in an encounter using the Negotiation skill.', 'taIncidental', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EMPTYSOUL', 'Empty Soul', 'If the character is carrying items that total 2 encumbrance or less, add [LI][DA] to Force power checks.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GOWITHOUT', 'Go Without', 'Once per session, the character counts as having the right tools for the job when making a skill check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IRONSOUL', 'Iron Soul', 'When carrying items that total 2 encumbrance of less, at the end of each encounter, heal all strain the character is suffering.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MEDTRANCE', 'Meditative Trance', 'When suffocating ([B]Force and Destiny[b] Core Rulebook, page 221), the character suffers 1 strain each round instead of 3. When exposed to vacuum, the character suffers 1 wound each round instead of 3.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MINDBLEED', 'Mind Bleed', 'If the character is carrying items that total 2 encumbrance or less; When attacked, the character may choose to suffer strain no greater than the number of wounds suffered from the attack. If he does so, the attacker then suffers a number of wounds equal to the strain suffered by the character.', 'taIncidentalOOT', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NOWMAST', 'Now the Master', 'Once per session, choose one talent or Force power that any character in the current encounter possesses. Gain that talent or Force power until the end of the encounter. If the chosen talent is a ranked talent, the character counts as having ranks in that talent equal to the ranks the target possesses. If a Force power is selected, he counts as having the same upgrades purchased.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ONCELEARN', 'Once A Learner', 'As an action, suffer 4 strain and increases the Force rating of one ally in short range equal to the character''s Force rating until the end of the character''s next turn. You may not make any Force Power checks until the after your next turn.', 'taAction', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SAVVYNEG', 'Savvy Negotiator', 'Remove all [SE] per rank of Savvy Negotiator from all Negotiation and Streetwise checks.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SAVVYNEGIMP', 'Savvy Negotiator (Improved)', 'While engaged in a debate or argument, the character may take the Savvy Negotiator action; make a [B]Hard ([DI][DI][DI]) Negotiation check[b]. If successful, one bystander or observer per rank of Savvy Negotiator sees one of the opponent''s points (chosen by the character) as maliciously unreasonable. GM has final say as to whether bystanders could see a point as unreasonable.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SKILLEDTEACH', 'Skilled Teacher', 'Before an ally at short range makes a skill check, if that ally has fewer ranks in that skill than the character does, the character may choose to immediately perform a Skilled Teacher incidental to suffer a number of strain, then add an equal number of [SU] to the ally''s next check. The number of strain suffered cannot exceed the character''s ranks in Skilled Teacher.', 'taIncidentalOOT', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SUNDERIMP', 'Sunder (Improved)', 'Each [AD] spent to activate a weapon''s Sunder quality damages an items two steps instead of one.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WISEWAR', 'Wise Warrior', 'Once per round, when making a combat check, may perform the Wise Warrior incidental; spend 1 Destiny Point an use any characteristic for the check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WISEWARIMP', 'Wise Warrior (Improved)', 'When performing the Wise Warrior incidental, one ally at short range may use the same characteristic for the next combat check the ally makes before the end of the character''s next turn.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ACKLAYSCYTHINGSTRIKE', 'Acklay''s Scything Strike', 'The character''s Brawl attacks gain the Pierce quality with a rating equal to their Force rating, or increase their existing Pierce quality by that amount.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IMPDODGE', 'Improved Dodge', 'When the character performs the Dodge incidental, the character may make a Move maneuver as an out-of-turn incidental after the triggering attack has been resolved.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EMBRACEHATE', 'Embrace Your Hate', 'After making a successful Brawl, Lightsaber, or Melee combat check, the character may spend one Destiny Point and then gain Conflict equal to the number of dark side Destiny Points in the Destiny pool to add an equal amount of damage to one hit of the attack, The character may use this ability once per encounter for each rank of Embrace Your Hate.', 'taIncidental', true, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FARSTRIKE', 'Far Strike', 'The character may take the Far Strike action, making a Brawl combat check as a ranged attack at one target at short range or further, adding [FO] no greater than the character''s Force rating to the check. The character may spend [FP] to increase the range of the attack by one range band per [FO] spent, to a maximum of long.  If the target is at medium range or further, the character must both sufficiently increase the range of the attack and succeed on the check to hit the target.', 'taAction', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HEADBUTT', 'Headbutt', 'Once per encounter, the character may perform the Headbutt incidental. The character suffers 2 wounds and selects one engaged non-vehicle target with a silhouette of up to one higher than the character''s.  The target is knocked prone and is disoriented until the end of t he next round.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INDOMITABLEWILL', 'Indomitable Will', 'Once per encounter, the character may perform the Indomitable Will maneuver, suffering 3 strain to commit a number of [FO] up to their Force rating.  While [FO] remain committed, reduce all damage the character suffers by an amount equal to the committed [FO], and the character suffers 1 strain at the beginning of each of their turns.', 'taManeuver', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INNERPEACE', 'Inner Peace', 'Once per encounter, the character may convert a number of dark side Destiny Points equal to the character''s ranks in Inner Peace to light side Destiny Points. The character reduces the amount of Conflict they gain at the end of the session by 1 plus 1 per Destiny Point converted.', 'taIncidental', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('JUYOSAVAGERY', 'Juyo Savagery', 'When the character inflicts a Critical Injury with a Lightsaber combat check, add + 5 to the Critical Injury roll for each dark side Destiny Point in the Destiny pool.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('POWERFROMPAIN', 'Power From Pain', 'Once per session, the character may spend a Destiny Point to gain + 1 Force rating for each Critical Injury the character is suffering, until the end of the encounter.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SAPITHSUNDERING', 'Sapith Sundering', 'When making a Brawl combat check, the character may include [FO] up to the character''s Force rating. The Brawl attack gains the Sunder quality, and the character may spend [FP] generated on the check as [AD] to activate the Sunder quality.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TOUGHENEDIMP', 'Toughened (Improved)', 'Once per session, the character may heal a number of wounds equal to their ranks in Toughened.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('VAAPADCONTROL', 'Vaapad Control', 'When making a Lightsaber combat check, the character may suffer 1 strain to downgrade the difficulty of the check a number of times equal to the number of light side Destiny Points in the Destiny pool.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BOD', 'Body Guard', 'Once per round, perform the Body Guard maneuver to guard an engaged character. Suffer a number of strain no greater than ranks of Body Guard, then until the beginning of the next turn upgrade the difficulty of combat checks targeting the protected character by that number.', 'taManeuver', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COMBATPROG', 'Combat Programming', 'Once per encounter when working on a droid, the character
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CONSTSPEC', 'Construction Specialist', 'The character removes [SE] per rank of Construction Specialist from checks made to construct bases, defense works, positions,  ortiflcations, tunnels, bunkers, and similar combat engineering projects.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CREATDES', 'Creative Design', 'As part of resolving a successful crafting check, the character may also apply a result equivalent to spending a number of [AD] equal to his ranks in Creative Design.  The GM may then apply a result equivalent to spending that same number of [TH].', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DESPREP', 'Desperate Repairs', 'Once per session, the character may make a [B]Hard ([DI][DI][DI]) Mechanics check[b] targeting one engaged drold.  If the character succeeds, the droid becomes staggered and immobilized until the end of its next turn.  At th  end of its next turn, the droid heals all
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DESFLAW', 'Design Flaw', 'When making a combat check with a personal scale weapon against a droid, the character adds [AD] equal to his ranks of Design Flaw', 'taIncidental', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DOCKEXP', 'Dockyard Expertise', 'The character may make an [B]Average ([DI][DI]) Knowledge (Education) check[b] when at a dry dock with suitable personnel and equiprnent to conduct repairs to a starship, or to add attachments or modifications to one.  If successful, the cost and time for repairs is reduced by 20% for each rank of Dockyard Expertise, to a minimum of 100 credits and one day.', 'taAction', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IMPDEF', 'Improvised Defenses', 'The character may attempt an [B]Average ([DI][DI]) Survival check[b] to fashion small defenses using scavenged materials.  If the check is successful, the structure can
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IMPPOS', 'Improvised Position', 'The character may make a [B]Hard ([DI][DI][DI]) Mechanics check[b] and spend 12 hours constructing a secure position that can contain the group and its vehicles. The sum of its vehicles'' silhouettes must be 4 or less.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASTDEMO', 'Master Demolitionist', 'When resolving an attack from a personal (non-starship/vehicle)
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PUSHSPEC', 'Push the Specs', 'The character may perform the Push the Specs action
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('REPPATCHSPEC', 'Repair Patch Specialization', 'Whenever the character uses an emergency repair patch, the target heals an additional wound per rank of Repair Patch Specialization. The sixth emergency repair patch and beyond each day still has no effect. If the character is a droid, it may use this talent when using a patch on itself.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SMARTHAND', 'Smart Handling', 'Once per session, while aboard a starship of silhouette 4 or higher, the character may take the Smart Handling action; making a [B]Hard ([DI][DI][DI]) Knowledge (Education) check[b]. If the check is successful, until the start of the next round, the ship''s handling increases by two plus one per [AD] scored on the check to a maximum handling of +4.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WEAKFOUND', 'Weak Foundation', 'Once per game session, the character may identify
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ASTEPAHEAD', 'A Step Ahead', 'Once per session, the character may suffer two strain in order to count his Cunning as one higher than normal for the remainder of the encounter.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ANALYZEDATA', 'Analyze Data', 'Once per session, after capturing or stealing data about an opponent, the character may perform the Analyze Data action to make an [B]Average ([DI][DI]) Knowledge (Warfare) check[b] to determine its value. If successful, once before the end of the session the character may add automatic [SU] equal to his ranks in Knowledge (Warfare) to one check related to that captured data. The GM has the final say on what checks are related to the data.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CUNNINGPERSONA', 'Cunning Persona', 'The character may suffer two strain to make a Charm check using Cunning instead of Presence.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EXHAUSTIVEQUESTIONING', 'Exhaustive Questioning', 'Whenever the character makes a successful social skill check against a captured enemy within short range, he may reduce the enemy''s strain threshold by 2 for the remainder of the session and spend [AD] to inflict 1 strain.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HIDDENSTORAGEIMP', 'Hidden Storage (Improved)', 'The character may use Hidden Storage to store an item within his own suitably modified body (such as through cybernetics, surgery, or prosthetic replacements).', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INCITEDISTRACTION', 'Incite Distraction', 'While in a crowd or populated area, the character may perform the Incite Distraction action to make an [B]Average ([DI][DI]) Deception check[b]. If successful, enemies treat the area as difficult terrain for the remainder of the encounter. The character may spend [TR] to make the location impassable terrain to them instead.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INDISIMP', 'Indistinguishable (Improved)', 'The character may extend the effects of Indistinguishable to a number of allies within short range equal to his ranks in Deception.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INSIDEKNOWLEDGE', 'Inside Knowledge', 'Once per session, the character may perform the Inside Knowledge action to make a [B]Hard ([DI][DI][DI]) Skulduggery check[b] while within an enemy facility or vessel. He can then find a single personal scale weapon or device he previously stashed here with a rarity no greater than his Cunning plus 2. Alternatively, he can gain a narrative benefit such as knowing the codes to open sealed doors, the location of the commander''s office, personality quirks or weaknesses amongst personnel, which security cameras have been deactivated or broken, secret or concealed rooms, or some other equivalent type of information.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWTHEIRWEAKNESS', 'Know Their Weakness', 'Once per session, the character may choose one target within short range and perform the Know Their Weakness action to make a [B]Hard ([DI][DI][DI]) Perception check[b]. If successful, the character downgrades the difficulty of social skill checks he makes against that target once per rank of Know Their Weakness.', 'taAction', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWTHEIRWEAKNESSIMP', 'Know Their Weakness (Improved)', 'The character may extend the effects of Know Their Weakness to a number of enemy characters within short range equal to his rating of Presence.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('USERTALENT1', 'Lose Them', 'When being followed or chased, may make a [B]Hard[DI][DI][DI] Stealth[b] check as an action. If successful, add [SE] [SE] to checks to follow them for the remainder of the encounter and may spend [TR] from the check to lose pursuers completely.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MADEYOUTALK', 'Made You Talk', 'Made You Talk
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INSIDEPERSON', 'Inside Person', 'Once per session, the character may spend a Destiny Point to establish he has previously been undercover gathering information in an identified enemy base or large vehicle. For the remainder of the session, add automatic [AD][AD] to checks he or his allies make that are associated with that location (such as checks to attack it or social skill checks targeting personnel in it).', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NATATHL', 'Natural Athlete', 'Once per session, reroll any 1 Athletics or Coordination check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PILOTTRAINING', 'Pilot Training', 'Piloting (Planetary) and Piloting (Space) become career skills.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RESISTQUESTIONING', 'Resist Questioning', 'When targeted by an opposed social skill check, the character may suffer 2 strain to perform the Resist Questioning out-of-turn incidental, adding [SE] to the check. If the check fails, he may spend [DE] to indicate he has provided false or misleading information that the target believes to be true.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RESISTQUESTIONINGIMP', 'Resist Questioning (Improved)', 'When one ally within short range is targeted by an opposed social skill check, the character may perform Resist Questioning to affect this check instead. If the check fails, he may spend [DE] to indicate the ally has provided false or misleading information that the target believes to be truthful.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BOCOAN', 'Boring Conversation Anyway', 'Once per session, may spend [AD][AD][AD] or [TR] from a failed social check to make an attack against the target of that check as an incidental', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FRLOW', 'Friends in Low Places', 'Once per session, may reveal a contact they owe a favor to who can get them access to an object or service. Undertake 2 Obligation to this character, or add [TH][TH] to checks to secure services or attain the object.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DUBX', 'Double-Cross', 'Once per encounter, may make a Hard [DI][DI][DI] Deception check to reveal how the character’s previously unknown scheming has a meaningful impact on the current scene [I]See Long Text[i]', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MAODL', 'Master of Dealing', 'May suffer 2 strain to reduce the difficulty of any check to find, buy, or sell stolen, contraband, or otherwise illegal goods once.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('OPP', 'Opportunist', 'Add [BO] per rank of Opportunist to combat checks made against enemies who have attacked an ally this round, or are otherwise distracted.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SWI', 'Swindler', 'Add [BO] or remove [SE] per rank of Swindler from checks to cheat or commit subterfuge.[BR]
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BLATHER', 'Blather', 'Make a Hard[DI][DI][DI] Charm or Deception check. One adversary per success (within medium range) is disoriented for a number of rounds equal to the character''s Presence rating. The character may spend a [TR] result from the check to stagger one affected target for one round.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DODGEIMP', 'Dodge (Improved)', 'When the character performs the Dodge incidental, the character may make a Move maneuver as an out-of-turn incidental after the triggering attack has been resolved.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ASQULA', 'Ask Questions Later', 'Once per encounter, after defeating a foe with a Ranged (Light) attack, may spend 1 Destiny Point. Add[AD], [SU], or [TR] to the next social check made against a present enemy based on defeated enemy NPC type.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SHFR', 'Shoot First', 'Once per session, if an enemy would attack, may spend 1 Destiny Point to make a Ranged (Light) attack as an out-of-turn incidental against the attacker. If attacker also activates this talent the effects for both are cancelled and initiative order takes precedence', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SPITIMP', 'Spitfire, Improved', 'Once per encounter after a successful combined check with two Ranged (Light) weapons, may spend [AD][AD][AD][AD] or [TR] to generate an additional hit of the primary weapon, which must be allocated to different enemy from the original target.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TRSH', 'Trick Shot', 'Remove [SE][SE] imposed on Ranged (Heavy) or Ranged (Light) checks due to target''s cover or from aiming. Additionally, the Game Master may allow the character to target enemies they don’t have line of sight on, if they are aware of their presence.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CRUELCOM', 'Cruel Commander', 'When upgrading the ability of a Mass Combat check in a mass combat in which the character is commander of the acting force (or when upgrading the difficulty, if the character is the commander of the enemy force), the character may use ranks in Coercion instead of ranks in Leadership.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RESPDEL', 'Respected Delegate', 'The character downgrades the difficulty of social skill checks made to interact with government institutions outside of their homeworld a number of times equal to their ranks in Respected Delegate.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ONORDER', 'On My Order', 'The character may take the On My Order action, making a Hard ([DI] [DI][DI]) difficulty Leadership check. If the check succeeds, the character chooses a number of crew aboard their ship equal to their Presence. Those crew members upgrade the ability of their next Gunnery check once, plus one time for every additional two [SU] results on the check.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DROIDCOMM', 'Droid Commander', 'Once per encounter, the character may perform Field Commander as a maneuver instead of an action. All affected allies must be droids.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LEADBACK', 'Lead from the Back', 'Once per round when an enemy makes a successful combat check targeting the character, the character may spend 1 Destiny Point to perform the Lead from the Back incidental. The character chooses one allied NPC subordinate within short range, who becomes the target of the attack instead.', 'taIncidentalOOT', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LEADFRONT', 'Lead from the Front', 'After succeeding on a Leadership check or other check to inspire, lead, or rally an audience, the character may spend 1 Destiny Point to upgrade the ability of the next combat check made by each ally within short range once.', 'taIncidental', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SAVVY', 'Savvy', 'The character adds [BO] to Charm and Negotiation checks they make per rank of Savvy.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RESISTQUEST', 'Resist Questioning', 'When one ally within short range is targeted by an opposed social skill check, the character may perform Resist Questioning to affect this check instead. If the check fails, they may spend a [DE] to indicate the ally has provided false or misleading information that the target believes to be truthful.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DIPIMMUN', 'Diplomatic Immunity', 'Once per encounter, the character may perform the Diplomatic Immunity incidental. The character spends one Destiny Point, and adversaries cannot choose the character as the target of a combat check until after the end of the character''s next turn. This effect ends if the character makes a combat check.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RESALLOC', 'Resource Allocation', 'At the beginning of a mass combat, the character may make a Hard ([DI][DI][DI]) Charm or Negotiation check to increase their force''s strength by one step for the duration of the encounter. The character may spend a [TR] result from the check to upgrade the ability of their force''s first Mass Combat check once.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NOBFOOLIMP', 'Nobody''s Fool (Improved)', 'When targeted by a Charm, Coercion, or Deception check, the character may spend a [DE] result or [TH][TH][TH] results from the check to inflict strain on the opponent equal to the character''s ranks in Nobody''s Fool.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ORDSAT', 'Ordnance Saturation', 'When the character or an ally who is currently benefiting from On My Order or Fire When Ready activates the Blast quality of a planetary-scale weapon, all ships or vehicles within close range of the target suffer damage equal to the weapon''s Blast quality (plus 1 per additional [SU], as usual).', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FIREREADY', 'Fire When Ready', 'The character may take the Fire When Ready action, making a Hard ([DI][DI][DI]) Leadership check. If the check succeeds, the character chooses a number of crew aboard their ship equal to their Presence. Those crew members downgrade the difficulty of their next Gunnery check once, plus one time for every ([SU][SU]) results on the check.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PRECON', 'Preexisting Condition', 'Once per session, may make a Hard ([DI][DI][DI]) Medicine check. On success, the character makes an on observation of a (previously unnoted) medical condition a character in the scene is suffering from. The Game Master determines whether the condition is purely narrative in nature, or is a Critical Injury with a difficulty no greater than Medium ([DI][DI]), and what effect it has on the encounter.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DONOHA', 'Do No Harm*', 'Once per session, take the Do No Harm action; make a Hard ([DI][DI][DI]) Cool check. If successful, may not be targeted by combat checks until the end of the encounter, or until making a combat check.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DRSORD', 'Doctor''s Orders*', 'When recovering under your supervision, characters heal an additional wound whenever they passively heal wounds, and add [SU] to any check to heal their critical injuries.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IMPSURG', 'Surgeon (Improved)*', 'When performing a Medicine check, may suffer strain up to ranks of Surgeon, then choose to either remove that many [SE] or add that many [BO].', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('VOIREA', 'Voice of Reason*', 'Once per encounter when making Leadership or Negotiation skill check, the character may use a Knowledge skill instead. Check uses Presence and player must explain how, in this particular instance, their Knowledge skill is persuading others or driving the conversation.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HEALSELF', 'Heal Thyself*', 'When performing a check to heal themselves, may substitute Resilience instead of the required skill to avoid increasing the difficulty of the check.  This includes Mechanics checks to heal cyborgs or droids, but does not apply to Resilience checks to passively heal critical injuries.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CAPTAUDI', 'Captive Audience', 'Once per session, may make a Hard ([DI][DI][DI]) Charm or Deception check to captivate a group of people with a performance. On Success, add [FA] to checks made by audience for the duration of the performance. May spend [TR] to add [FA][FA] instead.', 'taAction', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LIGHMOOD', 'Lighten the Mood', 'When recovering at the end of an encounter, may roll [B]Average[DI][DI] Charm[b] check. On Success, allies equal to Presence add [SU] to their recovery rolls. The character may spend [AD][AD] to have an affected ally add an additional [SU]to their check, and may spend [TR] to recover the same number of strain as one affected ally.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HYPASSAULT', 'Hyperspace Assault', 'The character may use Astrogation or Knowledge (Warfare) to determine their Initiative during an encounter in which they are piloting or commanding a starship. If they do so, they may spend a [TR] result from the check to choose the starting locations of all allied ships in the encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('OUTMAN', 'Outmaneuver', 'The character may take the Outmaneuver action, making a Hard ([DI][DI][DI]) Knowledge (Warfare) check. If the check succeeds, until the end of the character''s next turn, one enemy ship per [SU] must perform one extra maneuver in order to move or change range bands relative to the character''s ship or allies.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EXCEEDSPEC', 'Exceed Specifications', 'Before making a check using an item, the character may take the Exceed Specifications incidental, adding a [BO] to the check. The GM may spend [TH][TH] results on the check to damage the item one step, or [DE] to damage it beyond usability. [TH] or [DE] results may have additional consequences depending on the nature of the item, at the GM''s discretion.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EXCEEDSPECIMP', 'Exceed Specifications (Improved)', 'When the character takes the Exceed Specifications incidental, upgrade the ability of the check once instead of adding a [BO]', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EXCEEDSPECSUP', 'Exceed Specifications (Supreme)', 'If the character''s check benefitting from the Exceed Specifications incidental generates a [TR], they may damage the item one step to roll one additional [PR] and add it to the check results. If the check generates a [DE], roll a [CH] and add it to the results.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ONETRASH', 'One Person''s Trash', 'The character may make a Perception check in order to locate a particular item amid a battlefield, shipwreck, junkyard, or other location with potential salvage. The difficulty of the check is equal to half the item''s rarity, rounded down. There is no cost to acquire an item this way, but the item is in need of moderate repairs when found.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UTILIMP', 'Utility Belt (Improved)', 'Once per session when the character performs a Utility Belt incidental, they may produce up to five functionally identical items.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LEVER', 'Leverage', 'The character removes a [SE] per rank of Leverage from their Cool and Negotiation checks.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BACKROOM', 'Backroom Deal', 'Once per encounter, the character may take the Backroom Deal action, making a Hard ([DI][DI][DI]) Negotiation check. If successful the player reveals how their previously unknown dealings have a meaningful impact on the current scene or encounter. The nature of the revelation and its impact on the scene are ultimately subject to the GM''s discretion, but they should give a significant advantage to the PCs. If the check fails and generates a [DE] , however, the GM may decide that the character''s disastrously failed deal has negative repercussions.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CONCOPT', 'Consider our Options', 'The character may take the Consider Our Options action,  making a Hard ([DI][DI][DI]) Negotiation check. If successful any enemy who attacks the character suffers 2 strain, plus 1 strain per additional [SU][SU] results on the character''s check, before resolving the attack. (If this strain causes an adversary to become incapacitated, the GM may determine that adversary simply bows out of the fight.) The effect end immediately if the character inflicts damage on an enemy.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CONCOPTIMP', 'Consider our Options (Improved)', 'May choose to have the effects also apply to attacks that target allies who are within short range. The effects end for all characters if the character or an affected ally inflict damage on an enemy.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SUMMONITEM', 'Summon Item', 'When the character purchases this talent, choose one item they own of encumbrance 4 or less. As a maneuver, the character can summon this item to their hand or dismiss it from their hand back to the depths of Dathomir, regardless of the character''s location. Once per session, the character can spend one hour to ceremonially prepare a different item to be summoned. The character can have only one item prepared in this way.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WITCHCRAFT', 'Witchcraft', 'The character gains a Force rating of 1. If the character already has a Force rating of 1 or higher, there is no effect.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ICHORBLADE', 'Ichor Blade', 'Choose one Melee or Brawl weapon they possess that does not feature electronic or other high-tech parts.  The weapon gains the Cortosis and Pierce 2 item qualities and reduces its critical rating by one to a minimum of 1. In addition, any other character adds [SE] to checks they make to use this weapon. If the weapon is ever lost or destroyed, the character can apply Ichor Blade to a new weapon. If the weapon leaves the character''s possession for longer than a single scene or encounter, it loses all effects of this talent until the character reacquires it.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ICHORBLADEIMP', 'Ichor Blade (Improved)', 'The weapon affected by the character''s Ichor Blade talent also gains the Sunder and Defensive 1 item qualities, and increases its damage by 2.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ICHORTRANS', 'Ichor Transfusion', 'Once per encounter, the character may perform the Ichor Transfusion maneuver. The character may heal any number of their current wounds by suffering that number of strain +1. The character may instead heal any number of their current strain by suffering that number of wounds +1.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ICHORRES', 'Ichor Reserve', 'Once per session, the character may suffer 2 strain to perform the Ichor Reserve maneuver. Their Force rating increases by 1 until the end of the scene or encounter. At the GM''s discretion, the character may need to occasionally return to Dathomir to replenish their supply of magickal ichor.', 'taManeuver', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COVEN', 'Coven', 'Force talent. The character may perform the Coven maneuver. On their next Force power check, they may reroll one [FO] for each ally within short range who also possesses the Coven talent.', 'taManeuver', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SURVINST', 'Survivor''s Instincts', 'Once per session after the character suffers a Critical Injury but before the result is rolled, they may spend 1 Destiny Point. Then, the attacker must roll two results for the Critical Injury and the player chooses which will apply to their character.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RENFORM', 'Renegade Form', 'When the character purchases this talent, they choose one characteristic. They may use this characteristic in place of Brawn when making Lightsaber checks.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SECRETFORCE', 'Secrets of the Force', 'Knowledge (Lore) and Lightsaber become career skills for the character.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RAVAGE', 'Ravage', 'Force talent. Once per encounter, the character may suffer 3 strain to add [FO] up to their current Force rating to a combat check targeting an engaged opponent. The character may spend Force points to add [SU] or [AD] to the results of the check. The character gains 1 Conflict at the beginning of each session.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('JETPEXP', 'Jetpack Expertise', 'The character may spend [AD] checks they make to remove 1 system strain from a jetpack they are equipped with. (can be done multiple times per check).', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SIDESTEPIMP', 'Side Step (Improved)', 'Until the start of their next turn, they may spend [TH][TH][TH] or [DE] from a combat check targeting them to inflict one hit on that attacker from a Ranged (Heavy) or Ranged (Light) weapon the character is currently wielding. The hit deals its base damage plus any damage from applicable talents or abilities. This talent may not be used if the original attack incapacitates the character.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TOTHEDEATH', 'To the Death!', 'Once per session, the character may take the To the Death! maneuver, suffering strain no greater than their Willpower rating. For each strain suffered this way, add +10 to Critical Injury rolls the character inflicts and suffers until the end of the encounter.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HITANDRUN', 'Hit and Run', 'While the character is using a jetpack, after they complete an attack targeting an opponent they are engaged with, the character may immediately disengage as an incidental.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DEATHABOVE', 'Death from Above', 'Once per encounter while using a jetpack, the character may take the Death from Above action, inflicting 1 system strain on their jetpack and making a [DI][DI][DI] [B]Pilot (Planetary)[b]. If successful, one adversary of silhouette 0 or 1 per [SU] within short range is knocked prone. May spend [TR] result from the check to stagger one affected adversary until the end of that adversary''s next turn.', 'taAction', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MOMENTUM', 'Momentum', 'When making a melee attack, the character deals additional damage equal to the number of range bands they moved during the current round.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DANGDEV', 'Dangerous Development*', 'When making a check to improve or craft an item, may suffer 2 strain and upgrade the check once. On [SU], may add a single permanent improvement to the item.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EURE', 'EUREKA!*', 'Once per session, may spend strain equal to difficulty of a successful Intellect check to add a [TR] to that check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SME', 'SME*', 'Once per encounter, may spend 1 Destiny point to add [BO] [BO] [BO] to any check the character makes to which their personal experience is relevant.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('REVEG', 'Reverse Engineering*', 'Once per session, may make a Knowledge (Education) or Mechanics check to create a copy of a piece of personal gear the character has access to, with the difficulty and time required based on the object replicated.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('USERTALENT2', 'Reverse Engineering (Imp)*', 'May scrap the original item instead of paying credits when taking the Reverse Engineering action. May also spend [TR] to grant the item the [B]Superior[b] quality at the cost of one Hard Point.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SYNTH', 'Synthesis*', 'Once per encounter, may make a Hard [DI][DI][DI] Medicine check to create a chemical equivalent to any medical supply or chemical compound with a rarity of Intellect + [SU] or lower. [See Long Text]', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TECBAB', 'Technobabble*', 'Once per session, may make a Hard[DI][DI][DI] Knowledge (Education) check to establish a fact that solves a current problem.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HIDFEA', 'Hidden Feature*', 'Once per session while aboard a vessel, may declare a hidden feature about the vessel as if a Destiny Point had been spent.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('OVBATT', 'Overcharged Battery*', 'Once per round while piloting or operating a starship, before the character or an ally makes a Gunnery check, may have the starship suffer 2 system strain to increase the damage of the attack by 2 or reduce the Critical Rating by 1 (minimum of 1).', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CANNIB', 'Cannibalize*', 'Once per encounter, may add [SU] to a check to improve or repair a piece of gear or a vessel by scrapping an appropriate piece of gear.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FICAL', 'Field Calibration*', 'May make an Avg [DI][DI] Mechanics check to add [SU] to the next check made by an ally using an engaged Vessel or piece of Equipment, and may spend [AD][AD] or [TR] to extend this effect to an additional check.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FICAIMP', 'Field Calibration (Imp)*', 'Once per round, may suffer 2 strain to perform Field Calibration as a maneuver.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FITES', 'Field Tester*', 'Remove [SE] per rank of Field Tester from checks made using equipment or vessels the character has repaired or improved this session.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FITUIMP', 'Fine Tuning (Imp)*', 'Once per encounter, make a Hard[DI][DI][DI]Mechanics check to increase the system strain threshold of starship or vehicle by ranks of Fine Tuning for the rest of the encounter. Spend [AD][AD][AD] or [TR] to have craft recover that much system strain.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('JULINE', 'Just Like New*', 'Spend 1 Destiny Point to treat a damaged (not destroyed) piece of equipment within medium range as if it isn’t damaged until the end of the character''s next turn.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KIBA', 'Kitbash*', 'Short Text - Once per session, may make a Hard [DI][DI][DI] Mechanics check and scrap a piece of gear to combine it with a vehicle or item with a larger silhouette, granting the latter a quality or feature from the scrapped item.[BR] Please see Maintainer Respecialized for additional details.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MADMAI', 'Madcap Maintenance*', 'Once per session, may reroll one check to repair or maintain. If the rerolled check succeeds, add [TR] to the next check made using the item. Otherwise, the item becomes damaged further.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SOREIMP', 'Solid Repairs (Imp)*', 'Once per encounter, make a Hard [DI][DI][DI] Mechanics check to increase the armor of the ship they are on by 1 until the end of the encounter. Spend [AD][AD] to have that ship recover one hull trauma.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DESFLA', 'Design Flaw (Imp)*', 'As an action make an opposed Computers vs Discipline check targeting a disabled or restrained Droid, downgrading the difficulty of that check once per rank of Design Flaw the character possesses. Make an opposed [B]Computers vs Discipline[b] check targeting a disabled or restrained Droid to extract useful information from their databanks. Downgrade the difficulty once per rank of Design Flaw.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DIREC', 'Directive*', 'Once per round, may perform the Directive maneuver and suffer strain no more than ranks in Directive. Upgrade the ability of the next check made by an allied droid within short range a number of times equal to strain suffered.', 'taManeuver', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IMPDIREC', 'Improved Directive*', 'Once per encounter when performing the Directive maneuver, may affect an additional allied droid within medium range per rank of Directive.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SUPDIREC', 'Supreme Directive*', 'Once per session, may make a Hard[DI][DI][DI] Leadership check. A number of allied droids within medium range up to ranks of Directive may use Character’s ranks of 1 skill until the end of character’s next turn. Spend [TR] to extend this effect 1 round.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FINDIREC', 'Final Directive*', 'Once per session, when an allied droid would be incapacitated or destroyed, may spend 1 Destiny Point to allow that droid to make an immediate maneuver, followed by an action.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ACCACC', 'Accomplished Accomplice*', 'Once per encounter, when allied character within short range of Droid Companion would fail a check, may spend 1 Destiny Point to add [BO] equal to their ranks in the skill to the check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DROCOM', 'Droid Companion*', 'Choose a PC or NPC Droid as a Droid Companion. Choose two skills. The Droid Companion adds [AD] to checks using those skills.[BR]
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BINALLY', 'Binary Allies*', 'May choose an additional NPC Droid as an additional Droid Companion per rank of Binary Companions.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MACMENIMP', 'Machine Mender (Imp)*', 'When making a check to repair a droid, may spend [AD][AD] to increase the droid’s melee or ranged defense once, and may spend [TR] to increase its Soak by 1 until the end of the session.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('THANMAK', 'Thank The Maker!*', 'Once per session when Droid Companion would be incapacitated or destroyed, may spend 1 Destiny Point. They are not defeated until the end of the character’s next turn.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IMPREPPAT', '(Imp) Repair Patch Specialization*', 'Once per droid per encounter, after applying a repair patch to a Droid, that droid adds [SU][AD] to the next check they make this encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COMP', 'Compelling Counterpart*', 'Choose one social skill per Droid Companion. While engaged with Droid Companion, add [AD] to checks using the chosen skill.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('AGAODD', 'Against The Odds*', 'Add [BO] per ranks of Against the Odds to [B]Daunting[b] or harder checks.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MAKITINT', 'Let’s Make It Interesting*', 'Once per session while gambling, may have an opponent bet or stake something of distinct narrative or material value, which is won or lost during the current wager.[BR]
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MAKLUCK', 'Make Your Own Luck*', 'Once per session, may make a [B]Hard[DI][DI][DI][b] Cool Check. Allies equal to ranks of Cool may reroll 1 (+) die on their next check, and an additional die for every [SU][SU] past the first. Spend [AD][AD] or [TR] to allow an affected ally to reroll (+) or (-) dice this way.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('REVFOR', 'Reversal of Fortunes*', 'Once per session, after rolling a [DE] result, may spend 1 Destiny Point to cancel it, and add a [DE] to the next check made by an adversary. The [I]player[i] should have a justification for how action or fate have turned this misfortune around and made it the problem of an adversary in the scene.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RAISSTAK', 'Raise The Stakes*', 'Suffer 2 strain to perform the Raise the Stakes incidental to increase and upgrade the difficulty of the next check once. If successful, add [AD] equal to the final difficulty of the check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RAISTAIMP', 'Raise The Stakes, Improved*', 'When performing the Raise the Stakes incidental, also double the number of [TR] and [DE].', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SWIND', 'Swindler*', 'Add [BO] or remove [SE] per rank of Swindler from checks to cheat or commit subterfuge.[BR]
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BOLSPRES', 'Bolstering Presence*', 'Once per session, when an ally within Medium range would exceed their strain threshold, may spend 1 Destiny Point to have them recover strain equal to the character’s [B]Presence[b].', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KILKINIMP', 'Kill With Kindness (Imp)*', 'Once per session, make a Formidable [DI][DI][DI][DI][DI] Charm or Leadership check to make one allied or neutral character provide assistance during this encounter. Reduce the difficulty once per rank of Kill with Kindness
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HAPPHELP', 'Happy to Help*', 'When assisting or being assisted, add [BO] to the check in addition to the normal effects of assistance.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HAPHELIMP', 'Happy to Help (Imp)*', 'Once per encounter, when assisting or being assisted, upgrade the ability of that check, and all involved characters recover 2 strain.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BYPSECIMP', 'Improved Bypass Security*', 'May spend [AD][AD][AD] or [TR] from checks to unlock doors or disable a security device to add [BO] equal to ranks of Bypass Security to similar checks in the same system or location this session. [I]See Long Text[i]', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DECOY', 'Decoy*', 'Once per session, may spend a Destiny Point to produce a facsimile of an encumbrance 1 or smaller item in the scene. A character must make an opposed [B]Perception vs. Skulduggery[b] check to determine it is a fake.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DIRTTRIC', 'Dirty Tricks', 'Once per session, make a [B]Hard[DI][DI][DI] Skullduggery[b] check to add [SE] equal to [SU] to the next check made by a number of enemies equal ranks of Cunning.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EXITSTRA', 'Exit Strategy*', 'Once per session, make a Hard [DI][DI][DI] Vigilance check to notice a way out of the location. On Success, a discrete path of egress presents itself. Add [BO] to all checks the character or allies within medium range make to leave the encounter.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FADEAWAY', 'Fade Away*', 'Once per encounter, when targeted by a combat check, may spend 1 Destiny Point to add [SE] equal to ranks in Stealth. If that attack is unsuccessful, the character may not be targeted by attacks until their next turn.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HANDOFF', 'Hand Off*', 'Once per round, as an out-of-turn incidental, may suffer 2 strain to covertly exchange up to two encumbrance 1 or smaller items with an ally within short range. [I]See Long Text[i]', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STAKEOUT', 'Stakeout', 'Once per session, while trying to surveil a person or location, make a [B]Hard[DI][DI][DI] Cool[b] or [B]Skullduggery[b] check. If successful, gain [AD][AD] on checks involving the person or location this session', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ADAPT', 'Adaptable', 'When resolving a check that uses a skill in which they have no ranks, the character may spend one Destiny Point to remove a [DE] result from the check or to remove [TH] results equal to their ranks in Cool from the check.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SOMEPROVE', 'Something to Prove', 'Once per session, the character may suffer 4 strain in order to reroll a failed check. If the check succeeds, the character heals 4 strain.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LEARNOPP', 'Learning Opportunity', 'Once per round, the character may spend three [AD] results from a check they fail to upgrade the ability of their next check once.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BEGLUCK', 'Beginner''s Luck', 'Once per session when the character makes a check, the character may add [SU] results equal to the number of light side Destiny Points in the Destiny pool to the results.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TEMPLETR', 'Temple Training', 'Before making a Lightsaber skill check, the character may spend one Destiny Point to add damage to the attack equal to his ranks in Knowledge (Lore).', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SINFLAT', 'Sincerest Flattery', 'Once per encounter when the character makes a check using a skill that another character has previously used during the encounter, they add two [BO] dice.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SIDEBYSIDE', 'Side by Side', 'While the character is wielding a lightsaber and engaged with one or more allies also wielding a lightsaber, add a [TH] result to all combat checks that target the character or those allies. (If multiple allied characters in the engagement possess this talent, the effects are cumulative.)', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WILLFORCE', 'Will of the Force', 'Once per round after failing a skill check, the character may convert one dark side Destiny Point to a light side Destiny Point.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GUARDREP', 'Guardian of the Republic', 'After the character uses Parry or Reflect to reduce damage to an ally, that ally cannot be targeted by combat checks for the remainder of the round.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FALLBACK', 'Fall Back!', 'While engaged with an opponent, the character may suffer a number of strain up to their ranks in Leadership to allow an equal number of allies to immediately disengage from that opponent as an out-of-turn incidental.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STANDFIRM', 'Stand Firm!', 'Once per encounter, may take the Stand Firm! action, making a [B]Hard [DI][DI][DI]Leadership[b] check. If the check is successful, the character chooses one ally within medium range for each success on the check. Until the end of the encounter, chosen allies increase their wound threshold by an amount equal to the character''s Presence rating. (Multiple uses of this talent are not cumulative.)', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PREEMPTINTER', 'Preemptive Intervention', 'Immediately after an opponent moves to engage an ally within short range of the character, the character may spend one Destiny Point to engage that opponent as an out-of-turn incidental.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INSPIRKILL', 'Inspiring Kill', 'The character may spend one Destiny point to perform an Inspiring Kill maneuver immediately after conducting a successful attack in which the target is incapacitated or suffers a Critical Injury. The character rolls F[FO] no greater than their Force rating, and may spend [FP] to heal 2 strain from allies within medium range (and may do so multiple times).  A character who has purchased this talent gains 1 Conflict at the beginning of each game session.', 'taManeuver', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NATCHAMP', 'Natural Champion', 'Once per game session, the character may reroll any one Leadership or Lightsaber check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STANDFIRMIMP', 'Stand Firm! (Improved)', 'Allies affected by Stand Firm! also increase their strain threshold by an amount equal to the character''s Presence rating. (Multiple uses of this talent are not cumulative.)', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWSTR', 'Knowledge is Strength', 'Once per session, when making a check, the character may increase their Force rating by their ranks in Knowledge (Warfare) for the duration of the check. A character who has purchased this talent gains 1 Conflict at the beginning of each game session.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EXEMPREP', 'Exemplar of the Republic', 'When making a Mass Combat check for which the character is the acting commander or takes a prominent role on the battlefield, the character may add [FO] no greater than their Force rating to the check. The character may spend [FP] to add [SU] or [AD] (character''s choice) to the result.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BOUNDTO', 'Bound Together', 'The character may perform the Bound Together maneuver. Until the start of the character''s next turn, when the character or an ally within short range suffers strain involuntarily, they reduce the amount suffered by the current number of light side Destiny Points in the destiny pool.', 'taManeuver', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FLOWALL', 'Flows Through All Things', 'Once per round, the character may perform the Flows through all Things maneuver to recover strain equal to their Force rating.', 'taManeuver', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('POWALLY', 'Powerful Ally', 'The character may spend a Destiny Point to use the basic version of a Force power they have not purchased or to apply the effects of a single unpurchased control upgrade to a power they have purchased.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASTORDER', 'Master of the Order', 'The character may spend two Destiny Points during a single action.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NOTRY', 'There Is No Try', 'Once per session before any ally rolls the dice for a check, the character may spend a Destiny Point to allow the ally to automatically succeed at the check with one success and no other results.', 'taIncidentalOOT', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CENTBEINGSUP', 'Center of Being (Supreme)', 'When the character performs the Center of Being maneuver, until the beginning of their next turn, ranged weapons also treat their critical rating as one higher per rank of Center of Being when attacking the character.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ANIMCOMP', 'Animal Companion', 'Choose an animal no larger than Silhouette 2 to be an Animal Companion. Upgrade all checks made to soothe or heal them once.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ANCOIMP', 'Animal Companion (Improved)', 'Animal Companion may now be no larger than Silhouette 3. Attacks targeting an Animal Companion treat their critical rating as 1 higher.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BRTHIN', 'Break Them In', 'Make a Hard [DI][DI][DI] Athletics check to train one or more animals, upgrading the difficulty by the Animal’s Willpower. On success, one animal gains Trained Mount 1 until the end of the session, plus 1 animal per additional [SU][SU].', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASTRID', 'Master Rider', 'Once per turn while mounted, may suffer 2 strain to perform a Survival Check or other mount-handling action as a maneuver.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RIDDOW', 'Ride Down', 'While mounted, the mount’s Brawl attacks and any rider’s melee attacks deal additional damage equal to the speed of the mount.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TRUSCOMP', 'Trusty Companion', 'Once per session when successfully attacked, may spend 1 Destiny Point and perform the Trusty Companion out-of-turn incidental to have an Animal Companion within medium range become the target of the attack instead.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WILYRIDE', 'Wily Rider', 'Count mounted animals as having a silhouette as 1 lower when being attacked. Minimum of 0.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WRANGLE', 'Wrangle', 'Once per round, as a maneuver, may suffer strain up to ranks in Athletics. An animal or foe within short range adds :Setback: equal to strain suffered to their next action and treats their surroundings as difficult terrain until the character’s next turn.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ATTVEC', 'Attack Vector', 'Once per encounter, may Make a Hard [DI][DI][DI] Perception check to identify a weak point in an enemy vehicle or structure. On success, aim maneuvers made to target it before the end of the character’s next turn add [SU] in addition to normal effects. [See Long Text]', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COMBARMS', 'Combined Arms', 'Allied characters within short range of a vehicle piloted by the character treat their ranged defense as equal to the highest defense zone of that vehicle.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FIRSUPIMP', 'Fire Support (Improved)', 'After making a successful attack, may spend 1 Destiny Point to extend the benefit of Fire Support to all allies within [I]planetary[i] close range.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ONEINAMIL', 'One in a Million', 'Once per session, when inflicting a critical hit, may suffer 3 strain to change the result to any Hard[DI][DI][DI] Critical Hit.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TRIGDISC', 'Trigger Discipline', 'Once per encounter, may spend 1 Destiny point to remove [TH] up to ranks in Discipline from a Ranged attack check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SUSTFIRE', 'Sustained Fire', 'When performing an Aim maneuver, if the character successfully attacked the target this or last round, upgrade the ability of that attack instead of the aim’s normal effects (cannot be used to target a specific item or part of the target).', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASTMISS', 'Master Missileer', 'Before rolling a [B]Guided[b] attack, may suffer strain up to ranks of the weapon’s combat skill to upgrade the ability of the [B]Guided[b] roll that many times.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WEAPFREE', 'Weapons Free', 'Once per encounter, as a maneuver, may ignore a weapon’s [B]Slow-Firing[b] quality this turn and upgrade the difficulty of the next check using it equal to its ranks of [B]Slow-Firing[b].', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MANUOVER', 'Manual Override', 'Once per encounter, may make a Daunting[DI][DI][DI][DI] Coordination check to set a piloted starship or vehicle''s system strain to its threshold if it is over. Spend [TR] to immediately take another action.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PLAMAISYS', 'Planned Maintenance System', 'Repairs made to Signature Vehicle cost 25% less per rank of Planned Maintenance System, rounded down.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SIGVEHSUP', 'Signature Vehicle (Supreme)', 'Once per session, may spend 1 Destiny Point to add [TR] to a check involving the Signature Vehicle as an out-of-turn incidental.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNAUREQU', 'Unauthorized Requisition', 'Once per session, may make a Hard[DI][DI][DI] Knowledge (Underworld) check to establish ownership of ill-gotten munitions or equipment, with a cost no greater than 250 credits per rank of Knowledge (Underworld).
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CORSLIIMP', 'Corellian Slip (Improved)', 'Spend [TH][TH][TH] or [DE] from attacks targeting the character or an ally within close range benefitting from Evasive Maneuvers to inflict a hit on the attacker.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BREOFF', 'Break Off', 'Once per encounter, when an allied vehicle within close range becomes the target of an attack, may make a Hard[DI][DI][DI] Vigilance check to become the target of the attack.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CORESLIP', 'Corellian Slip', 'While performing Evasive Maneuvers, allies equal to ranks in Vigilance in close range gain the benefits of Evasive Maneuver.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MATHSPEE', 'Match Speed', 'Once per round when an ally within close range performs the Accelerate/Decelerate, Fly/Drive, or Punch it maneuver, may suffer 2 strain to perform the same maneuver to follow that ally as an out-of-turn incidental.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ASSASSIN', 'Assassinate', 'When inflicting a critical injury on a minion group, if undetected by them, may spend additional [AD] to remove an additional member per [AD] spent.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ASSASIMP', 'Assassinate (Improved)', 'Before rolling a combat check while undetected by the target, suffer strain up to [BO] in pool to trade that many [BO] for that many [AD]. Assassinate may remove a Rival by spending [AD][AD][AD] or [TR].', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FROMSHAD', 'From the Shadows', 'While undetected by enemies, the character may use the Stealth Skill when making checks to determine initiative.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NOWITNES', 'No Witnesses', 'Once per encounter, after incapacitating an enemy, may make a [B]Hard[DI][DI][DI] Stealth[b] check. On success, they are undetected as the attacker. May spend [AD] to move one range band per [AD] spent, and may spend [TR] to escape the scene completely.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PREAIMIMP', 'Precise Aim (Improved)', 'When using Precise Aim, all non-Gunnery attacks made by the character this round have their Pierce rating increased by ranks in Precise Aim.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PERFCRIM', 'The Perfect Crime', 'Once per session may make a [B]Hard[DI][DI][DI] Skullduggery[b] check to reveal how a previously unknown plan assists them in a crime or attack during this scene.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ALWAPREP', 'Always Prepared', 'Once per session, incidental may produce a previously undocumented item or weapon (with restrictions) as if a Destiny Point was spent.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HOTSWAP', 'Hot Swap', 'After changing weapons, add [BO] per rank of Hot Swap to the next attack made with weapons not yet used in this encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASOFARM', 'Master of Arms', 'Master of Arms
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASARMIMP', 'Master of Arms (Improved)', 'May spend [AD][AD] or [TR] from Master of Arms check to immediately take another action.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASARMSUP', 'Master of Arms (Supreme)', 'When making the Master of Arms action, may choose any number of equipped weapons to increase one of its existing qualities’ rating by 2. Each of the chosen qualities cost one less [AD] to activate (to a minimum of one).
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TARGACQU', 'Target Acquired', 'Make an opposed [B]Coercion vs Discipline[b] check against a foe within Medium Range. On Success, immobilize that adversary until the end of the next round. Spend [AD][AD] to effect an additional foe.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TARACQIMP', 'Target Acquired (Improved)', 'When taking the Target Acquired action, add [BO] for each status effect affecting the target. Spend [TR] to [I]Stagger[i] an affected adversary.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EYEOSTOR', 'Eye of the Storm', 'Perform the Eye of the Storm maneuver, suffer 1 strain, to make next Brawl attack this turn gain the [B]Blast[b] quality with a rating equal to ranks of Brawn plus ranks of Discipline. Blast triggered on this attack only affects foes.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
