INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SMOOOPER', 'Smooth Operator', 'After making a successful Gunnery attack, spend a Destiny Point and suffer strain no greater than [SU] to convert that many [SU] to [AD].', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
