INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TOOLREBE', 'Tools of Rebellion', 'Once per session, may make a Hard[DI][DI][DI] Knowledge (Underworld) or Knowledge (Warfare) check. On Success, an amount of weapons and equipment suitable to outfit allies equal to [SU] is covertly stashed nearby.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ACALLAID', 'A Call For Aid', 'Once per session, the character may make a Hard[DI][DI][DI] Charm check. On success, the character reveals how a previously unknown call for aid has a meaningful impact on the scene.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ESCACLAU', 'Escape Clause', 'Once per session when under scrutiny by authorities, make a Hard[DI][DI][DI] Knowledge (Core Worlds) check to cite law or regulation that exempts or exonerates them.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GREAGOOD', 'For the Greater Good', 'Once per session after being successfully attacked, the character may make a Hard[DI][DI][DI] Discipline check to ignore the damage and the effect of this attack until the end of the encounter after which, the character suffers the damage, and the effects of any exceeded thresholds, status effects, or critical injuries, in that order.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RESPKIND', 'Respond In Kind', 'May spend [TH][TH][TH] or [DE] from an incoming social check to add [SU][AD] to the next Charm, Negotiation, or Leadership check the character or an ally makes targeting that adversary.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNITPEOP', 'Uniter of People', 'Once per session, may choose a faction or group and make a Hard[DI][DI][DI] Charm or Negotiation check. On success, allied characters and the chosen faction within medium range add [AD] to skill checks this encounter
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ACTILIST', 'Active Listener', 'When targeted by an opposed social check, may suffer 2 strain to oppose the check with Perception instead of Cool or Discipline, but still use the characteristic associated with the replaced skill.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CODEIMPR', 'Codebreaker (Improved)', 'Once per session, may choose a faction or group and make a Hard[DI][DI][DI] Computers check to gain insight on their plans or communications. On success, may add [FA] equal to ranks of Codebreaker to one check made by that group this session.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ACTLISIMP', 'Active Listener (Improved)', 'When using Active Listener, may also suffer strain up to ranks of Perception to add that many [SE] to the check.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HEROEMBE', 'Heroic Embellishment', 'Once per encounter, may spend 1 Destiny point to add [AD] equal to ranks of Charm to an ally’s check. If that ally’s Duty triggered this session, add [TR] instead.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SHIFNARR', 'Shift The Narrative', 'Once per session, choose an organization and make a Hard[DI][DI][DI] Charm or Deception check. On success, each member of that organization adds [SE] or [BO] to each check they make this session.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MARTYRDO', 'Martyrdom', 'Once per encounter after being successfully hit by an attack, may suffer 3 strain to add [DE] to the check.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SHINARIMP', 'Shift The Narrative (Improved)', 'When taking the Shift The Narrative action, may spend [AD][AD][AD] or [TR] to increase or decrease the difficulty of the first check members of the targeted organization make each encounter this session.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SHINARSUP', 'Shift The Narrative (Supreme)', 'The group affected by Shift The Narrative increases or decreases their wound threshold by 1, plus an additional 1 for each additional [SU][SU][SU] until the end of the session.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FINDSTOR', 'Find The Story', 'Once per session, may make an Average [DI][DI] Perception check to identify a local compelling narrative. On success, add [SU] to all checks made to utilize that story this session. [See Long Text]', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WARIDEA', 'War of Ideas', 'When a foe makes a social check to persuade a third party, may suffer strain up to ranks of Knowledge (Warfare) to add that many [SE] to the check. If it fails, upgrade the ability of all social checks targeting that party or the foe once for the remainder of the session.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EMEROUTF', 'Emergency Outfitting', 'Once per session, may make an Average[DI][DI] Vigilance check to reveal an undisclosed piece of personal gear, and may spend [AD][AD][AD] or [TR] to produce additional equipment equal to ranks of Vigilance.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FATAFLAW', 'Fatal Flaw', 'Once per encounter, may make a Hard[DI][DI][DI] Perception or Vigilance check to determine that enemy equipment is substandard. Enemies equal to [SU][SU] add [TH][TH] to checks using this equipment in this encounter.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FORAGOOD', 'For A Good Cause', 'Once per session, may spend 1 Destiny Point to reduce purchase price of a single object or service by 5% times the character’s Contribution Rank
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MISAPPR', 'Misappropriate', 'Once per session, make a Hard[DI][DI][DI] Computers or Skulduggery check to reveal how a previously unknown theft or oversight has a meaningful impact on the scene.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WELLSUPP', 'Well-Supplied', 'Once per round when an ally attempts a skill check, may spend 25 credits times the difficulty of the check to add [SU] to that check.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BOOBTRAP', 'Booby Trap', 'Once per encounter as an action, may create a trap. Any other character who moves to engaged range of the trap must make an opposed [B]Vigilance vs. Skullduggery[b] check to avoid harm and ill effects.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASKBLAS', 'Masked Blast', 'Before using explosives, may spend a Destiny Point to establish an even louder noise to mask it. Bystanders must make an opposed [B]Vigilance vs Stealth[b] check to notice the sound of the explosion.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASTSABO', 'Master Saboteur', 'Personal-scale explosives the character uses or sets gain Sunder, and each [AD] spent to activate the Sunder quality damages the target item two steps instead of one.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CONSTRUC', 'Constructor', 'When constructing bases, defenses, positions, or other similar combat engineering projects, add [BO] or remove [SE] per rank of Constructor.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CONSTRIMP', 'Constructor (Improved)', 'While benefiting from cover from a position they have constructed, the character and allies increase their soak against ranged attacks by 1 per rank of Constructor.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COUNMOBI', 'Counter-Mobility', 'While defending a position, the character may make a Hard[DI][DI][DI] Survival check. On Success, foes treat an approach to this position out to extreme range as difficult terrain. Spend [AD][AD][AD] to increase range to [B]planetary[b] close.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COUMOBIMP', 'Counter-Mobility (Improved)', 'Add [TH] to checks made by foes in the chosen approach. May spend [TH][TH][TH] from a foe’s check to immobilize them for rounds equal to characters ranks of Survival, or cause a minor collision.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CONDIMP', 'Conditioned (Improved)', 'Once per session while falling, may spend 1 Destiny Point to reduce range bands fallen by ranks of Conditioned (minimum Short).', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FIELRESE', 'Field Researcher', 'On a successful Knowledge check, reduce the difficulty of the next check the character makes to act on this information once per rank of Researcher (minimum Easy[DI]).', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HISTORIAN', 'Historian', 'When recalling information about or interacting with ancient or abandoned places or things, add [BO] or remove [SE] per rank of Historian.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HISTIMP', 'Historian (Improved)', 'Once per session when interacting with ancient or abandoned places or things, may spend 1 Destiny Point to cancel a [DE] or [TH] equal to ranks of Historian from a check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWACTI', 'Knowledge In Action', 'Spend 1 Destiny point when making a skill check that involves technology to substitute a Knowledge skill instead of the required skill.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STERSTUF', 'Sterner Stuff', 'Once per session, when the character would exceed their strain threshold make a Hard [DI][DI][DI]Discipline check to reduce strain to 1 below the threshold instead.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNEAANSW', 'Unearth the Answer', 'Once per session, may make a Hard [DI][DI][DI] Knowledge (Lore) to reveal that an item or place conceals a hidden secret that solves a problem in the current scene.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WATCSTEP', 'Watch Your Step', 'Once per session, may make a Hard [DI][DI][DI] Athletics check to have all other characters within short range suffer 1 wounds plus 1 wound per each [SU]. Spend [AD] and [TR] for additional effects.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HUNTIMP', 'Hunter (Improved)', 'After the character inflicts a critical injury on or incapacitates a foe with an attack, or otherwise causes a critical injury or incapacitation of a foe, the character may perform a maneuver as an incidental. This does not allow the character to perform more than 2 maneuvers per turn, but may allow them to make maneuvers out-of-turn.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HUNTSUP', 'Hunter (Supreme)', 'Once per round, perform a maneuver and suffer strain up to non-Vehicle target’s silhouette to reduce critical rating of the next non-Gunnery attack by the same amount (minimum 1).', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FINTUNIMP', 'Fine Tuning (Improved)', 'Once per encounter, make a Hard[DI][DI][DI]Mechanics check to increase the system strain threshold of starship or vehicle by ranks of Fine Tuning for the rest of the encounter. Spend [AD][AD][AD] or [TR] to have craft recover that much system strain.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('QUICPICK', 'Quick Pickup', 'Once per encounter while piloting a starship or vehicle, make a Hard [DI][DI][DI] Piloting check to have any number of allies within medium range of the craft board it as an out-of-turn incidental.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DESPSCRA', 'Desperate Scramble', 'Once per session, make a Hard [DI][DI][DI]Coordination check to escape through a previously unknown method. On success, the character is able to escape confinement or reposition, and may spend [AD][AD][AD] or [TR] to allow allies to follow. [I]See Long Text[i]', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FEARJUMP', 'Fearless Jump', 'Once per session, may reroll an Astrogation check to make a hyperspace jump, adding [TR] [DE] to the result. The [DE] added this way cannot be canceled by effects of talents, abilities, or equipment.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ODDJOB', 'Odd-Job', 'Once per session, after successfully negotiating the purchase goods or services, may substitute an offer to perform a task or favor in lieu of payment.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASTNONE', 'Master of None', 'Once per round, may add [SU] to a skill check using a skill in which the character has less than 2 ranks.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PARTUNCH', 'Parts Uncharted', 'Once per session, may make a Daunting [DI][DI][DI][DI] Astrogation check to yet-undiscovered route. On success, the route charted is either immediately ready for jump, untraceable and unrepeatable, or the shortest possible distance. Spend [TR] for all three.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BOLSTER', 'Bolster', 'As a maneuver, the character may remove [SE] per rank of Bolster imposed by a single environmental circumstance from all actions they make this encounter. This may be used multiple times to remove setbacks imposed by additional environmental circumstances.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BOLSTIMP', 'Bolster (Improved)', 'When the character performs the Bolster maneuver, the benefits apply to all allies within short range.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KEEEYEIMP', 'Keen Eyed (Improved)', 'Once per session, may make a Formidable[DI][DI][DI][DI][DI] Perception or Vigilance check to add [SU] to next checks they and Allies make to act on observation. Decrease difficulty of check once per rank of Keen Eyed.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NATUREME', 'Natural Remedy', 'When in the wilderness, may use Survival instead of Medicine to heal wounds and critical injuries by increasing the difficulty of the check once.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ONLOOK', 'On The Lookout', 'When making a check to determine initiative, may spend 1 Destiny point to add [SU] to character’s check and to a number of allies’ check equal to Cunning.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('READWIND', 'Read The Wind', 'Once per encounter make a Hard[DI][DI][DI] Perception check. On success, a moderate environmental effect appears. Spend [TR] for a severe environmental effect.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('REAWINIMP', 'Read the Wind (Improved)', 'May suffer 2 strain to perform the Read The Wind action as a maneuver.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('REAWINSUP', 'Read the Wind (Supreme)', 'Once per round, may suffer strain up to ranks in Perception to remove that many [SE] imposed due to environmental conditions from an enemy’s check, and add an equal number of [FA] or [TH]. If >3, may add [DE] instead.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ITSABARG', 'It’s a Bargain', 'When buying goods, may have them become damaged one step to reduce the price by 20%.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ITSASTEA', 'It’s A Steal', 'When selling damaged or misrepresented goods, may make an opposed [B]Deception vs. Vigilance[b] check, and treat their value as if they were undamaged and genuine. Upgrade the difficulty of the check based on damage and misrepresentation.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MARKCONN', 'Market Connections', 'May make a Knowledge (Core Worlds) or (Outer Rim) to locate a willing local seller of a particular legal good, and add [SU] to checks to purchase that item from that seller. The difficulty of the check is determined by the rarity of the item.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MARCONIMP', 'Market Connections (Improved)', 'May take the Market Connections action to locate a seller of an illegal good using Knowledge (Underworld) instead by aditionally upgrading the difficulty of the check once.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MARCONSUP', 'Market Connections (Supreme)', 'May spend [AD][AD][AD] or [TR] from Market Connections action to have the seller include a related item with a value or rarity no greater than half that of the original item, rounded down, at no additional cost.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WHE&DEAIMP', 'Wheel & Deal (Improved)', 'When selling goods illegally, the character may upgrade the difficulty of the check once to gain 10% more credits per rank of Wheel and Deal. This includes locally restricted, stolen, or otherwise illegal goods.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SOMEREAL', 'Something More Real', 'May spend 1 Destiny Point when negotiating the cost of goods or services to introduce physical goods to be bartered, counted at 150% their current value, instead of or in addition to credits.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ONLOOKOU', 'On The Lookout', 'When making a check to determine initiative, may spend 1 Destiny point to add [SU] to character’s check and to a number of allies’ check equal to Cunning.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PERSBODY', 'Personal Body Guard', 'Once per encounter before an attack is made targeting an ally within short range, may move to their position and perform the Body Guard Maneuver as an out of turn incidental.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PERBODIMP', 'Personal Body Guard (Improved)', 'Once per session when performing the Body Guard Maneuver, may spend 1 Destiny point to have all attacks targeting the guarded character target the user instead until the user''s next  turn. Upgrade each attack targeting the character equal to the strain suffered performing the  Body Guard maneuver.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SAWCOMIN', 'Saw it Coming', 'Once per Encounter; make a Hard[DI][DI][DI] Perception check to add [TH][TH] to all attacks made against the character or allies within short range until their next turn. Spend [TR] to add [FA] to those attacks.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TIMTOGOSUP', 'Time To Go (Supreme)', 'Once per encounter when activating Time to Go, a number of allies equal to Cool may suffer 2 strain to also perform a maneuver as an out-of-turn move incidental to attempt to move into cover or out of the blast range of a weapon or explosion.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MAKIDOOR', 'Making A Door', 'Once per encounter, make a Hard[DI][DI][DI] Skullduggery check to treat an explosive as if it had the Breach 1 quality when breaching a specific structure or vehicle this encounter. Spend [AD][AD][AD] or [TR] to treat it as if it had Breach 2 instead.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STENERIMP', 'Steady Nerves (Improved)', 'Once per encounter when performing a check involving a precise and/or dangerous technical action, may suffer strain up to ranks of Steady Nerves to downgrade the difficulty of the check that many times.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FEARIMP', 'Fearsome (Improved)', 'May Spend [AD][AD] from Coercion checks or [TH][TH] from foes’ Discipline check to have the target suffer strain equal to ranks of Fearsome.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SENDMESS', 'Sending a Message', 'After incapacitating or inflicting a critical injury may spend 1 Destiny point. As a maneuver, make an opposed [B]Coercion vs Discipline[b] check to immobilize a target within medium range. Spend [AD][AD][AD] or [TR] to [I]Stagger[i] them for 1 round.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ORELSE', '…Or Else', 'Once per session, after the character or an ally within short range fails a Coercion check, or it results in a [DE] may suffer 3 strain to add [TR] to the result.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LOCK&LOAD', '**Lock and Load**', 'Once per encounter, may load or reload a weapon as an incidental, including those with the limited ammo quality.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SUPFIRIMP', 'Suppressing Fire (Improved)', 'Upon unsuccessful attack with non-starship or vehicle ranged weapon, may spend [AD][AD] up to ranks of Suppressing Fire. Upgrade the difficulty of the next check made by targeted character once per [AD][AD] spent.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BLOOLUST', 'Bloodlust', 'Once per hit, add [BO] per rank of Bloodlust to next check after incapacitating or inflicting a Critical Injury.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('JUGGERNAUT', 'Juggernaut', 'When suffering a critical injury, may spend 1 Destiny Point to reduce the result by 10 per rank of Resilience (minimum 1).', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KILORKILL', 'Kill Or Be Killed', 'Once per session, when the character would exceed their wound threshold, may spend 1 Destiny Point to make a melee attack. If the target dies, wounds become 1 below threshold instead.', 'taActionOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SAVARESP', 'Savage Response', 'When the character suffers a critical injury, may suffer 3 strain to inflict a hit with an equipped Melee or Brawl weapon, or an unarmed Brawl attack, against an engaged foe.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNYIELD', 'Unyielding', 'Once per attack, when the character is hit by a ranged attack, may suffer 2 strain to perform a Move maneuver as an out-of-turn incidental to move towards the attacker.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FOCUFIRE', 'Focus Fire', 'Once per encounter, increase the difficulty of your next ranged combat check by 1. If successful, upgrade the ability of each combat check made against the target once until the end of the character’s next turn.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PERTARIMP', 'Persistent Targeting (Improved)', 'After making one or more successful combat checks against a target, allies within short range equal to Leadership add [BO] to combat checks against that target for the remainder of the encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CARGDROP', 'Cargo Drop', 'Once per encounter, may make a Hard [DI][DI][DI] Skullduggery check to dump the ship’s cargo. Foes within short range equal to [SU] must drop to speed 1 or suffer a major collision.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MUSTSPEC', 'Mustafar Special', 'Once per round, may make an opposed Piloting vs Piloting check against starship or vehicle within close range. On Success, that craft suffers system strain equal to ranks in Cunning plus [SU]. Spend [AD][AD] to affect an additional craft within close range.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STELLDIST', 'Stellar Distraction', 'When a foe makes a check to detect, scan, or identify a starship the character is aboard, may spend 1 Destiny Point to upgrade the difficulty of that check a number of times equal to ranks in Astrogation.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WRETHIVE', 'Wretched Hive', 'Once per session, may make a Hard [DI][DI][DI] Astrogation or Knowledge (Underworld) check to identify the path to the nearest Shadowport. Upgrade all checks to travel to and interact with the Shadowport this session.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ENERSIPH', 'Energy Siphon', 'Once per encounter, may make an Opposed Athletics check against an engaged foe to drain the energy from an equipped item and recover strain equal to total encumbrance of drained item(s). Spend [AD][AD] or [TR] to drain an additional equipped item.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASTCYBE', 'Master Cyberneticist', 'Once per round, suffer 2 strain to decrease the difficulty of the next check to create, install, repair, or activate a cybernetic, or heal a cyborg once.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MACMANIMP', 'More Machine than Man (Improved)', 'As a maneuver, suffer 1 strain, and add [BO] to the next check equal to half the number of installed cybernetics, rounded up.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STROFLES', 'Stronger Than Flesh', 'Once per encounter, may avoid suffering a [DI] or [DI][DI]  severity critical injury by having an installed cybernetic immediately malfunction.[I]See Long Text[i]', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STRFLEIMP', 'Stronger Than Flesh (Improved)', 'Stronger Than Flesh may also be used to avoid crits of [DI][DI][DI] or [DI][DI][DI][DI] severity', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STRFLESUP', 'Stronger Than Flesh (Supreme)', 'Immediately after being hit by an attack but before suffering damage, spend 1 Destiny Point to increase Soak by half the number of installed cybernetics, rounded up.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EMERBYPA', 'Emergency Bypass', 'Once per encounter, when an engaged starship or vehicle suffers a critical hit, may spend 1 Destiny Point and suffer system strain equal to the severity to choose a different critical hit of the same severity.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SIGNSUPE', 'Signature Superiority', 'Once per encounter while aboard the Signature Vehicle, may make a Hard[DI][DI][DI] Mechanics check.  On Success, characters and allies equal to Intellect add [SU] to all checks involving the signature vehicle until the end of their next turn.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TINKIMP', 'Tinkerer (Improved)', 'Once per session, may spend 1 Destiny Point. Each item improved by character’s Tinkerer adds [AD] equal to ranks in Tinkerer to next check using that item.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PERMAI', 'Percussive Maintenance*', 'Once per encounter, as a maneuver, before making a check to repair or damage an engaged mechanical construct, may suffer 2 wounds to add [BO] to that check equal to ranks of Melee or Brawl.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SIGVEHIMP', 'Signature Vehicle (Improved)', 'Signature Vehicle may have a Silhouette or 5 or less. Increase that vehicle''s top Speed by 1, to a maximum of Speed 6.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SPECMODI', 'Special Modifications', 'Once per session, may make an Average[DI][DI] Mechanics check to temporarily convert an installed attachment into another valid attachment with equal or lesser Hard Points and Rarity.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNLOPOTE', 'Unlocked Potential', 'Once per session, character or ally within short range may spend [AD][AD][AD] or [TR] from a check using a vehicle or equipment to install a Mod of an attachment on that item until the end of the session. Spend additional [TR] to attach it permanently.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MAKEDANG', 'Make It Dangerous', 'Once per encounter, may make a Hard[DI][DI][DI] Knowledge (Education) check as a maneuver to add choice of Burn 1, Sunder, or Vicious 1 to an engaged weapon until the end of the character''s next turn. Spend [AD][AD] to extend the effect one round.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MAKDANIMP', 'Make It Dangerous (Improved)', 'May suffer 1 strain to decrease the difficulty of Make it Dangerous to Average [DI][DI], and may spend [AD][AD][AD][AD] or [TR] to give the weapon the Disruptor effect.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DELARESP', 'Delayed Response', 'Once per session after being detected or discovered, may spend 1 Destiny Point to delay alarm, pursuit or reprisal until the end of the character''s next turn.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FORCEXPL', 'Forceful Expulsion', 'Once per session, may make a Hard[DI][DI][DI] Computers check to eject an opposed slicer or another character accessing a connected system. Spend [AD][AD] to inflict strain equal to ranks of Knowledge (Education) on the target, and [TR] to render the opposed character''s slicer''s gear or accessed system unusable.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GHOSMACH', 'Ghost in the Machine', 'May suffer strain up to ranks in Stealth to add an equal number of [SE] or remove an equal number of [BO] from checks to trace, locate, or identify the character while they are slicing.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LOGIBOMB', 'Logic Bomb', 'Once per session, may make a Hard[DI][DI][DI] Computers check and choose a connected system or device and a triggering event. On success, when the event occurs, enact a single command in that system or have it shut down.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SHADSECR', 'Shadowfeed Secret', 'Once per session, may choose target location or faction, or person and make a Knowledge (Underworld) with a difficulty based on the target. On Success, may add [TR] to a Computers check to slice that target this session.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GLIDSTEP', 'Gliding Step', 'Add [BO] to melee attacks for each move maneuver performed this round.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MAKITCOU', 'Make It Count', 'Once per round, after an enemy cripples, destroys, or inflicts a critical hit on their ship or an allied ship within short range, may spend 1 Destiny Point to add [AD][AD] to the next check made by a number of allies equal to Presence.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BADMOTIMP', 'Bad Motivator (Improved)', 'Once per session when taking the Bad Motivator action, may choose a trigger that will cause the device to fail, rather than it failing immediately.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IMPDETSUP', 'Improvised Detonation (Supreme)', 'When taking the Improvised Detonation action, may add Burn +1, Concussive +1, Ensnare +1, Ion, Knockdown, Pierce +2, Stun +2, and/or Stun Damage qualities to the explosive, upgrading the the difficulty of the check once for each quality chosen.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('JAOATR', 'Jack of All Trades', 'Once per encounter when performing a skill check using skill with fewer ranks than ranks of Jack of All Trades, may suffer strain equal to the difference to upgrade the ability of the check an equal number of times.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DAZZFLOU', 'Dazzling Flourish', 'May spend [AD][AD][AD] or [TR] from a successful melee attack to upgrade the ability of each ally’s next attack targeting that enemy.  May spend [TR] from a failed melee attack for the same effect.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CENTOATT', 'Center of Attention*', 'While making a social or performance check before a gathering or audience, may suffer 2 strain to gain [TR] on success or [DE] on failure.[BR]
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BRAIMP', 'Brace (Improved)', 'When the character performs the Brace maneuver, they may choose one environmental circumstance. The benefits of Brace apply to that circumstance until the end of the encounter. (This benefit is not cumulative with further uses of the Brace maneuver, although the character may select additional circumstances with subsequent uses.)', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BRASUP', 'Brace (Supreme)', 'When the character performs the Brace maneuver, the benefits apply to all allies within short range.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TACTPLAN', 'Tactical Planning', 'Once per game session when performing an activity that requires a skill check, the character may choose to substitute a Knowledge (Warfare) check for the skill check that would normally apply. When they do this, they must explain how their tactical foresight is helping them overcome the challenge.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TACTEVA', 'Tactical Evasion', 'Upgrade the difficulty of any ranged combat checks targeting the character a number of times equal to the number of maneuvers the character has performed to move during the current round.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RAPIDFIRE', 'Rapid Fire', 'Before making a [B]Ranged (Light)[b] combat check using a weapon that does not have the [U]Limited Ammo[u] quality, the character may perform the Rapid Fire incidental to add the [U]Auto-fire[u] quality to the attack. After resolving the attack, the weapon runs out of ammo.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PRACSTRAT', 'Practiced Strategist', 'Once per session during a mass combat or combat encounter, the character may make an opposed [B]Knowledge (Warfare)[b] check targeting the enemy leader. If successful the check succeeds, the character (or player) reveals a narrative advantage provided by their strategic planning, up to GM''s discretion, but it should provide the character and their allies with a significant advantage in the encounter or session.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NATCOMM', 'Natural Commando', 'Once per session, the character may reroll one [B]Ranged (Light)[b] or [B]Stealth[b] check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWNPROG', 'Known Programming', 'Once per session, the character may choose a single model of droid that they have encountered before and make a [B]Hard[DI][DI][DI] Vigilance[b] check. If successful, minion and rival droids of that type upgrade the difficulty of their checks targeting the character, plus one ally per success result after the first, once for the rest of the encounter.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWNPROGIMP', 'Known Programming (Improved)', 'Affected allies also upgrade the ability of their checks targeting the chosen droid model once.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INGRAINLOY', 'Ingrained Loyalty', 'When the character makes a [B]Leadership[b] check targeting only clones, they may change the result of one [CH] dice to any nonblank face', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GETDROP', 'Get the Drop', 'Once per session, the character and any number of allies in the current encounter may add [SU] results equal to the character''s ranks in [B]Stealth[b] to initiative checks.. The player must explain how their character''s stealthy approach helps the PCs to get the drop on their opponents.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FORMTACT', 'Formation Tactics', 'As an action, make a [B]Hard[DI][DI][DI] Leadership[b] check. If successful, they may choose a number of allies within short range equal to [SU]. Attacks against these allies are upgraded once until the end of the character''s next turn. Effects do not stack.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FORMTACTIMP', 'Formation Tactics (Improved)', 'The difficulty [B]Average[DI][DI][b]. May also spend a [TR] result or [AD][AD][AD][AD][AD][AD] results to have the effect last until the end of the encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ENDURPRES', 'Enduring Presence', 'If commanding an active force may upgrade one [AB] or [DI] of a Mass Combat check once per session; even if the character is not present or is prevented from communicating with their troops.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DROIDCOMMIMP', 'Droid Commander (Improved)', 'Once per encounter may make an [B]Average ([DI][DI]) Leadership[b] check as a maneuver. Up to six droid allies may immediately suffer 1 strain to perform a free maneuver. Does not count towards their two maneuvers this round. If there are any questions as to the order in which allies act, the character using Field Commander is the final arbiter. May spend [TR] to have one droid ally take an action instead of a maneuver.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COMBATVET', 'Combat Veteran', 'Add [BO] to [B]Brawl[b] and [B]Discipline[b] checks equal to ranks in Combat Veteran.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CLANKKILLIMP', 'Clanker Killer (Improved)', '[B]Brawl[b] or [B]Melee[b] checks targeting droids lower their critical rating by one per rank of Clanker Killer (minimum of 1).', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CLANKILL', 'Clanker Killer', 'Before rolling a combat check that targets a droid (including a droid vehicle or a vehicle piloted by a droid), may trade [BO] up to ranks in Clanker Killer for [SU] or [AD] (in any combination).', 'taIncidental', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IDING', 'Identify Ingredients', 'After being exposed to any unknown substance may roll [FO] no greater than their Force rating and spend two [FP] to immediately identify the composition and any effects of the substance.', 'taIncidentalOOT', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IMPCONC', 'Improvised Concoction', 'Once per encounter, as an action, the character may make a [B]Hard[DI][DI][DI] Knowledge (Xenology)[b] check adding [FO] no greater than their Force rating. If successful create 1 dose of any potion, poison, or drug out of available materials. The rarity of this item must be lower than or equal to the character''s [B]Intellect+[SU]+[FP][b] spent.', 'taAction', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('OVERWAURA', 'Overwhelming Aura', 'As a maneuver, suffer 1 strain and commit [FO] up to Force rating or ranks of Overwhelming Aura to add that many [AD] to their social checks. Opponents within short range add an equal number of [TH] to their social checks.', 'taManeuver', true, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('POWDARK', 'Power of Darkness', 'Once per session, as a maneuver, increase wound and strain threshold by 1 per Dark Side Destiny point currently in the pool until the end of the encounter. Having this talent generates 1 Conflict at the beginning of each session.', 'taManeuver', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FONTPOW', 'Font of Power', 'Once per session, may perform the Font of Power action. Until end of encounter, whenever any Force user within medium range rolls [FO] they add 1 automatic [FP] matching the Font character’s Light/Dark orientation to the results .', 'taAction', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ACKLAYSCST', 'Acklay''s Scything Strike', 'The character''s [B]Brawl[b] attacks gain (or increase) [U]Pierce[u] equal to their Force rating.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TRANSMOG', 'Transmogrify', 'May add [FO] no greater than Force rating to crafting checks. Spend 1 [FP] to add [SU], Spend 2 [FP] to add [AD].', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INDWILL', 'Indomitable Will', 'Once per encounter, suffer 3 strain as a maneuver to commit a number of [FO] up to their Force rating. Reduce all damage the character suffers by an amount equal to the committed [FO] and the character suffers 1 strain at the beginning of each of their turns.', 'taManeuver', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CHANAG', 'Channel Agony', 'After rolling [FO], the character may choose to suffer wounds no greater than twice their ranks in Channel Agony. For every two wounds, they add [DA] to the results. The character gains 1 Conflict per rank at the beginning of a game session.', 'taIncidental', true, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EMBHATE', 'Embrace Your Hate', 'After a successful [B]Brawl, Lightsaber,[b] or [B]Melee[b] combat check, the character may spend one Destiny Point and then gain Conflict equal to dark side points in the Destiny pool to add an equal amount of damage to one hit of the attack. Usable once per encounter per rank. The character gains 1 Conflict per rank at the beginning of a game session.', 'taIncidental', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SAPITHSUND', 'Sapith Sundering', 'When making a [B]Brawl[b] check, may include [FO] up to Force rating. The  attack gains [U]Sunder[u]. [FP] generated on the check can be used as [AD] for activating [U]Sunder[u].', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TOUGHIMP', 'Toughened (Improved)', 'Once per session,  may heal wounds equal to  ranks in Toughened.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('VAAPADCONT', 'Vaapad Control', 'May suffer 1 strain to downgrade the difficulty of a [B]Lightsaber[b] check once per light side Destiny Point in the pool.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CUNNPERSON', 'Cunning Persona', 'May suffer two strain to make a [B]Charm[b] check using [B]Cunning[b] instead of [B]Presence[b].', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('POWPAIN', 'Power From Pain', 'Once per session, may spend a Destiny Point to gain +1 Force rating for each Critical Injury the character is suffering, until the end of the encounter. This talent automatically grants 1 Conflict at the beginning of each game session.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HIDDIMP', 'Hidden Storage (Improved)', 'May use Hidden Storage to store an item within their own suitably modified body (such as through cybernetics, surgery, or prosthetic replacements).', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INCITEDIST', 'Incite Distraction', 'While in a crowd or populated area, may make an [B]Average[DI][DI] Deception[b] check. If successful, enemies treat the area as difficult terrain for the remainder of the encounter. May spend a [TR] to treat the location as impassable terrain instead.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INSIDEKNOW', 'Inside Knowledge', 'Once per session while within an enemy facility or vessel, may make a [B]Hard[DI][DI][DI] Skulduggery[b] check to find a single personal scale weapon or device they previously stashed here with a (rarity no greater Cunning+2). [I][See Long Text for alternate options][i]', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWWEAK', 'Know Their Weakness', 'Once per session, may choose one target within short range and make a [B]Hard[DI][DI][DI] Perception[b] check. If successful, downgrade the difficulty of social skill checks (you) make against that target once per rank of Know Their Weakness.', 'taAction', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('JUYOSAV', 'Juyo Savagery', 'When the character inflicts a Critical Injury with a [B]Lightsaber[b] check, add +5 to the Critical Injury roll per dark side point in the Destiny pool. [I]This talent inflicts 1 Conflict at the beginning of each game session.[i]', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EXHAUSTQUEST', 'Exhaustive Questioning', 'When succeeding on a social skill check against a captured enemy within short range may reduce their strain threshold by 2 for the remainder of the session and spend [AD] to inflict 1 strain.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PILOTTRAIN', 'Pilot Training', '[B]Piloting (Planetary and Space)[b] become career skills.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RESISTQUESTIMP', 'Resist Questioning (Improved)', 'When an ally within short range is targeted by an opposed social check, may perform Resist Questioning to affect this check instead. If it fails, may spend [DE] to indicate the ally has provided false or misleading information that the target believes to be truthful.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ANTREAS', 'Another''s Treasure', 'When selling items their condition does not impact the price received. In addition a buyer can always be found, no matter its condition or how useless or worthless it may seem. The details of the transaction are subject to the GM''s discretion, as always, and a buyer might not be immediately (or easily) available.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ASSAULTDR', 'Assault Drop', 'Once per session while piloting a vehicle or ship, allow all passengers aboard or allies engaged with the vehicle or ship may immediately disembark or embark as an out-of-turn incidental.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BARREL', 'Barrel Roll', 'When a vehicle or starship (silhouette 3 or less) the character is piloting suffers a hit from a combat check, after damage is calculated but before armor is applied, suffer 3 system strain to reduce incoming damage of one hit by ranks of the [B]Piloting[b] skill being used. Usable once per attack.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BARRELIMP', 'Barrel Roll (Improved)', 'Reduce damage of all affected attack''s hits by ranks in the relevant [U]Piloting[u] skill.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BARRELSUP', 'Barrel Roll (Supreme)', 'When reducing damage from a weapon with the [U]Auto-fire[u], [U]Blast[u], or [U]Guided[u], may spend [DE] or [TH][TH][TH] to inflict one hit on the attacker or another enemy vehicle or starship within close range after the initial attack resolves dealing base damage of the original attack.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FIRESUP', 'Fire Support', 'After making a successful combat check using a vehicle weapon, the next ally to make a check adds [BO] equal to ranks of Fire Support.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FIRSTBRO', 'First Among Brothers', 'Add [AD] equal to ranks in First Among Brothers to any roll that does not have net [TH]. These additional advantages may only be used to affect allied clones.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FORREP', 'For the Republic!', 'Once per encounter when an ally is incapacitated or killed, make a [B]Daunting[DI][DI][DI][DI] Leadership[b] check. If successful, the ally is not incapacitated or killed until the end of the following round. If their wounds or strain are reduced below their threshold before the end of the next round, they are not incapacitated.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LATTHINK', 'Lateral Thinking', 'Once per encounter after an enemy succeeds on a check targeting the character, may spend one Destiny Point to force the enemy to reroll. If the enemy is a droid, the character does not spend a Destiny Point to use this talent.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ALCARTS', 'Alchemical Arts', 'After making a crafting check to create a potion or talisman, the character may choose to suffer strain no greater than twice their ranks in Alchemical Arts. For every two strain, they may add a [LI] or [DA] to the results. Each [DA] added also causes 1 Conflict.', 'taIncidental', true, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MISSCRIT', 'Mission Critical', 'Once per session after rolling a [B]Piloting[b] check but before resolving it, the character may spend a Destiny Point to add any combination of [SU] or [AD] equal to their ranks in that skill.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NATOP', 'Natural Operator', 'Once per session may reroll any one [B]Piloting[b] check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NATTROOP', 'Natural Trooper', 'Once per session may reroll any  [B]Gunnery[b] or [B]Ranged (Heavy)[b] check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SCRAPEM', 'Scrap ''Em!', 'After making a successful combat check, the character may suffer 2 strain to select a number of allies (up to ranks in Leadership) to add a [BO] on combat checks against the character''s target until the start of the character''s next turn.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SCRAPEMIMP', 'Scrap ''Em! (Improved)', 'Doubles [BO] granted and doubles allies that can be affected by Scrap Em!', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TACTADV', 'Tactical Advance', 'While in cover, may suffer 2 strain to allow character and allies within short range to move out of cover and continue to receive its benefits until beginning of your next turn.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TACTADVIMP', 'Tactical Advance (Improved)', 'Rather than suffer strain, may spend [AD][AD] from any check they make, or [TH][TH] from a combat check targeting them to perform the Tactical Advance incidental.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TRANSERR', 'Translation Error', 'Once per encounter, when making a social check may remove a [DE] from the results.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ATANYCOST', 'At Any Cost', 'May suffer a Critical Injury to force a Mass Combat check reroll. At GM discretion, the character may be required to sacrifice an item, vehicle, or individual of personal significance instead', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWWEAKIMP', 'Know Their Weakness (Improved)', 'Can now impact a number of enemy characters within short range equal to [B]Presence[b].', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LOSETHEM', 'Lose Them', 'When being followed of chased, make a [B]Hard[DI][DI][DI] Stealth[b] check. If successful, pursuers add [SE][SE] to checks to follow them for the remainder of the encounter. May spend [TR] from the [B]Stealth[b] check to completely lose their pursuers.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('OVERWAURAIMP', 'Overwhelming Aura (Improved)', 'Characters affected by your Overwhelming Aura add [FA] to fear checks the character causes and [SU] to fear checks not caused by the character. [I]This talent inflicts 1 Conflict at the beginning of each game session.[i]', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FEARSOMEEDIT', '*Fearsome', 'When an adversary becomes engaged with the character, the character may force the adversary to make a fear check, with the difficulty equal to the character''s ranks in Fearsome. [I]See Long Text[i]', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BATMEDBASIC', 'Battle Meditation Basic Power', 'The Force user directs allies in battle, making them more effective as a coordinated unit.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SENSEBASIC', 'Sense Basic Power', 'The Force user can sense the Force interacting with the world around him.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SENSECONTROL1', 'Control: Upgrade Difficulty', 'Commit [FO]. Once per round, when the target of an attack, upgrade the difficulty once [I](multiple activation not allowed)[i].', 'SENSE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SENSEDURATION', 'Duration', 'ongoing effect may be triggered one additional time per round.', 'SENSE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SENSESTRENGTH', 'Strength', 'When using Sense''s ongoing effects, may upgrade one additional die.', 'SENSE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SENSECONTROL3', 'Control: Upgrade Ability', 'Commit [FO]. Once per round, when the user makes a combat check, upgrade the ability of that check once[I](multiple activation not allowed)[i].', NULL, 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SENSECONTROL2', 'Control: Sense Thoughts', 'Spend [FP]. The user senses the current thoughts of one living target with whom they are engaged. (multiple activation allowed)', 'SENSE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SENSEMAGNITUDE', 'Magnitude', 'Spend [FP] to affect one additional target in range per rank of Magnitude.', 'SENSE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SENSERANGE', 'Range', 'Spend [FP] to increase power’s range by a number of range bands equal to Range ranks.', 'SENSE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BATMEDCONTROL1', 'Control: Orders', 'When making a [B]Battle Meditation[b] power check, may make an [B]Easy ([DI]) Leadership[b] check as part of the pool. If they are able to activate the power and succeed on the check, they may telepathically transmit a simple order to each character, (recipient comprehends it even if they do not understand the user''s language).', 'BATMED', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BATMEDCONTROL2', 'Control: Planetary Scale', 'Before attempting to activate the power, may suffer 4 strain to change the range of the Battle Meditation basic power to close on the planetary scale rather than engaged on the personal scale, for this use of the power only. Activating range upgrades increases the range of the power by planetary range bands.', 'BATMED', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BATMEDDURATION', 'Duration', 'Commit [FO][FO][FO] to sustain the ongoing effects of the power on each affected target while it remains in range.', 'BATMED', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BATMEDMAGNITUDE', 'Magnitude', 'Spend [FP] to increase the number of targets affected by an amount equal to user''s Presence per ranks of Magnitude.', 'BATMED', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BATMEDMASTERY', 'Mastery', 'If no [DA] were used to generate [FP], choose one skill. Each affected character counts as having the same number of ranks in the chosen skill as the affected character with the most ranks in the skill. [P]If any [DA] were used to generate [FP], each affected character must make an [B]Easy ([DI]) Discipline[b] check to resist obeying orders given by the user as part of this power.', 'BATMED', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BATMEDRANGE', 'Range', 'Spend [FP] to increase the power''s maximum range by a number of range bands equal to Range upgrades purchased.', 'BATMED', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BATMEDSTRENGTH', 'Strength', 'Spend [FP][FP] to add one additional automatic [SU] to affected characters'' checks.', 'BATMED', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BINDBASIC', 'Bind Basic Power', 'The Force user restrains an enemy, preventing the target from acting.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BINDCONTROL1', 'Control: Strain', 'Spend [FP]; whenever a target affected by Bind takes an action, they suffer strain equal to the user''s Willpower[I](multiple activation not allowed)[i].', 'BIND', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BINDCONTROL2', 'Control: Move', 'Spend [FP] to immediately move the target up to one range band closer or farther away.', 'BIND', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BINDDURATION', 'Duration', 'Commit [FO][FO][FO] to sustain the ongoing effects of the power on each affected target while it remains in range.', 'BIND', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BINDMAGNITUDE', 'Magnitude', 'Spend [FP][FP] to affect one additional target in range per rank of Magnitude.', 'BIND', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BINDMASTERY', 'Mastery', 'When the user is making a [B]Bind power check[b], if the check was not already opposed, the user may roll an opposed [B]Discipline vs. Discipline check[b] against one target of the power. If no [DA] were used to generate [FP] and the user succeeds on the check, they may immediately stagger the target until the end of their next turn. If any [DA] were used to generate [FP] and the check succeeds, the target suffers a Critical Injury, adding +10 to the roll per [FP] spent on the check.', 'BIND', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BINDRANGE', 'Range', 'Spend [FP] to increase power’s range by a number of range bands equal to Range ranks.', 'BIND', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BINDSTRENGTH', 'Strength', 'Spend [FP] to disorient the target for a number of rounds ranks in Strength.', 'BIND', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENHANCEBASIC', 'Enhance Basic Power', 'Combine with an [B]Athletics[b] check. The user may spend [FP] to gain [SU] or [AD] (user''s choice) on the check.', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENHANCECONT0', 'Control: Force Leap (Maneuver)', 'The user only needs to use a maneuver to perform a Force Leap, instead of an action.', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENHANCECONT1', 'Control: Coordination', 'The user gains the ability to use Enhance with the Coordination skill.', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENHANCECONT2', 'Control: Resilience', 'The user gains the ability to use Enhance with the Resilience skill.', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENHANCECONT3', 'Control: Force Leap (Horizontal)', '(Action) Make an [B]Enhanced power check[b]. The user may spend [FP] to jump horizontally to any location in short range. They can use this to leap over obstacles or impassable terrain, but cannot leap directly vertically.', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENHANCECONT4', 'Control: Piloting - Planetary', 'The user gains the ability to use Enhance with the Piloting (Planetary) skill.', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENHANCECONT5', 'Control: Brawl', 'The user gains the ability to use Enhance with the Brawl skill.', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENHANCECONT6', 'Control: Force Leap (Vertical)', 'When taking a Force Leap action, the user can leap to any location in range vertically as well as horizontally.', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENHANCECONT7', 'Control: Piloting - Space', 'The user gains the ability to use Enhance with the Piloting (Space) skill.', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENHANCECONT8', 'Control: Brawn', 'Ongoing Effect: Commit [FO]. The user increases their Brawn characteristic by 1 (to maximum of 6).', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENHANCECONT9', 'Control: Agility', 'Ongoing Effect: Commit [FO]. The user increases their Agility characteristic by 1 (to a maximum of 6).', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
