INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FORSEECONTROL1', 'Control: Initiative (Success)', 'When making a skill check to determine Initiative, the user may roll a [B]Foresee[b] power check as part of the pool. He may spend [FP] to gain [SU] on the check. The user may activate this multiple times.', 'FORSEE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FORSEECONTROL2', 'Control: Defense', 'When performing a [B]Forsee[b] power check as part of an initiative check, all targets affected by the power increase their ranged and melee defense by 2 for the first round of combat.', 'FORSEE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FORSEECONTROL3', 'Control: Initiative (Maneuver)', 'When performing a [B]Foresee[b] power check as part of an Initiative check, the user may spend [FP] to allow all affected targets to take one free maneuver before the first round of combat begins. The user may not activate this multiple times.', 'FORSEE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FORSEEDURATION', 'Duration', 'Spend [FP] to increase the days into the future visible equal to the number of Duration upgrades purchased.', 'FORSEE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
