INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FORSEESTRENGTH', 'Strength', 'The Force user can spend [FP] to pick out a number of specific details from their vision equal to ranks in Strength.', 'FORSEE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
