INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('INFLUENCEBASIC', 'Influence Basic Power', 'The character may attempt to guide, shape, and even twist the thoughts and feelings of other.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('INFLUENCECONTROL1', 'Control: Emotion/Belief', 'The Force user may make an opposed [B]Discipline vs. Discipline check[b] combined with an [B]Influence power check[b]. If the user spends [FP] and succeeds on the check, they can force the target to adopt an emotional state or believe something untrue, lasting for 1 round or 5 minutes. If the user has the ability to affect multiple minds with this power (such as with the Magnitude upgrade), the Discipline check either must be opposed by the mind with the highest ranks in Discipline, or its difficulty must be set statistically based on the number of minds (GM discretion).', 'INFLUENCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('INFLUENCECONTROL2', 'Control: Skills', 'When making a [B]Coercion, Charm, Deception, Leadership,[b] or [B]Negotiation[b] check,  roll an [B]Influence[b] power check as part of the pool. May spend [FP] to gain [SU] or [AD] (user choice) per point on the check.', 'INFLUENCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('INFLUENCEDURATION', 'Duration', 'Spend [FP] to increase duration by number of rounds (or minutes) equal to Duration upgrades purchased.', 'INFLUENCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('INFLUENCEMAGNITUDE', 'Magnitude', 'Spend [FP] to affect one additional target in range per rank of Magnitude.', 'INFLUENCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('INFLUENCERANGE', 'Range', 'Spend [FP] to increase power’s range by a number of range bands equal to Range ranks.', 'INFLUENCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('INFLUENCESTRENGTH', 'Strength', 'When stressing the mind of a target, the character inflicts 2 strain instead of 1.', 'INFLUENCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MISDIRBASIC', 'Misdirect Basic Power', 'The Force user creates illusions to fool those around them.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MISDIRCONTROL1', 'Control: Appearance', 'Instead of merely hiding an object or person from the target with this power, the user may alter the appearance of that object or person, making it appear to be something or someone else to the target.', 'MISDIRECT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MISDIRCONTROL2', 'Control: Illusion', 'Instead of hiding an object or person from the target with this power, the user may cause the target to see a vision of an illusory object, person, or creature where none exists. This phantasm can be silhouette 1 or smaller. To accomplish this, the Force user may also roll an opposed [B]Deception versus Vigilance[b] check (if the check was not already opposed) as part of the pool. To make the target experience the illusion, the user must generate enough [FP] to create the illusion and must succeed at the opposed check. If the user spent any [DA] to generate [FP] on this check, each target subjected to the unsettling illusion suffers 1 strain per [FP] spent on the check.', 'MISDIRECT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MISDIRCONTROL3', 'Control: Combat', 'The Force user gains the ability to blur their own form in the eyes of others, causing their attacks to miss vital spots and creating excellent opportunities for their own counterblows. Ongoing effect: Commit one or more [FO]: Add an automatic [TH] per [FO] committed to all combat checks made against the Force user.', 'MISDIRECT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MISDIRDURATION', 'Duration', 'Commit [FO][FO][FO] to sustain the ongoing effects of the power on each affected target while it remains in range.', 'MISDIRECT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MISDIRMAGNITUDE', 'Magnitude', 'Spend [FP] to affect one additional target in range per rank of Magnitude.', 'MISDIRECT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MISDIRMASTERY', 'Mastery', 'Spend [FP][FP] to increase the number of objects obscured or illusions created by an amount up to the user''s [B](Cunning)+(Deception)[b].', 'MISDIRECT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MISDIRRANGE', 'Range', 'Spend [FP] to increase power’s range by a number of range bands equal to Range ranks.', 'MISDIRECT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MISDIRSTRENGTH', 'Strength', 'Spend [FP][FP] to increase the silhouette of the object able to be obscured or the illusion created by 1 per ranks in Strength.', 'MISDIRECT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MOVEBASIC', 'Move Basic Power', 'The Force user can move small objects via the power of the Force.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MOVECONTROL1', 'Control: Hurl', 'The user can hurl objects to inflict damage. Resulting impacts deal damage to both target and the object being moved. The user makes a [B]Move[b] power check and rolls a ranged attack as part of the pool. The difficulty is equal to the silhouette of the object being thrown instead of the normal difficulty for ranged attacks, and only succeeds if the user can also spend enough [FP] to move the object. Silhouette 0 objects deal 5 damage, while other objects deal damage equal to 10 times their silhouette. The number of targets affected by a single object is up to the GM, but in general a single object should only affect a single target, unless the object is particularly large. If the player wants to use multiple objects to hit multiple targets, he may do so using the rules for hitting multiple targets with the Auto-fire quality. This attack follows all the rules for ranged attacks, including ranged defense and aiming.', 'MOVE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MOVECONTROL2', 'Control: Pull', 'The Force user can pull objects out of secure mountings or out of an opponent''s grasp.', 'MOVE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MOVECONTROL3', 'Control: Manipulate', 'The user can perform fine manipulation of items within this power''s range, allowing them to do whatever they could normally do with their hands via this power. If used to manipulate something such as a control board, the controls count as an object of silhouette 0.', 'MOVE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
