INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('WARFORDURATION', 'Duration', 'Spend [FP][FP] to have the bonuses apply to all relevant checks rounds equal to Duration upgrades purchased.', 'WARFOR', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('WARFORSTRENGTH', 'Strength', 'Spend [FP][FP] to gain [BO] (equal to ranks in Strength) on the user''s next check against the target (or directly involving the target, in the case of a non-combat check).', 'WARFOR', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('WARFORMAGNITUDE', 'Magnitude', 'When combining with an Initiative check, spend [FP] to add [SU] or [AD] to ally''s first check this encounter.', 'WARFOR', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('WARFORCONTROL2', 'Control: Maneuver', 'Once per encounter, the user may use the basic power as a maneuver.', 'WARFOR', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('WARFORCONTROL3', 'Control:  Initiative', 'When making  Warde''s Foresight power check as part of an Initiative check, they may spend [FP] to add automatic [AD] on their first check this encounter. The user may activate this multiple times.', 'WARFOR', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('WARFORCONTROL1', 'Control: Successes', 'When making a skill check to determine initiative, the user may roll this power check as part of the pool. They may spend [FP] to add automatic [SU] on their first check this encounter [I](multiple activation allowed)[i].', 'WARFOR', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('WARFORCONTROL4', 'Control: Ally Initiative', 'When performing a Warde’s Foresight power check as part of an Initiative check: [BR]([LI]) Each ally adds automatic [SU] to the results of their Initiative check if the user did not use [DA] to generate [FP]. [BR]([DA])The user may immediately perform an action before the encounter begins if they used [DA] to generate [FP], but each enemy in the encounter adds automatic [SU] to the results of their Initiative check.', 'WARFOR', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SUPPRESSBASIC', 'Suppress Basic Power', 'The Force user can dampen the effect of incoming force powers, dramatically diminishing their effects on themselves and their allies.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SUPPRESSRANGE', 'Range', 'Spend [FP] to increase power’s range by a number of range bands equal to Range ranks.', 'SUPPRESS', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SUPPRESSCONTROL3', 'Control: Strain', 'Whenever an enemy targets a character protected by Suppress with a hostile Force power, if that enemy used any [DA] to generated [FP] on the check, the enemy suffers strain equal to the user''s ranks in Discipline.', 'SUPPRESS', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SUPPRESSMASTERY', 'Mastery', 'Combine with an [B]opposed Discipline vs. Discipline[b] check targeting another Force user within short range. If the user spends [FP][FP] and succeeds on the check, the user causes the target Force user to immediately uncommit [FO] and immediately end all ongoing effects of Force powers, Force talents, and any other effects that required committed [FO].', 'SUPPRESS', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SUPPRESSCONTROL2', 'Control: Destiny', 'Once per game session, the user may spend a Destiny Point to use Suppress as an out of turn incidental.', 'SUPPRESS', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SUPPRESSSTRENGTH', 'Strength', 'Spend [FP] to add additional automatic [FA] (equal to ranks in Strength) to hostile Force power checks targeting characters affected by Suppress.', 'SUPPRESS', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SUPPRESSDURATION', 'Duration', 'Commit [FO] to sustain the ongoing effects of the power on each affected target while it remains in range.', 'SUPPRESS', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FARSIGHTCONTROL2', 'Control: Transparent', 'Spend [FP] to see through a single object at medium range as though it were transparent.', 'FARSIGHT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FARSIGHTMASTERY', 'Mastery', 'Spend [FP][FP]. The user now can see as though from a spot within close range (planetary scale) of the user''s body.', 'FARSIGHT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FARSIGHTCONTROL3', 'Control: Vigilance', 'Combine with a [B]Vigilance or Perception[b] check, and spend [FP] to gain [SU] or [AD] on the check.', 'FARSIGHT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FARSIGHTDURATION', 'Duration', 'Spend [FP] to increase duration by number of rounds or minutes equal to Druation upgrades purchased.', 'FARSIGHT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MANIPULATECONTROL3', 'Control: Mechanics', 'When making a [B]Mechanics[b] skill check, the user may roll a Manipulate power check as part of the pool and may spend [FP] to gain [SU] or [AD] (user''s choice) on the check. The user may activate this multiple times.', 'MANIPULATE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MANIPULATERANGE', 'Range', 'Spend [FP] to increase power’s range by a number of range bands equal to Range ranks.', 'MANIPULATE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MANIPULATEMASTERY', 'Mastery', 'When performing Manipulate power check as part of a Mechanics skill check, the user may spend [FP][FP] to gain [TR] on the check.', 'MANIPULATE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MANIPULATECONTROL5', 'Control: Inflict Strain', 'When performing a combat check against a droid, ship, vehicle or other mechanical construct within engaged range, the user may spend [FP] to inflict 1 additional strain or system strain on the target. The user may activate this multiple times.', 'MANIPULATE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MANIPULATESTRENGTH', 'Strength', 'When using this power to cause a target to recover strain or system strain or heal wounds. Spend [FP] to cause targets to recover 1 additional strain or system strain or heal 1 additional wound equal to ranks in Strength.', 'MANIPULATE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MANIPULATECONTROL4', 'Control: Heal Droid', 'The user may spend [FP] to heal a number of wounds equal to their Intellect in an engaged droid. This counts as the use of an Emergency Repair Patch. This may not be activated multiple times.', 'MANIPULATE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MANIPULATECONTROL1', 'Control: Item Damage', 'Ongoing effect: Commit [FO] One damaged weapon or item counts as being undamaged. This can be activated multiple times.', 'MANIPULATE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MANIPULATECONTROL2', 'Control: Increase System Strain', 'Ongoing efffect: Commit [FO] Increase the system strain threshold of 1 vehicle or starship at engaged range by 3 per [FO] commited.', 'MANIPULATE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MANIPULATEBASIC', 'Manipulate Basic Power', 'The Force user shapes machine components on a molecular level, allowing mending damaged medical systems
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MANIPULATECONTROL7', 'Control: Upgrade Computers and Mechanics', 'Commit [FO]. Upgrade the ability of Computers and Mechanics check once [I](multiple activation not allowed)[i].', 'MANIPULATE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MANIPULATECONTROL6', 'Control: Increase Hull Trauma', 'Ongoing effect: Commit [FO]. Increase the hull trauma threshold of 1 vehicle or starship at engaged range by 3 per [FO] committed.', 'MANIPULATE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FARSIGHTCONTROL6', 'Control: Fine Details', 'Spend [FP] to make out fine details on a single object within medium range.', 'FARSIGHT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FARSIGHTCONTROL4', 'Control: Perception', 'This power gains the ongoing effect: Commit [FO] after successfully activating the Farsight power to increase ranks in Perception by 1 (to max of 5) each time this is performed.', 'FARSIGHT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FARSIGHTCONTROL5', 'Control: Panoramic Vision', 'Spend [FP][FP] to see in every direction simultaneously, noticing and observing things in a full 360 degree arc.', 'FARSIGHT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FARSIGHTBASIC', 'Farsight Basic Power', 'The Force user expands normal visual senses through a connection to the Force.
