INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FARSIGHTRANGE', 'Range', 'Spend [FP] to increase power’s range by a number of range bands equal to Range ranks.', 'FARSIGHT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('IMBUEBASIC', 'Imbue Basic Power', 'The Force User lends strength to allies, making them more potent, resourceful, or resilient for a time.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('IMBUEDURATION2', 'Duration (-1)', 'Reduce [FD] required to sustain by 1.', 'IMBUE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('IMBUEDURATION', 'Duration', 'Commit [FO][FO] to sustain the effects of this power as long as the target remains in range.', 'IMBUE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('IMBUESTRENGTH', 'Strength', 'If no [DA] were used to generate [FP], decrease all Critical Injuries suffered and inflicted by the target by 10 per ranks in Strength.  If no [LI] were used to generate [FP], increase all Critical Injuries suffered and inflicted by 10 per ranks in Strength.', 'IMBUE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('IMBUECONTROL1', 'Control: Skill Ranks', 'Spend [FP] to allow the target to count as having ranks in a skill equal to user''s ranks in the skill while they are affected by this power. The skill must be linked to the characteristic improved by this power.', 'IMBUE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('IMBUERANGE', 'Range', 'Spend [FP][FP] to increase power’s range by a number of range bands equal to Range ranks.', 'IMBUE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('IMBUEMASTERY', 'Mastery', 'The Force user increases characteristics boosted by this power by 2 (max 7) instead of 1 (max 6).', 'IMBUE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('EBBFLOWBASIC', 'Ebb/Flow Basic Power', 'The Force user''s actions empower themselves or sap strength from their foes.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('EBBFLOWMAGNITUDE', 'Magnitude', 'The Force user may spend [FP] to exclude a number of engaged characters equal to number of Magnitude upgrades purchased from being affected by this power.', 'EBBFLOW', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('EBBFLOWRANGE', 'Range', 'Spend [FP][FP] to affect all other characters at short range.', 'EBBFLOW', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('EBBFLOWSTRENGTH', 'Strength', 'The Force user may spend [FP] to increase the strain healed or inflicted by this power by 1.', 'EBBFLOW', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('EBBFLOWCONTROL1', 'Control: Question', 'Once per encounter, spend [FP][FP][FP] to ask a single "yes-or-no" question pertaining to the current events of the game.', 'EBBFLOW', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('EBBFLOWCONTROL2', 'Control: Threat/Advantage', '[B]Ebb:[b] When making a combined Ebb power check, may spend[FP] to add [TH] to all checks made by engaged opponents until the end of the user''s next turn[I](multiple activation not allowed)[i].
