INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('EBBFLOWSTRENGTH3', 'Strength: Failure/Success', 'May spend[FP] to increase the [FA] or [SU] added by 1.', 'EBBFLOW', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('EBBFLOWSTRENGTH2', 'Strength: Threat/Advantage', 'May spend[FP] to increase the [AD] or [TH] added by 1.', 'EBBFLOW', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('EBBFLOWCONTROL4', 'Control: Skill Checks', 'Commit [FO] until the end of the current encounter.  For the remainder of the current encounter, add [FO] to all skill checks.  Each [FP] adds [SU] or [AD].  Each [DA] causes the user 1 strain and adds 1 Conflict as well.', 'EBBFLOW', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('EBBFLOWCONTROL5', 'Mastery (Despair/Triumph)', '[P][B]Ebb:[b] Once per session, if a target suffered at least 5 strain from this power, add [DE] to the target’s next check.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONJUREBASICPOWER', 'REMOVE Conjure Basic Power', 'The Force user calls forth a spectral object to their hand, which lasts for a short time.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONJURECONTROL', 'Control (Offense)', 'Spend [FP] to grant one conjured weapon one of the following qualities: Burn 3, Pierce 3, or Vicious 3. The user can activate this multiple times, granting the weapon an additional quality each time (but may not grant the same quality more than once).', 'CONJURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONJURECONTROL1', 'Control (Defense)', 'Spend [FP] to grant one conjured weapon one of the following qualities: Defensive 1, Deflection 1, or Stun 4. The user can activate this multiple times, granting the weapon an additional quality each time (but may not grant the same quality more than once).', 'CONJURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONJUREDURATION1', 'REMOVE Duration', 'Commit [FO] to sustain 1 conjuration (while it remains in short range) per rank of Duration.', 'CONJURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONJUREDURATION2', 'REMOVE Duration', 'Commit [FO] to sustain one conjuration (while it remains in short range) per rank of Duration.', 'CONJURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
