INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONJURENUMBER2', 'REMOVE Number', 'REMOVE', 'CONJURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONJURERANGE', 'Range', 'Spend [FP] to increase power’s range by a number of range bands equal to Range ranks.', 'CONJURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONJUREMASTERY', 'Mastery', 'Spend [FP][FP][FP] to create a facsimile of a living creature of silhouette 1 or smaller instead of an object. This creature if bound to the user’s willI mindlessly follows the character’s commands until the end of the summoner’s next turn. If the user has a corpse of silhouette 1 or smaller to imbue with false life, this facsimile lasts until the end of the encounter and the character gains 7 Conflict.', 'CONJURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ALTERBASICPOWER', 'REMOVE Alter Basic Power', 'The basic power for Alter allows the user to tap into the living Force of their surroundings, manipulating the nearby environs. The basic power has two uses, both of which can only be used in natural terrain that can change form easily, such as dirt, sand, mud, and thick vegetation.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ALTERCONTROLSURVIVAL', 'Control (Survival)', 'Spend [FP] and make an [B]Average ([DI][DI]) Survival[b] check to instantly locate food, water, and other critical supplies within extreme range. GM may determine that there are no such supplies available (example: the Force user is on an airless moon). The user may not activate this multiple times.', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ALTERCONTROLCONCEALMENT', 'Control (Concealment)', 'The Force user may spend [FP] to give all characters within short range of the Force user concealment, adding [BO] or [SE] to appropriate checks.  This lasts for the duration of the power. The user may not activate this multiple times.', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ALTERCONTROLANIMALS', 'Control (Animals)', 'Spend [FP] to share the senses of non-sentient animals and similar creatures within range of their power. The Force user adds [BO] to Perception and Vigilance checks, and at the GM''s discretion, may be able to learn or notice things they could not normally perceive. This lasts for the duration of the power. The user may not activate this multiple times.', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ALTERCONTROLFIRMTERRAIN', 'Control (Firm Terrain)', 'This power can affect firm natural terrain, such as packed earth, stone, or ice.', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ALTERCONTROLIMPASSIBLETERRAIN', 'Control (Impassible Terrain)', 'Spend [FP][FP] to make a small patch of terrain within the power''s area of effect impassable terrain. This patch is no more than 3 meters across. The nature of the impassible terrain is up to the Force user; it could be a mass of solid rock, an impenetrable morass of twisting underbrush. or a bubbling pit of steam and superheated water. This lasts for the duration of the power. The user may activate this multiple times, choosing a new patch of terrain to affect each time.', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ALTERCONTROLCORROSIVEATMO', 'Control (Corrosive Atmosphere)', 'Spend [FP][FP] to create a corrosive atmosphere in a small area within the power''s area of effect. This area is no more than 3 meters across.  The rating of the corrosive atmosphere is equal to the Force user''s current Force rating. This lasts for the duration of the power. The user may activate this multiple times, choosing a new patch of terrain to affect each time.', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ALTERCONTROLUPGRADEDIFFICULTY)', 'Control (Upgrade Difficulty)', 'Spend [FP][FP] to upgrade the difficulty of all checks made by opponents while in the power''s area of effect once. This lasts for the duration of the power.', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ALTERDURATION', 'Duration', 'Commit [FO] to sustain its effects while user remains in range of the area affected.', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ALTERRANGE1', 'Range', 'Spend [FP][FP] to increase power’s range by a number of range bands equal to Range ranks.', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ALTERRANGE2', 'Range', 'Spend [FP][FP] to increase power’s range by a number of range bands equal to Range ranks.', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ALTERSTRENGTH1', 'Strength', 'Spend [FP] to select a number of targets ranks in Strength: these targets ignore this power''s effects.', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
