INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('PROTUNLMAGNITUDE', 'Magnitude', 'Spend [FP] to affect one additional target in range per rank of Magnitude.', 'PROTUNL', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SEEKDURATION', 'Duration', 'Commit [FO] to continue tracking target even when it moves [I][See Long Text][i]', 'SEEK', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SUPPRESSCONTROL1', 'Control: Commit', 'Ongoing effect: Commit one or more [FO], when an opponent targets the user with a Force power, after the opponent generates [FP], reduce the total [FP] generated by 1 per [FO] committed, to a minimum of 1.', 'SUPPRESS', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('JERINFBASIC', 'Jerserra''s Influence Basic Power', 'The Force user can project terrifying visions onto foes, forcing them to face their greatest fears.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('JERINFCONTROL1', 'Control: Fear', 'When making a fear check, the Force user can roll a [B]Jerserra''s Influence power check[b] as part of the dice pool. The user may spend [FP] to gain [SU] or [AD] (user''s choice) on the check.', 'JERINF', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('JERINFCONTROL2', 'Control: Willpower', 'Commit [FO]. Increase Willpower characteristic by 1 (max of 6).', 'JERINF', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('JERINFCONTROL3', 'Control: Strain', 'If the target suffers strain as a result of this power, the user recovers an equal amount of strain.', 'JERINF', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('JERINFMASTERY1', 'Mastery: Commit', 'Combine with an [B]opposed Discipline vs. Discipline[b] check targeting one character within short range. If the user succeeds on the check and spends [FP], they may commit [FO] and force the target to also commit [FO]. Both dice remain committed until the user uncommits that [FO] or the encounter ends.', 'JERINF', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('JERINFMASTERY2', 'Mastery: Action', 'Once per session, after a target fails a fear check caused by this power, the Force user may have the target perform one action of the Force user''s choice as an out of turn incidental. The Force user gains 3 Conflict.', 'JERINF', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('JERINFRANGE', 'Range', 'Spend [FP] to increase the power''s range by a number of range bands equal to Range upgrades purchased.', 'JERINF', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('JERINFMAGNITUDE', 'Magnitude', 'Spend [FP] to affect one additional target in range per rank of Magnitude.', 'JERINF', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('JERINFSTRENGTH', 'Strength', 'Spend [FP] to increase the difficulty of the fear check by ranks of Strength', 'JERINF', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENDUREBASIC', 'Endure Basic Power', 'When suffering a Critical Injury with a severity no greater than [B]Easy ([DI])[b], may activate Endure as an out-of-turn incidental, committing [FO] to temporarily ignore the effects of that injury (do not apply any results from the Critical Injury or add +10 to further rolls on the Critical Injury Result table while [FO] remains committed, injury can still be healed). When this ongoing effect ends, the character suffers all effects of the Critical Injury (unless it has been treated).', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENDURECONTROL', 'Control', 'The character can committ additional [FO] to temporarily ignore one additional Critical Injury per Control upgrade purchased.', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENDUREDURATION', 'Duration', 'As an incidental, the character can activate Endure to affect a Critical Injury the character is already suffering and which is of a severity that Endure could affect normally.', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENDUREMAGNITUDE', 'Magnitude', 'Can affect allies at short range. Effect ends if the character stops committing [FO] or if the ally is no longer within short range.', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENDUREMASTERY', 'Mastery', 'Make a [B]Discipline[b] check ([DI] equals Severity) and add [FO] up to Force rating. If the check succeeds and generates [FP] equal to the Severity, the Critical Injury is not suffered.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENDURERANGE', 'Range', 'The range at which the character can use Endure to affect allies increases to medium. The ongoing effect ends if the distance between the characters increases beyond medium for any reason.', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENDURESTRENGTHSEVERITY', 'REMOVE Strength: Increase Severity', 'REMOVE', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENDURESTRENGTHDEAD', 'REMOVE Strength: Delay Death', 'REMOVE', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ALTERBASIC', 'Alter Basic Power', 'The basic power for Alter allows the user to tap into the living Force of their surroundings, manipulating the nearby environs. The basic power has two uses, both of which can only be used in natural terrain that can change form easily, such as dirt, sand, mud, and thick vegetation.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONJUREBASIC', 'Conjure Basic Power', 'The Force user calls forth a spectral object to their hand, which lasts for a short time.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ALTERCONTROL3', 'Control: Animal Senses', 'The Force user may spend a [FP] to share the senses of non-sentient animals and similar creatures within range of their power. The Force user adds a [BO] to [B]Perception[b] and [B]Vigilance[b] checks, and at the GM''s discretion, may be able to learn or notice things they could not normally perceive. This lasts for the duration of the power. The user may not activate this multiple times.', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ALTERCONTROL2', 'Control: Concealment', 'The user may spend a [FP] to give all characters within short range of them concealment, adding [SE] or [BO] to appropriate checks. This lasts for the duration of the power. The user may not activate this multiple times.', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ALTERCONTROL6', 'Control: Corrosive Atmosphere', 'The user may spend two [FP] to create a corrosive atmosphere in a small area within the power''s AOE, (no more than 3m wide). The rating of the corrosive atmosphere is equal to the user''s current Force rating. This lasts for the duration of the power. The user may activate this multiple times, choosing a new patch of terrain to affect each time.', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ALTERCONTROL4', 'Control: Firm Terrain', 'This power can affect firm natural terrain, such as packed earth, stone, or ice.', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ALTERCONTROL5', 'Control: Impassible Terrain', 'The Force user may spend two [FP] to make a small patch of terrain within the power''s area of effect impassable terrain.[I][See Long Text][i]', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONJURECONTROL2', 'Control: Offense Qualities', 'Spend a [FP] to grant a conjured weapon one of the following qualities: Burn 3, Pierce 3, or Vicious 3. May activate this power multiple times, granting 1 quality/activation (may not duplicate a quality).[I][See Long Text][i]', 'CONJURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ALTERCONTROL1', 'Control: Survival', 'Spend [FP] to make an [B]Average [DI][DI] Survival[b] check to instantly locate food, water, and other critical supplies within extreme range.', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ALTERCONTROL7', 'Control: Upgrade Difficulty', 'Spend two [FP] to upgrade the difficulty of all checks made by opponents while in Alter’s AoE once.', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONJUREDURATION', 'Duration', 'Commit [FO] to sustain one conjuration (while it remains in short range) per rank of Duration.', 'CONJURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONJUREMAGNITUDE', 'Magnitude', 'Spend a [FP] to increase the maximum encumbrance of the facsimile by 2 per ranks of Magnitude upgrades.', 'CONJURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONJURENUMBER', 'Number', 'Spend [FP][FP] to create additional, identical conjurations equal to ranks in Number.', 'CONJURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ALTERRANGE', 'Range', 'Spend [FP][FP] to increase power’s range by a number of range bands equal to Range ranks.', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ALTERSTRENGTH', 'Strength', 'Spend [FP] to allow a number of targets equal to ranks in Strength to ignore effects.', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENDURESTRENGTH2', 'Strength - Delay Death', 'The character can use endure to temporarily ignore a Critical Injury result of Dead [I][See Long Text][i].', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
